              className="relative p-2 md:p-2.5 bg-slate-50 rounded-xl text-slate-600 hover:text-blue-600 hover:bg-white hover:shadow-md transition-all active:scale-90"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 md:h-6 md:w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" />
              </svg>
              {cartCount > 0 && (
                <span className="absolute -top-1 -right-1 bg-blue-600 text-white text-[9px] md:text-[10px] font-black px-1.5 py-0.5 rounded-full ring-2 ring-white animate-bounce">
                  {cartCount}
                </span>
              )}
            </button>

            {user ? (
              <div className="flex items-center gap-2 md:gap-3 pl-2 md:pl-4 border-l border-slate-200">
                <div className="hidden md:block text-right">
                  <p className="text-[11px] font-black text-slate-900 uppercase tracking-tight">{user.name}</p>
                  <button onClick={onLogout} className="text-[9px] text-slate-400 hover:text-red-500 font-black uppercase tracking-widest">Sign Out</button>
                </div>
                <div 
                   onClick={onLogout}
                   className="w-9 h-9 md:w-10 md:h-10 rounded-xl bg-gradient-to-br from-blue-500 to-green-400 p-[2px] cursor-pointer hover:scale-105 active:scale-95 transition-all shadow-md"
                >
                    <div className="w-full h-full rounded-[10px] bg-white flex items-center justify-center text-xs md:text-sm font-black text-blue-600 uppercase">
                        {user.name.charAt(0)}
                    </div>
                </div>
              </div>
            ) : (
              <div className="flex items-center gap-1 md:gap-2">
                <button 
                  onClick={onAuthClick}
                  className="hidden xs:block text-[10px] md:text-sm font-black text-slate-600 hover:text-blue-600 px-2 md:px-4 py-2 md:py-2.5 transition-all uppercase tracking-widest whitespace-nowrap"
                >
                  Sign In
                </button>
                <button 
                  onClick={onAuthClick}
                  className="text-[10px] md:text-xs font-black bg-slate-900 text-white px-3 md:px-6 py-2.5 md:py-3 rounded-xl hover:bg-blue-600 transition-all shadow-lg shadow-slate-200 uppercase tracking-widest whitespace-nowrap"
                >
                  Sign Up
                </button>
              </div>
            )}
          </div>
        </div>
      </div>
    </nav>
  );
};

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Navbar } from './components/Navbar';
import { ProductCard } from './components/ProductCard';
import { CartDrawer } from './components/CartDrawer';
import { ProductDetail } from './components/ProductDetail';
import { ProductTicker } from './components/ProductTicker';
import { CheckoutView } from './components/CheckoutView';
import { AuthModal } from './components/AuthModal';
import { Product, CartItem, User, View } from './types';
import { INITIAL_PRODUCTS, CATEGORIES } from './constants';
import { supabase } from './supabaseClient';

const App: React.FC = () => {
  // State
  const [products, setProducts] = useState<Product[]>(INITIAL_PRODUCTS);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [currentView, setCurrentView] = useState<View>('shop');
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [searchQuery, setSearchQuery] = useState('');
  const [user, setUser] = useState<User | null>(null);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
  const [authMode, setAuthMode] = useState<'signin' | 'signup' | 'forgot' | 'update'>('signin');
  const [loading, setLoading] = useState(true);

  const shopSectionRef = useRef<HTMLDivElement>(null);

  // Initialize Auth & Fetch Products
  useEffect(() => {
    const initialize = async () => {
      // 1. Check current session
      const { data: { session } } = await supabase.auth.getSession();
      if (session?.user) {
        setUser({
          id: session.user.id,
          name: session.user.user_metadata.full_name || session.user.email?.split('@')[0] || 'User',
          email: session.user.email || '',
          isAdmin: false
        });
      }

      // 2. Listen for auth changes
      const { data: { subscription } } = supabase.auth.onAuthStateChange((event, session) => {
        if (event === 'PASSWORD_RECOVERY') {
          setAuthMode('update');
          setIsAuthModalOpen(true);
        }

        if (session?.user) {
          setUser({
            id: session.user.id,
            name: session.user.user_metadata.full_name || session.user.email?.split('@')[0] || 'User',
            email: session.user.email || '',
            isAdmin: false
          });
        } else {
          setUser(null);
        }
      });

      // 3. Fetch Products from Supabase
      try {
        const { data: dbProducts, error } = await supabase
          .from('products')
          .select('*')
          .order('name', { ascending: true });

        if (!error && dbProducts && dbProducts.length > 0) {
          setProducts(dbProducts);
        }
      } catch (err) {
        console.error("Failed to fetch products from Supabase, using defaults.");
      } finally {
        setLoading(false);
      }

      return () => subscription.unsubscribe();
    };

    initialize();
  }, []);

  // Computed
  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const matchesCategory = selectedCategory === 'All' || p.category === selectedCategory;
      const matchesSearch = p.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                           p.description.toLowerCase().includes(searchQuery.toLowerCase());
      return matchesCategory && matchesSearch;
    });
  }, [products, selectedCategory, searchQuery]);

  const cartCount = useMemo(() => cart.reduce((sum, item) => sum + item.quantity, 0), [cart]);

  // Handlers
  const handleAddToCart = (product: Product, quantity: number = 1) => {
    if (!user) {
      setAuthMode('signin');
      setIsAuthModalOpen(true);
      return;
    }

    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        return prev.map(item => item.id === product.id ? { ...item, quantity: item.quantity + quantity } : item);
      }
      return [...prev, { ...product, quantity }];
    });
    setIsCartOpen(true);
  };

  const handleUpdateQuantity = (id: string, q: number) => {
    const validQ = Math.max(1, q);
    setCart(prev => prev.map(item => item.id === id ? { ...item, quantity: validQ } : item));
  };

  const handleRemoveFromCart = (id: string) => {
    setCart(prev => prev.filter(item => item.id !== id));
  };

  const handleViewDetails = (product: Product) => {
    setSelectedProduct(product);
    setCurrentView('product-detail');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleProceedToCheckout = () => {
    if (!user) {
      setIsCartOpen(false);
      setAuthMode('signin');
      setIsAuthModalOpen(true);
      return;
    }
    setIsCartOpen(false);
    setCurrentView('checkout');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setUser(null);
    setCart([]);
    resetToShop();
  };

  const resetToShop = () => {
    setCurrentView('shop');
    setSelectedProduct(null);
    setSelectedCategory('All');
    setSearchQuery('');
  };

  const scrollToShop = () => {
    resetToShop();
    setTimeout(() => {
        shopSectionRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }, 50);
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-[#F8FAFC]">
        <div className="flex flex-col items-center gap-6 text-center">
