                <circle cx="50" cy="50" r="46" fill="none" stroke="#2563eb" stroke-width="2" stroke-dasharray="20 10" />
                <circle cx="50" cy="50" r="38" fill="none" stroke="#22c55e" stroke-width="2" stroke-dasharray="10 20" />
            </svg>
            <div className="absolute inset-0 flex items-center justify-center font-black text-xl">
              <span className="text-blue-600">D</span>
              <span className="text-green-500">S</span>
            </div>
          </div>
          <div className="space-y-1">
            <p className="text-slate-900 font-black uppercase tracking-[0.3em] text-sm">DS <span className="font-normal text-slate-500">SERVICE STORE</span></p>
            <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest animate-pulse">Initializing System...</p>
          </div>
        </div>
      </div>
    );
  }

  return (
