export interface Order {
  id: string;
  userId: string;
  userName: string;
  userEmail: string;
  userWhatsapp: string;
  items: CartItem[];
  total: number;
  paymentMethod: 'crypto' | 'ssl';
  transactionId: string;
  screenshotUrl: string;
  status: 'pending' | 'verified' | 'delivered';
  createdAt: string;
}

export type View = 'shop' | 'product-detail' | 'checkout' | 'cart' | 'admin';

import React, { useState, useRef } from 'react';
import { CartItem, Order } from '../types';

interface CheckoutViewProps {
  items: CartItem[];
  onBack: () => void;
  onSuccess: (orderData: Partial<Order>) => void;
}

type CheckoutStep = 'details' | 'proof';

export const CheckoutView: React.FC<CheckoutViewProps> = ({ items, onBack, onSuccess }) => {
  const [paymentMethod, setPaymentMethod] = useState<'crypto' | 'ssl'>('crypto');
  const [step, setStep] = useState<CheckoutStep>('details');
  const [isProcessing, setIsProcessing] = useState(false);
  const [copiedId, setCopiedId] = useState<string | null>(null);

  // Details fields
  const [custName, setCustName] = useState('');
  const [custWhatsapp, setCustWhatsapp] = useState('');
  const [custEmail, setCustEmail] = useState('');

  // Proof fields
  const [transactionId, setTransactionId] = useState('');
  const [screenshot, setScreenshot] = useState<File | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const binancePayId = "573432978";
  const bdNumber = "01946406095";
  const USD_TO_BDT_RATE = 125;

  const subtotal = items.reduce((sum, item) => sum + (item.price * item.quantity), 0);
  const totalQuantity = items.reduce((sum, item) => sum + item.quantity, 0);
  const isDiscountEligible = totalQuantity >= 100;
  const discount = isDiscountEligible ? subtotal * 0.05 : 0;
  const total = subtotal - discount;

  const handleProceedToProof = () => {
    if (!custName || !custWhatsapp || !custEmail) {
      alert("Please fill in your delivery information first.");
      return;
    }
    setStep('proof');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleFinalSubmit = () => {
    if (!transactionId) {
      alert(`Please enter your ${paymentMethod === 'crypto' ? 'Binance TxID' : 'Transaction ID'}.`);
      return;
    }
    if (!screenshot) {
      alert('Please upload a screenshot of your payment for verification.');
      return;
    }

    setIsProcessing(true);

    // Simulate screenshot URL generation
    const mockScreenshotUrl = URL.createObjectURL(screenshot);

    const orderData: Partial<Order> = {
      userName: custName,
      userWhatsapp: custWhatsapp,
      userEmail: custEmail,
      items: items,
      total: total,
      paymentMethod: paymentMethod,
      transactionId: transactionId,
      screenshotUrl: mockScreenshotUrl,
      status: 'pending',
      createdAt: new Date().toISOString()
    };

    setTimeout(() => {
      setIsProcessing(false);
      onSuccess(orderData);
    }, 2500);
  };

  const copyToClipboard = (text: string, id: string) => {
    navigator.clipboard.writeText(text);
    setCopiedId(id);
    setTimeout(() => setCopiedId(null), 2000);
  };

  const formatPrice = (amount: number) => {
    if (paymentMethod === 'ssl') {
      return `${Math.ceil(amount * USD_TO_BDT_RATE).toLocaleString()} ৳`;
    }
    return `$${amount.toFixed(2)}`;
  };

  if (items.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-20 text-center bg-white rounded-[3rem] border border-slate-200">
        <h2 className="text-2xl font-black text-slate-900 mb-4">Your cart is empty</h2>
        <button onClick={onBack} className="bg-slate-900 text-white px-8 py-3 rounded-2xl font-bold transition-all hover:scale-105 active:scale-95">
          Return to Shop
        </button>
      </div>
    );
  }

  return (
    <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 max-w-5xl mx-auto">
      <div className="flex items-center gap-4 mb-8">
        <button onClick={step === 'proof' ? () => setStep('details') : onBack} className="p-2 hover:bg-white rounded-full transition-colors group">
          <svg className="w-6 h-6 text-slate-400 group-hover:text-slate-900" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 19l-7-7 7-7" />
          </svg>
        </button>
        <h1 className="text-3xl font-black text-slate-900 uppercase tracking-tighter">
          {step === 'details' ? 'Secure Checkout' : 'Submit Payment Proof'}
        </h1>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
        <div className="lg:col-span-7 space-y-8">
          {step === 'details' ? (
            <div className="bg-white rounded-[2.5rem] border border-slate-200 p-8 md:p-10 shadow-sm">
              <h2 className="text-xl font-black text-slate-900 mb-8 flex items-center gap-3">
                <span className="flex items-center justify-center w-8 h-8 rounded-full bg-slate-100 text-slate-600 text-sm font-black">1</span>
                Select Payment Method
              </h2>

              <div className="grid grid-cols-1 gap-4">
                <div className="space-y-4">
                  <button onClick={() => setPaymentMethod('crypto')} className={`w-full flex items-center justify-between p-6 rounded-2xl border-2 transition-all ${paymentMethod === 'crypto' ? 'border-blue-600 bg-blue-50/30' : 'border-slate-100'}`}>
                    <div className="flex items-center gap-4 text-left">
                       <div className="w-12 h-12 bg-amber-400 rounded-xl flex items-center justify-center font-black text-white">B</div>
                       <div>
                         <p className="font-black text-slate-900 uppercase text-sm tracking-widest">Binance Pay</p>
                         <p className="text-[10px] font-bold text-slate-400 uppercase">Global Settlement</p>
                       </div>
                    </div>
                    <div className={`w-6 h-6 rounded-full border-2 ${paymentMethod === 'crypto' ? 'bg-blue-600 border-blue-600' : 'border-slate-200'}`} />
                  </button>
                  {paymentMethod === 'crypto' && (
                    <div className="bg-slate-900 p-6 rounded-2xl text-white">
                       <div className="flex justify-between items-center mb-3">
                         <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Send to Pay ID</span>
                         <span className="text-cyan-400 font-black tracking-widest">{binancePayId}</span>
                       </div>
                       <button onClick={() => copyToClipboard(binancePayId, 'binance')} className="w-full py-3 bg-white/10 hover:bg-white/20 rounded-xl text-xs font-black uppercase tracking-widest transition-all">
                         {copiedId === 'binance' ? 'Copied ID' : 'Copy Pay ID'}
                       </button>
                    </div>
                  )}
                </div>

                <div className="space-y-4">
                  <button onClick={() => setPaymentMethod('ssl')} className={`w-full flex items-center justify-between p-6 rounded-2xl border-2 transition-all ${paymentMethod === 'ssl' ? 'border-blue-600 bg-blue-50/30' : 'border-slate-100'}`}>
                    <div className="flex items-center gap-4 text-left">
                       <div className="w-12 h-12 bg-pink-500 rounded-xl flex items-center justify-center font-black text-white">B</div>
                       <div>
                         <p className="font-black text-slate-900 uppercase text-sm tracking-widest">Only Bangladeshi User</p>
                         <p className="text-[10px] font-bold text-slate-400 uppercase">Bkash / Nagad</p>
                       </div>
                    </div>
                    <div className={`w-6 h-6 rounded-full border-2 ${paymentMethod === 'ssl' ? 'bg-blue-600 border-blue-600' : 'border-slate-200'}`} />
                  </button>
                  {paymentMethod === 'ssl' && (
                    <div className="bg-slate-900 p-6 rounded-2xl text-white space-y-4">
                       <div className="flex justify-between items-center">
                         <span className="text-[10px] font-black text-pink-500 uppercase">Bkash / Nagad Number</span>
                         <span className="text-white font-black tracking-widest">{bdNumber}</span>
                       </div>
                       <div className="flex gap-2">
                         <button onClick={() => copyToClipboard(bdNumber, 'bkash')} className="flex-1 py-3 bg-pink-600 hover:bg-pink-700 rounded-xl text-xs font-black uppercase tracking-widest transition-all">Bkash</button>
                         <button onClick={() => copyToClipboard(bdNumber, 'nagad')} className="flex-1 py-3 bg-orange-600 hover:bg-orange-700 rounded-xl text-xs font-black uppercase tracking-widest transition-all">Nagad</button>
                       </div>
                    </div>
                  )}
                </div>
              </div>

              <div className="mt-10 pt-10 border-t border-slate-100">
                  <h2 className="text-xl font-black text-slate-900 mb-8 flex items-center gap-3">
                      <span className="flex items-center justify-center w-8 h-8 rounded-full bg-slate-100 text-slate-600 text-sm font-black">2</span>
                      Delivery Details
                  </h2>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <input value={custName} onChange={e => setCustName(e.target.value)} type="text" placeholder="Full Name" className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none focus:ring-2 focus:ring-blue-600 font-bold" />
                      <input value={custWhatsapp} onChange={e => setCustWhatsapp(e.target.value)} type="text" placeholder="Whatsapp Number" className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none focus:ring-2 focus:ring-blue-600 font-bold" />
                      <input value={custEmail} onChange={e => setCustEmail(e.target.value)} type="email" placeholder="Delivery Email" className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none focus:ring-2 focus:ring-blue-600 font-bold md:col-span-2" />
                  </div>
              </div>
            </div>
          ) : (
            <div className="bg-white rounded-[2.5rem] border border-slate-200 p-8 md:p-10 shadow-sm animate-in slide-in-from-right duration-500">
              <div className="text-center mb-8">
                <h2 className="text-2xl font-black text-slate-900 mb-2 uppercase tracking-tighter">Submit Proof</h2>
                <p className="text-slate-500 font-bold text-xs uppercase tracking-widest">Verify your transaction to receive accounts</p>
              </div>

              <div className="space-y-6">
                <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 block ml-1">Transaction ID / TxID</label>
                  <input value={transactionId} onChange={(e) => setTransactionId(e.target.value)} type="text" placeholder="Enter TxID here..." className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none focus:ring-2 focus:ring-blue-600 font-black text-lg tracking-widest" />
                </div>

                <div 
                  onClick={() => fileInputRef.current?.click()}
                  className={`group h-48 border-2 border-dashed rounded-[2rem] flex flex-col items-center justify-center transition-all cursor-pointer ${screenshot ? 'border-blue-600 bg-blue-50' : 'border-slate-200 hover:border-blue-400'}`}
                >
                  {screenshot ? (
                    <p className="font-black text-blue-600 uppercase text-xs">Proof Attached: {screenshot.name}</p>
                  ) : (
                    <>
                      <p className="font-black text-slate-900 uppercase text-xs">Upload Payment Screenshot</p>
                      <p className="text-[9px] font-bold text-slate-400 uppercase mt-2">JPG or PNG allowed</p>
                    </>
                  )}
                  <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={(e) => setScreenshot(e.target.files?.[0] || null)} />
