        <div className="lg:col-span-5">
          <div className="bg-slate-900 rounded-[2.5rem] p-8 md:p-10 text-white shadow-2xl sticky top-24">
            <h2 className="text-2xl font-black uppercase tracking-tighter mb-8 border-b border-white/10 pb-4">Invoice</h2>
            <div className="space-y-6 mb-8 max-h-[250px] overflow-y-auto pr-2">
              {items.map(item => (
                <div key={item.id} className="flex justify-between items-center text-xs font-bold">
                  <span className="text-slate-400">{item.quantity}x <span className="text-white font-black">{item.name}</span></span>
                  <span>{formatPrice(item.price * item.quantity)}</span>
