import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Navbar } from './components/Navbar';
import { ProductCard } from './components/ProductCard';
import { CartDrawer } from './components/CartDrawer';
import { ProductDetail } from './components/ProductDetail';
import { ProductTicker } from './components/ProductTicker';
import { CheckoutView } from './components/CheckoutView';
import { AuthModal } from './components/AuthModal';
import { AdminPanel } from './components/AdminPanel';
import { Product, CartItem, User, View, Order } from './types';
import { INITIAL_PRODUCTS, CATEGORIES } from './constants';
import { supabase } from './supabaseClient';

const App: React.FC = () => {
  // State
  const [products, setProducts] = useState<Product[]>(INITIAL_PRODUCTS);
  const [orders, setOrders] = useState<Order[]>([]);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [currentView, setCurrentView] = useState<View>('shop');
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [searchQuery, setSearchQuery] = useState('');
  const [user, setUser] = useState<User | null>(null);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
  const [authMode, setAuthMode] = useState<'signin' | 'signup' | 'forgot' | 'update'>('signin');
  const [loading, setLoading] = useState(true);

  const shopSectionRef = useRef<HTMLDivElement>(null);

  // Initialize Auth & Fetch Products
  useEffect(() => {
    const initialize = async () => {
      const { data: { session } } = await supabase.auth.getSession();
      if (session?.user) {
        setUser({
          id: session.user.id,
          name: session.user.user_metadata.full_name || session.user.email?.split('@')[0] || 'User',
          email: session.user.email || '',
          isAdmin: session.user.email === 'mehedihasanajmir1000@gmail.com' // Set based on owner email
        });
      }

      const { data: { subscription } } = supabase.auth.onAuthStateChange((event, session) => {
        if (session?.user) {
          setUser({
            id: session.user.id,
            name: session.user.user_metadata.full_name || session.user.email?.split('@')[0] || 'User',
            email: session.user.email || '',
            isAdmin: session.user.email === 'mehedihasanajmir1000@gmail.com'
          });
        } else {
          setUser(null);
        }
      });

      try {
        const { data: dbProducts } = await supabase.from('products').select('*').order('name', { ascending: true });
        if (dbProducts && dbProducts.length > 0) setProducts(dbProducts);
      } catch (err) {
        console.error("Supabase fail, defaults loaded.");
      } finally {
        setLoading(false);
      }

      return () => subscription.unsubscribe();
    };
    initialize();
  }, []);

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const matchesCategory = selectedCategory === 'All' || p.category === selectedCategory;
      const matchesSearch = p.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                           p.description.toLowerCase().includes(searchQuery.toLowerCase());
      return matchesCategory && matchesSearch;
    });
  }, [products, selectedCategory, searchQuery]);

  const cartCount = useMemo(() => cart.reduce((sum, item) => sum + item.quantity, 0), [cart]);

  const handleAddToCart = (product: Product, quantity: number = 1) => {
    if (!user) { setAuthMode('signin'); setIsAuthModalOpen(true); return; }
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) return prev.map(item => item.id === product.id ? { ...item, quantity: item.quantity + quantity } : item);
      return [...prev, { ...product, quantity }];
    });
    setIsCartOpen(true);
  };

  const handleOrderSuccess = (orderData: Partial<Order>) => {
    const newOrder: Order = {
      id: Math.random().toString(36).substr(2, 9),
      userId: user?.id || 'guest',
      ...orderData
    } as Order;

    setOrders(prev => [newOrder, ...prev]);
    alert('Payment Received! Our team is verifying your transaction. You will receive an email shortly.');
    setCart([]);
    resetToShop();
  };

  const updateOrderStatus = (id: string, status: Order['status']) => {
    setOrders(prev => prev.map(o => o.id === id ? { ...o, status } : o));
  };

  const resetToShop = () => { setCurrentView('shop'); setSelectedProduct(null); setSelectedCategory('All'); setSearchQuery(''); };

  const handleAddProduct = async (p: Omit<Product, 'id'>) => {
    const newP = { id: Date.now().toString(), ...p, rating: 5 };
    setProducts([newP, ...products]);
  };

  const handleDeleteProduct = (id: string) => setProducts(products.filter(p => p.id !== id));

  if (loading) return (
    <div className="min-h-screen flex items-center justify-center bg-white font-black uppercase tracking-widest text-slate-900">
      Loading Systems...
    </div>
  );

  return (
    <div className="min-h-screen flex flex-col bg-[#F8FAFC]">
      <Navbar currentView={currentView} setView={resetToShop} cartCount={cartCount} user={user} onLogout={() => setUser(null)} onAuthClick={() => { setAuthMode('signin'); setIsAuthModalOpen(true); }} />

      {currentView === 'shop' && <ProductTicker products={products} onProductClick={(p) => { setSelectedProduct(p); setCurrentView('product-detail'); }} />}

      <main className="flex-1 max-w-7xl mx-auto w-full px-4 sm:px-6 lg:px-8 py-8">
        {currentView === 'shop' ? (
          <div className="space-y-12">
            {/* HERO REMOVED FOR BREVITY IN SNIPPET, RETAINING CORE LOGIC */}
            <div className="flex justify-between items-center bg-white p-6 rounded-3xl border border-slate-200">
                <div className="flex gap-2 overflow-x-auto no-scrollbar">
                    {CATEGORIES.map(cat => (
                        <button key={cat} onClick={() => setSelectedCategory(cat)} className={`px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${selectedCategory === cat ? 'bg-slate-900 text-white shadow-lg' : 'bg-slate-50 text-slate-500 hover:text-slate-900'}`}>{cat}</button>
                    ))}
                </div>
                <input type="text" placeholder="Search..." className="hidden lg:block w-64 px-5 py-2.5 bg-slate-50 rounded-xl border border-slate-200 outline-none text-xs font-bold" value={searchQuery} onChange={e => setSearchQuery(e.target.value)} />
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8">
              {filteredProducts.map(product => (
                <ProductCard key={product.id} product={product} onAddToCart={handleAddToCart} onViewDetails={(p) => { setSelectedProduct(p); setCurrentView('product-detail'); }} />
              ))}
            </div>
          </div>
        ) : currentView === 'product-detail' && selectedProduct ? (
          <ProductDetail product={selectedProduct} onAddToCart={handleAddToCart} onBack={resetToShop} />
        ) : currentView === 'checkout' ? (
          <CheckoutView items={cart} onBack={resetToShop} onSuccess={handleOrderSuccess} />
        ) : currentView === 'admin' ? (
          <AdminPanel products={products} orders={orders} onAddProduct={handleAddProduct} onDeleteProduct={handleDeleteProduct} onUpdateOrderStatus={updateOrderStatus} onBack={resetToShop} />
        ) : null}
      </main>

      <footer className="bg-slate-950 text-white/50 py-16">
        <div className="max-w-7xl mx-auto px-8 flex flex-col md:flex-row justify-between items-center gap-10">
            <div className="text-center md:text-left">
                <h3 className="text-white text-xl font-black uppercase tracking-tight">DS <span className="font-light text-slate-500">SERVICE STORE</span></h3>
                <p className="text-xs font-bold mt-2">Trusted Premium Digital Ecosystem Since 2005.</p>
            </div>
            {user?.isAdmin && (
                <button onClick={() => setCurrentView('admin')} className="px-8 py-4 bg-blue-600 text-white rounded-2xl font-black text-xs uppercase tracking-[0.2em] shadow-xl shadow-blue-500/20 hover:scale-105 active:scale-95 transition-all">
                    Open Dashboard Panel
                </button>
            )}
            <div className="text-[9px] font-bold text-slate-700 tracking-[0.2em]">© ALL RIGHTS RESERVED BY DS STORE TEAM.</div>
        </div>
      </footer>

      <CartDrawer isOpen={isCartOpen} onClose={() => setIsCartOpen(false)} items={cart} onRemove={(id) => setCart(cart.filter(i => i.id !== id))} onUpdateQuantity={(id, q) => setCart(cart.map(i => i.id === id ? {...i, quantity: q} : i))} onCheckout={() => { setIsCartOpen(false); setCurrentView('checkout'); }} />
      <AuthModal isOpen={isAuthModalOpen} initialMode={authMode} onClose={() => setIsAuthModalOpen(false)} onLogin={(u) => setUser(u)} />
    </div>
  );
};

export default App;

