  useEffect(() => {
    if (user?.isAdmin) {
      const fetchOrders = async () => {
        const { data, error } = await supabase
          .from('orders')
          .select('*')
          .order('createdAt', { ascending: false });

        if (data) setOrders(data);
      };
      fetchOrders();
    }
  }, [user, currentView]);

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const matchesCategory = selectedCategory === 'All' || p.category === selectedCategory;
      const matchesSearch = p.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                           p.description.toLowerCase().includes(searchQuery.toLowerCase());
      return matchesCategory && matchesSearch;
    });
  }, [products, selectedCategory, searchQuery]);

  const cartCount = useMemo(() => cart.reduce((sum, item) => sum + item.quantity, 0), [cart]);

  const handleAddToCart = (product: Product, quantity: number = 1) => {
    if (!user) { setAuthMode('signin'); setIsAuthModalOpen(true); return; }
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) return prev.map(item => item.id === product.id ? { ...item, quantity: item.quantity + quantity } : item);
      return [...prev, { ...product, quantity }];
    });
    setIsCartOpen(true);
  };

  const handleOrderSuccess = async (orderData: Partial<Order>) => {
    const newOrder = {
      userId: user?.id || 'guest',
      ...orderData
    };

    // Save to Supabase
    const { error } = await supabase.from('orders').insert([newOrder]);

    if (!error) {
      alert('Order placed successfully! Our admin will verify your payment soon.');
      setCart([]);
      resetToShop();
    } else {
      console.error("Order save error:", error);
      alert('Order placed, but failed to sync. Please keep your screenshot safe.');
    }
  };

  const updateOrderStatus = async (id: string, status: Order['status']) => {
    const { error } = await supabase
      .from('orders')
      .update({ status })
      .eq('id', id);

    if (!error) {
      setOrders(prev => prev.map(o => o.id === id ? { ...o, status } : o));
    }
  };

  const resetToShop = () => { setCurrentView('shop'); setSelectedProduct(null); setSelectedCategory('All'); setSearchQuery(''); };

  const handleAddProduct = async (p: Omit<Product, 'id'>) => {
    const newP = { ...p, rating: 5 };
    const { data, error } = await supabase.from('products').insert([newP]).select();
    if (data) setProducts([...data, ...products]);
  };

  const handleDeleteProduct = async (id: string) => {
    const { error } = await supabase.from('products').delete().eq('id', id);
    if (!error) setProducts(products.filter(p => p.id !== id));
  };

  if (loading) return (
    <div className="min-h-screen flex items-center justify-center bg-white">
        <div className="flex flex-col items-center gap-4">
            <div className="w-12 h-12 border-4 border-slate-900 border-t-blue-600 rounded-full animate-spin"></div>
            <p className="text-xs font-black uppercase tracking-widest text-slate-900">Loading Store Systems...</p>
        </div>
    </div>
  );

  return (
    <div className="min-h-screen flex flex-col bg-[#F8FAFC]">
      <Navbar currentView={currentView} setView={resetToShop} cartCount={cartCount} user={user} onLogout={() => supabase.auth.signOut()} onAuthClick={() => { setAuthMode('signin'); setIsAuthModalOpen(true); }} />

      {currentView === 'shop' && <ProductTicker products={products} onProductClick={(p) => { setSelectedProduct(p); setCurrentView('product-detail'); }} />}

      <main className="flex-1 max-w-7xl mx-auto w-full px-4 sm:px-6 lg:px-8 py-8">
        {currentView === 'shop' ? (
          <div className="space-y-12">
            <div className="flex flex-col lg:flex-row gap-4 items-center justify-between bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
                <div className="flex gap-2 overflow-x-auto no-scrollbar w-full lg:w-auto">
                    {CATEGORIES.map(cat => (
                        <button key={cat} onClick={() => setSelectedCategory(cat)} className={`px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all whitespace-nowrap ${selectedCategory === cat ? 'bg-slate-900 text-white shadow-lg' : 'bg-slate-50 text-slate-500 hover:text-slate-900'}`}>{cat}</button>
                    ))}
                </div>
                <div className="relative w-full lg:w-72">
                    <input type="text" placeholder="Search products..." className="w-full px-5 py-3 bg-slate-50 rounded-xl border border-slate-200 outline-none text-xs font-bold" value={searchQuery} onChange={e => setSearchQuery(e.target.value)} />
                </div>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8">
              {filteredProducts.map(product => (
                <ProductCard key={product.id} product={product} onAddToCart={handleAddToCart} onViewDetails={(p) => { setSelectedProduct(p); setCurrentView('product-detail'); }} />
              ))}
            </div>
          </div>
        ) : currentView === 'product-detail' && selectedProduct ? (
          <ProductDetail product={selectedProduct} onAddToCart={handleAddToCart} onBack={resetToShop} />
        ) : currentView === 'checkout' ? (
          <CheckoutView items={cart} onBack={resetToShop} onSuccess={handleOrderSuccess} />
        ) : currentView === 'admin' ? (
          <AdminPanel products={products} orders={orders} onAddProduct={handleAddProduct} onDeleteProduct={handleDeleteProduct} onUpdateOrderStatus={updateOrderStatus} onBack={resetToShop} />
        ) : null}
      </main>

      <footer className="bg-slate-950 text-white/50 py-16 mt-auto">
        <div className="max-w-7xl mx-auto px-8 flex flex-col md:flex-row justify-between items-center gap-10">
            <div className="text-center md:text-left">
                <h3 className="text-white text-xl font-black uppercase tracking-tight">DS <span className="font-light text-slate-500">SERVICE STORE</span></h3>
                <p className="text-xs font-bold mt-2">Verified Premium Digital Ecosystem Since 2005.</p>
            </div>
            {user?.isAdmin && (
                <button onClick={() => setCurrentView('admin')} className="px-8 py-4 bg-blue-600 text-white rounded-2xl font-black text-xs uppercase tracking-[0.2em] shadow-xl shadow-blue-500/20 hover:scale-105 active:scale-95 transition-all">
                    Open Owner Dashboard
                </button>
            )}
            <div className="flex flex-col items-center md:items-end gap-1">
                <div className="text-[9px] font-bold text-slate-700 tracking-[0.2em] uppercase">© 2005-2024 DS SERVICE STORE</div>
                <div className="text-[8px] font-black text-slate-800 uppercase tracking-widest">Designed for high performance business</div>
            </div>
        </div>
      </footer>

      <CartDrawer isOpen={isCartOpen} onClose={() => setIsCartOpen(false)} items={cart} onRemove={(id) => setCart(cart.filter(i => i.id !== id))} onUpdateQuantity={(id, q) => setCart(cart.map(i => i.id === id ? {...i, quantity: q} : i))} onCheckout={() => { setIsCartOpen(false); setCurrentView('checkout'); }} />
      <AuthModal isOpen={isAuthModalOpen} initialMode={authMode} onClose={() => setIsAuthModalOpen(false)} onLogin={(u) => setUser(u)} />
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { CartItem, Order } from '../types';

interface CheckoutViewProps {
  items: CartItem[];
  onBack: () => void;
  onSuccess: (orderData: Partial<Order>) => void;
}

type CheckoutStep = 'details' | 'proof';

export const CheckoutView: React.FC<CheckoutViewProps> = ({ items, onBack, onSuccess }) => {
  const [paymentMethod, setPaymentMethod] = useState<'crypto' | 'ssl'>('crypto');
  const [step, setStep] = useState<CheckoutStep>('details');
  const [isProcessing, setIsProcessing] = useState(false);
  const [copiedId, setCopiedId] = useState<string | null>(null);

  // Details fields
  const [custName, setCustName] = useState('');
  const [custWhatsapp, setCustWhatsapp] = useState('');
  const [custEmail, setCustEmail] = useState('');

  // Proof fields
  const [transactionId, setTransactionId] = useState('');
  const [screenshot, setScreenshot] = useState<File | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const binancePayId = "573432978";
  const bdNumber = "01946406095";
  const USD_TO_BDT_RATE = 125;

  const subtotal = items.reduce((sum, item) => sum + (item.price * item.quantity), 0);
  const totalQuantity = items.reduce((sum, item) => sum + item.quantity, 0);
  const isDiscountEligible = totalQuantity >= 100;
  const discount = isDiscountEligible ? subtotal * 0.05 : 0;
  const total = subtotal - discount;

  const handleProceedToProof = () => {
    if (!custName || !custWhatsapp || !custEmail) {
      alert("Please fill in your delivery information first.");
      return;
    }
    setStep('proof');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => resolve(reader.result as string);
      reader.onerror = (error) => reject(error);
    });
  };

  const handleFinalSubmit = async () => {
    if (!transactionId) {
      alert(`Please enter your ${paymentMethod === 'crypto' ? 'Binance TxID' : 'Transaction ID'}.`);
      return;
    }
    if (!screenshot) {
      alert('Please upload a screenshot of your payment for verification.');
      return;
    }

    setIsProcessing(true);

    try {
      const screenshotBase64 = await fileToBase64(screenshot);

      const orderData: Partial<Order> = {
        userName: custName,
        userWhatsapp: custWhatsapp,
        userEmail: custEmail,
        items: items,
        total: total,
        paymentMethod: paymentMethod,
        transactionId: transactionId,
        screenshotUrl: screenshotBase64,
        status: 'pending',
        createdAt: new Date().toISOString()
      };

      onSuccess(orderData);
    } catch (err) {
      console.error("Screenshot conversion error:", err);
      alert("Failed to process image. Please try a smaller file.");
    } finally {
      setIsProcessing(false);
    }
  };

  const copyToClipboard = (text: string, id: string) => {
    navigator.clipboard.writeText(text);
    setCopiedId(id);
    setTimeout(() => setCopiedId(null), 2000);
  };

  const formatPrice = (amount: number) => {
    if (paymentMethod === 'ssl') {
      return `${Math.ceil(amount * USD_TO_BDT_RATE).toLocaleString()} ৳`;
    }
    return `$${amount.toFixed(2)}`;
  };

  return (
    <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 max-w-5xl mx-auto">
      <div className="flex items-center gap-4 mb-8">
        <button onClick={step === 'proof' ? () => setStep('details') : onBack} className="p-2 hover:bg-white rounded-full transition-colors group">
          <svg className="w-6 h-6 text-slate-400 group-hover:text-slate-900" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 19l-7-7 7-7" />
          </svg>
        </button>
        <h1 className="text-3xl font-black text-slate-900 uppercase tracking-tighter">
          {step === 'details' ? 'Secure Checkout' : 'Submit Payment Proof'}
        </h1>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-10 pb-20">
        <div className="lg:col-span-7 space-y-8">
          {step === 'details' ? (
            <div className="bg-white rounded-[2.5rem] border border-slate-200 p-8 md:p-10 shadow-sm">
              <h2 className="text-xl font-black text-slate-900 mb-8 flex items-center gap-3">
                <span className="flex items-center justify-center w-8 h-8 rounded-full bg-slate-100 text-slate-600 text-sm font-black">1</span>
                Payment Method
              </h2>

              <div className="grid grid-cols-1 gap-4">
                <button onClick={() => setPaymentMethod('crypto')} className={`w-full flex items-center justify-between p-6 rounded-2xl border-2 transition-all ${paymentMethod === 'crypto' ? 'border-blue-600 bg-blue-50/30' : 'border-slate-100'}`}>
                  <div className="flex items-center gap-4">
                    <div className="w-12 h-12 bg-amber-400 rounded-xl flex items-center justify-center font-black text-white">B</div>
                    <div className="text-left">
                      <p className="font-black text-slate-900 uppercase text-xs tracking-widest">Binance Pay</p>
                      <p className="text-[10px] font-bold text-slate-400 uppercase">Universal Crypto</p>
                    </div>
                  </div>
                  <div className={`w-5 h-5 rounded-full border-2 ${paymentMethod === 'crypto' ? 'bg-blue-600 border-blue-600' : 'border-slate-200'}`} />
                </button>

                <button onClick={() => setPaymentMethod('ssl')} className={`w-full flex items-center justify-between p-6 rounded-2xl border-2 transition-all ${paymentMethod === 'ssl' ? 'border-pink-500 bg-pink-50/30' : 'border-slate-100'}`}>
                  <div className="flex items-center gap-4">
                    <div className="w-12 h-12 bg-pink-500 rounded-xl flex items-center justify-center font-black text-white">৳</div>
                    <div className="text-left">
                      <p className="font-black text-slate-900 uppercase text-xs tracking-widest">Bkash / Nagad</p>
                      <p className="text-[10px] font-bold text-slate-400 uppercase">Only for BD Users</p>
                    </div>
                  </div>
                  <div className={`w-5 h-5 rounded-full border-2 ${paymentMethod === 'ssl' ? 'bg-pink-500 border-pink-500' : 'border-slate-200'}`} />
                </button>
              </div>

              {paymentMethod === 'crypto' && (
                <div className="mt-6 bg-slate-900 p-6 rounded-2xl text-white">
                  <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Send USDT via Binance Pay</p>
                  <div className="flex justify-between items-center bg-white/5 p-4 rounded-xl">
                    <span className="font-mono text-cyan-400 font-bold tracking-widest">{binancePayId}</span>
                    <button onClick={() => copyToClipboard(binancePayId, 'binance')} className="text-[10px] font-black uppercase text-white hover:text-cyan-400">
                      {copiedId === 'binance' ? 'Copied' : 'Copy'}
                    </button>
                  </div>
                </div>
              )}

              {paymentMethod === 'ssl' && (
                <div className="mt-6 bg-slate-900 p-6 rounded-2xl text-white">
                  <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Send BDT to Mobile Money</p>
                  <div className="flex justify-between items-center bg-white/5 p-4 rounded-xl">
                    <span className="font-mono text-white font-bold tracking-widest">{bdNumber}</span>
                    <div className="flex gap-4">
                      <button onClick={() => copyToClipboard(bdNumber, 'bkash')} className="text-[10px] font-black uppercase text-pink-400">Bkash</button>
                      <button onClick={() => copyToClipboard(bdNumber, 'nagad')} className="text-[10px] font-black uppercase text-orange-400">Nagad</button>
                    </div>
                  </div>
                </div>
              )}

              <div className="mt-10 pt-10 border-t border-slate-100">
                  <h2 className="text-xl font-black text-slate-900 mb-8 flex items-center gap-3">
                      <span className="flex items-center justify-center w-8 h-8 rounded-full bg-slate-100 text-slate-600 text-sm font-black">2</span>
                      Delivery Information
                  </h2>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <input value={custName} onChange={e => setCustName(e.target.value)} type="text" placeholder="Your Name" className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none focus:ring-2 focus:ring-blue-600 font-bold" />
                      <input value={custWhatsapp} onChange={e => setCustWhatsapp(e.target.value)} type="text" placeholder="Whatsapp Number" className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none focus:ring-2 focus:ring-blue-600 font-bold" />
                      <input value={custEmail} onChange={e => setCustEmail(e.target.value)} type="email" placeholder="Contact Email" className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none focus:ring-2 focus:ring-blue-600 font-bold md:col-span-2" />
                  </div>
              </div>
            </div>
          ) : (
            <div className="bg-white rounded-[2.5rem] border border-slate-200 p-10 shadow-sm animate-in slide-in-from-right duration-500 text-center">
              <h2 className="text-2xl font-black text-slate-900 mb-2 uppercase tracking-tighter">Submit Verification</h2>
              <p className="text-slate-500 font-bold text-xs uppercase tracking-widest mb-10">Upload your payment screenshot to process order</p>

              <div className="space-y-6 text-left">
                <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block ml-1">Transaction ID / Reference</label>
                  <input value={transactionId} onChange={(e) => setTransactionId(e.target.value)} type="text" placeholder="Enter TxID..." className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none focus:ring-2 focus:ring-blue-600 font-black tracking-widest" />
                </div>

                <div 
                  onClick={() => fileInputRef.current?.click()}
                  className={`h-48 border-2 border-dashed rounded-[2rem] flex flex-col items-center justify-center transition-all cursor-pointer ${screenshot ? 'border-blue-600 bg-blue-50' : 'border-slate-200 hover:bg-slate-50'}`}
                >
                  <svg className={`w-8 h-8 mb-3 ${screenshot ? 'text-blue-600' : 'text-slate-300'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
                  </svg>
                  <span className="text-[10px] font-black text-slate-900 uppercase tracking-widest">
                    {screenshot ? `Screenshot: ${screenshot.name}` : 'Click to Upload Proof'}
                  </span>
                  <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={(e) => setScreenshot(e.target.files?.[0] || null)} />
                </div>
              </div>
            </div>
          )}
        </div>

        <div className="lg:col-span-5">
          <div className="bg-slate-900 rounded-[2.5rem] p-8 text-white shadow-2xl sticky top-28">
            <h3 className="text-xl font-black uppercase tracking-tighter mb-6 border-b border-white/10 pb-4">Order Summary</h3>
            <div className="space-y-4 mb-8">
              {items.map(item => (
                <div key={item.id} className="flex justify-between text-xs font-bold">
                  <span className="text-slate-500">{item.quantity}x {item.name}</span>
                  <span>{formatPrice(item.price * item.quantity)}</span>
                </div>
              ))}
            </div>
            <div className="pt-6 border-t border-white/10 flex justify-between items-center mb-10">
              <span className="font-black uppercase tracking-widest text-xs text-slate-500">Total Payable</span>
              <span className="text-2xl font-black text-cyan-400">{formatPrice(total)}</span>
            </div>
            <button 
              onClick={step === 'details' ? handleProceedToProof : handleFinalSubmit}
              disabled={isProcessing}
              className="w-full py-5 bg-white text-slate-950 rounded-2xl font-black text-sm uppercase tracking-widest hover:bg-cyan-400 transition-all disabled:opacity-50"
            >
              {isProcessing ? 'Saving Order...' : step === 'details' ? 'Next Step' : 'Confirm & Send'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

