                <tr key={p.id} className="hover:bg-slate-50/50 transition-colors group">
                  <td className="px-8 py-4">
                    <div className="flex items-center gap-4">
                      <img src={p.image} className="w-12 h-12 rounded-xl object-cover border border-slate-100 shadow-sm" alt="" />
                      <span className="font-black text-slate-900 text-sm">{p.name}</span>
                    </div>
                  </td>
                  <td className="px-8 py-4"><span className="text-[10px] font-black uppercase tracking-widest text-slate-500">{p.category}</span></td>
                  <td className="px-8 py-4 font-black text-blue-600 text-sm">${p.price.toFixed(2)}</td>
