              </div>
              <h2 className="text-xl font-black text-slate-900 uppercase tracking-tighter">Secure Terminal</h2>
              <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-1">Authorized Access Only</p>
            </div>

            <form onSubmit={verifyAdmin} className="space-y-4">
              <input 
                autoFocus
                type="password"
                placeholder="Enter Access Key..."
                className={`w-full px-5 py-4 bg-slate-50 border-2 rounded-2xl outline-none font-black text-center tracking-widest transition-all ${adminError ? 'border-red-500 bg-red-50 animate-shake' : 'border-slate-100 focus:border-blue-600'}`}
                value={adminInputPass}
                onChange={e => setAdminInputPass(e.target.value)}
              />
              {adminError && <p className="text-red-500 text-[10px] font-black uppercase text-center tracking-widest">Access Denied</p>}
              <div className="grid grid-cols-2 gap-3">
                <button type="button" onClick={() => setShowAdminPassModal(false)} className="py-4 bg-slate-100 text-slate-500 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-slate-200 transition-all">Cancel</button>
                <button type="submit" className="py-4 bg-slate-900 text-white rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-blue-600 transition-all shadow-lg">Unlock</button>
              </div>
            </form>
          </div>
        </div>
      )}

      <CartDrawer isOpen={isCartOpen} onClose={() => setIsCartOpen(false)} items={cart} onRemove={(id) => setCart(cart.filter(i => i.id !== id))} onUpdateQuantity={(id, q) => setCart(cart.map(i => i.id === id ? {...i, quantity: q} : i))} onCheckout={() => { setIsCartOpen(false); setCurrentView('checkout'); }} />
      <AuthModal isOpen={isAuthModalOpen} initialMode={authMode} onClose={() => setIsAuthModalOpen(false)} onLogin={(u) => setUser(u)} />
    </div>
  );
};

export default App;

export interface Product {
  id: string;
  name: string;
  description: string;
  price: number;
  category: string;
  image: string;
  stock: number;
  rating: number;
}

export interface CartItem extends Product {
  quantity: number;
}

export interface User {
  id: string;
  name: string;
  email: string;
  isAdmin: boolean;
}

export interface Order {
  id: string;
  userId: string;
  items: CartItem[];
  total: number;
  status: 'pending' | 'confirmed' | 'delivered' | 'cancelled';
  createdAt: string;
  fullName: string;
  whatsappNumber: string;
  deliveryEmail: string;
  paymentMethod: string;
  transactionId: string;
  screenshotUrl?: string;
}

export type View = 'shop' | 'product-detail' | 'checkout' | 'cart' | 'admin';

import React, { useState, useRef, useMemo } from 'react';
import { CartItem, Order } from '../types';
import { supabase } from '../supabaseClient';

interface CheckoutViewProps {
  items: CartItem[];
  onBack: () => void;
  onSuccess: (orderData: Omit<Order, 'id' | 'userId' | 'createdAt'>) => void;
}

type CheckoutStep = 'details' | 'proof';

export const CheckoutView: React.FC<CheckoutViewProps> = ({ items, onBack, onSuccess }) => {
  const [paymentMethod, setPaymentMethod] = useState<'crypto' | 'ssl' | null>(null);
  const [step, setStep] = useState<CheckoutStep>('details');
  const [isProcessing, setIsProcessing] = useState(false);
  const [copiedId, setCopiedId] = useState<string | null>(null);

  // Account Delivery Information State
  const [fullName, setFullName] = useState('');
  const [whatsappNumber, setWhatsappNumber] = useState('');
  const [deliveryEmail, setDeliveryEmail] = useState('');

  // Proof fields
  const [transactionId, setTransactionId] = useState('');
  const [screenshot, setScreenshot] = useState<File | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const binancePayId = "573432978";
  const bdNumber = "01946406095";
  const USD_TO_BDT_RATE = 125; 

  const subtotal = items.reduce((sum, item) => sum + (item.price * item.quantity), 0);
  const totalQuantity = items.reduce((sum, item) => sum + item.quantity, 0);
  const isDiscountEligible = totalQuantity >= 100;
  const discount = isDiscountEligible ? subtotal * 0.05 : 0;
  const totalAmount = subtotal - discount;

  // Validation Logic
  const isDetailsValid = useMemo(() => {
    return (
      paymentMethod !== null &&
      fullName.trim().length > 0 &&
      whatsappNumber.trim().length > 0 &&
      deliveryEmail.trim().match(/^[^\s@]+@[^\s@]+\.[^\s@]+$/)
    );
  }, [paymentMethod, fullName, whatsappNumber, deliveryEmail]);

  const isProofValid = useMemo(() => {
    return transactionId.trim().length > 0 && screenshot !== null;
  }, [transactionId, screenshot]);

  const handleProceedToProof = () => {
    if (!isDetailsValid) return;
    setStep('proof');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleFinalSubmit = async () => {
    if (!isProofValid || !screenshot) {
      alert(`Please enter your transaction ID and upload a screenshot.`);
      return;
    }

    setIsProcessing(true);

    try {
      // 1. Upload Screenshot to Supabase Storage
      const fileExt = screenshot.name.split('.').pop();
      const fileName = `${Date.now()}-${Math.random().toString(36).substring(7)}.${fileExt}`;
      const filePath = `payment-proofs/${fileName}`;

      const { error: uploadError } = await supabase.storage
        .from('products') // Using the existing 'products' bucket or you can create 'orders'
        .upload(filePath, screenshot);

      if (uploadError) throw uploadError;

      // 2. Get Public URL
      const { data: urlData } = supabase.storage
        .from('products')
        .getPublicUrl(filePath);

      // 3. Submit Order Data
      onSuccess({
        items,
        total: totalAmount,
        status: 'pending',
        fullName,
        whatsappNumber,
        deliveryEmail,
        paymentMethod: paymentMethod === 'crypto' ? 'Binance' : 'Mobile Banking',
