                    </div>
                    <span className="text-[10px] font-black uppercase tracking-widest text-cyan-400">Expert Recommendation</span>
                  </div>
                  <div className="text-sm leading-relaxed whitespace-pre-line font-medium text-slate-300">
                    {aiResponse}
