            <div className="bg-blue-50 p-6 rounded-3xl border border-blue-100">
              <h4 className="text-sm font-black text-blue-900 uppercase tracking-tight mb-2">1. টেবিল তৈরি</h4>
              <p className="text-xs text-blue-700 leading-relaxed font-medium">উপরের SQL কোডটি Supabase SQL Editor-এ রান করলে `products` এবং `orders` টেবিল তৈরি হয়ে যাবে। এরপরই আপনি ওয়েবসাইট থেকে সার্ভিস যোগ করতে পারবেন।</p>
            </div>
            <div className="bg-indigo-50 p-6 rounded-3xl border border-indigo-100">
              <h4 className="text-sm font-black text-indigo-900 uppercase tracking-tight mb-2">2. স্টোরেজ সেটআপ</h4>
              <p className="text-xs text-indigo-700 leading-relaxed font-medium">ইমেজ আপলোড করার জন্য Supabase Storage-এ গিয়ে `products` নামে একটি <b>Public</b> বাকেট তৈরি করুন। অন্যথায় ইমেজ সেভ হবে না।</p>
            </div>
          </div>
        </div>
      )}

      {selectedOrder && (
        <div className="fixed inset-0 z-[400] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/90 backdrop-blur-xl" onClick={() => setSelectedOrder(null)} />
          <div className="relative w-full max-w-4xl bg-white rounded-[3rem] shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300 max-h-[90vh] flex flex-col">
            <div className="flex items-center justify-between p-8 border-b border-slate-100">
              <div>
                <h2 className="text-2xl font-black text-slate-900 uppercase tracking-tighter">Order Details</h2>
                <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-1">Order ID: {selectedOrder.id}</p>
              </div>
              <button onClick={() => setSelectedOrder(null)} className="p-3 bg-slate-100 text-slate-400 rounded-2xl hover:bg-slate-200 transition-all">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            </div>

            <div className="flex-1 overflow-y-auto p-8 lg:p-12">
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
                <div className="space-y-10">
                  <section>
                    <h3 className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em] mb-4">Customer Info</h3>
                    <div className="space-y-4">
                      <div className="flex flex-col">
                        <span className="text-xs font-bold text-slate-400 uppercase">Full Name</span>
                        <span className="text-lg font-black text-slate-900">{selectedOrder.fullName}</span>
                      </div>
                      <div className="flex flex-col">
                        <span className="text-xs font-bold text-slate-400 uppercase">WhatsApp</span>
                        <span className="text-lg font-black text-blue-600 underline cursor-pointer">{selectedOrder.whatsappNumber}</span>
                      </div>
                      <div className="flex flex-col">
                        <span className="text-xs font-bold text-slate-400 uppercase">Delivery Email</span>
                        <span className="text-lg font-black text-slate-900">{selectedOrder.deliveryEmail}</span>
                      </div>
                    </div>
                  </section>

                  <section>
                    <h3 className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em] mb-4">Payment Details</h3>
                    <div className="bg-slate-50 rounded-3xl p-6 border border-slate-100 space-y-4">
                      <div className="flex justify-between items-center">
                        <span className="text-xs font-black text-slate-400 uppercase">Method</span>
                        <span className="text-sm font-black text-slate-900">{selectedOrder.paymentMethod}</span>
                      </div>
                      <div className="flex justify-between items-center">
                        <span className="text-xs font-black text-slate-400 uppercase">Trx ID / Order ID</span>
                        <span className="text-sm font-black text-cyan-600 font-mono tracking-widest">{selectedOrder.transactionId}</span>
                      </div>
                      <div className="flex justify-between items-center pt-4 border-t border-slate-200">
                        <span className="text-xs font-black text-slate-400 uppercase">Total Amount</span>
                        <span className="text-2xl font-black text-slate-900">${selectedOrder.total.toFixed(2)}</span>
                      </div>
                    </div>
                  </section>

                  <section>
                    <h3 className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em] mb-4">Ordered Items</h3>
                    <div className="space-y-3">
                      {selectedOrder.items.map((item, i) => (
                        <div key={i} className="flex justify-between items-center p-4 bg-slate-50 rounded-2xl border border-slate-100">
                          <span className="text-xs font-black text-slate-900">{item.name} <span className="text-slate-400 ml-1">(x{item.quantity})</span></span>
                          <span className="text-xs font-black text-blue-600">${(item.price * item.quantity).toFixed(2)}</span>
                        </div>
                      ))}
                    </div>
                  </section>
                </div>

                <div>
                  <h3 className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em] mb-4">Payment Proof</h3>
                  {selectedOrder.screenshotUrl ? (
                    <div className="relative group">
                      <div className="rounded-[2rem] overflow-hidden border border-slate-200 bg-slate-50 shadow-inner">
                        <img 
                          src={selectedOrder.screenshotUrl} 
                          alt="Payment Proof" 
                          className="w-full h-auto object-contain cursor-zoom-in transition-transform group-hover:scale-105 duration-500"
                          onClick={() => window.open(selectedOrder.screenshotUrl, '_blank')}
                        />
                      </div>
                      <p className="text-center text-[10px] font-black text-slate-400 uppercase mt-4">Click Image to View Full Size</p>
                    </div>
                  ) : (
                    <div className="h-64 rounded-[2rem] border-2 border-dashed border-slate-200 flex flex-col items-center justify-center text-slate-300">
                      <svg className="w-12 h-12 mb-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                      <span className="text-xs font-black uppercase tracking-widest">No Screenshot Provided</span>
                    </div>
                  )}

                  <div className="mt-12 space-y-4">
                    <h3 className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em] mb-4">Quick Actions</h3>
                    <div className="grid grid-cols-2 gap-3">
                      <button 
                        onClick={() => { onUpdateOrderStatus(selectedOrder.id, 'confirmed'); setSelectedOrder(null); }}
                        className="py-4 bg-green-600 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-green-700 shadow-xl shadow-green-200 transition-all"
                      >
                        Approve Order
                      </button>
                      <button 
                        onClick={() => { onUpdateOrderStatus(selectedOrder.id, 'cancelled'); setSelectedOrder(null); }}
                        className="py-4 bg-red-50 text-red-600 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-red-100 transition-all"
                      >
                        Cancel Order
                      </button>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export interface Product {
  id: string;
  name: string;
  description: string;
  price: number;
  category: string;
  image: string;
  stock: number;
  rating: number;
  is_published?: boolean;
}

export interface CartItem extends Product {
  quantity: number;
}

export interface User {
  id: string;
  name: string;
  email: string;
  isAdmin: boolean;
}

export interface Order {
  id: string;
  userId: string;
  items: CartItem[];
  total: number;
  status: 'pending' | 'confirmed' | 'delivered' | 'cancelled';
  createdAt: string;
  fullName: string;
  whatsappNumber: string;
  deliveryEmail: string;
  paymentMethod: string;
  transactionId: string;
  screenshotUrl?: string;
}

export type View = 'shop' | 'product-detail' | 'checkout' | 'cart' | 'admin';

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Navbar } from './components/Navbar';
import { ProductCard } from './components/ProductCard';
import { CartDrawer } from './components/CartDrawer';
import { ProductDetail } from './components/ProductDetail';
import { ProductTicker } from './components/ProductTicker';
import { CheckoutView } from './components/CheckoutView';
import { AuthModal } from './components/AuthModal';
import { AdminPanel } from './components/AdminPanel';
import { Product, CartItem, User, View, Order } from './types';
import { INITIAL_PRODUCTS, CATEGORIES } from './constants';
import { supabase } from './supabaseClient';
import { getProductRecommendations } from './services/geminiService';

const App: React.FC = () => {
  const [products, setProducts] = useState<Product[]>(INITIAL_PRODUCTS);
  const [orders, setOrders] = useState<Order[]>([]);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [currentView, setCurrentView] = useState<View>('shop');
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [searchQuery, setSearchQuery] = useState('');
  const [user, setUser] = useState<User | null>(null);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
  const [authMode, setAuthMode] = useState<'signin' | 'signup' | 'forgot' | 'update'>('signin');
  const [loading, setLoading] = useState(true);

  const [aiQuery, setAiQuery] = useState('');
  const [aiResponse, setAiResponse] = useState<string | null>(null);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [showAiModal, setShowAiModal] = useState(false);

  const [isAdminAuthenticated, setIsAdminAuthenticated] = useState(false);
  const [showAdminPassModal, setShowAdminPassModal] = useState(false);
  const [adminInputPass, setAdminInputPass] = useState('');
  const [adminError, setAdminError] = useState(false);

  const shopSectionRef = useRef<HTMLDivElement>(null);
  const clickCount = useRef(0);
  const lastClickTime = useRef(0);
  const ADMIN_PASSWORD = "Ajmir@#123";

  const fetchData = async () => {
    try {
      const { data: dbProducts, error: prodError } = await supabase
        .from('products')
        .select('*')
        .order('name', { ascending: true });

      if (!prodError && dbProducts) {
        // যদি ডাটাবেস একদম খালি না থাকে, তবে ডাটাবেসের ডাটা দেখাবো
        if (dbProducts.length > 0) {
          setProducts(dbProducts);
        }
      }

      const { data: dbOrders, error: orderError } = await supabase
        .from('orders')
        .select(`*`)
        .order('created_at', { ascending: false });

      if (!orderError && dbOrders) {
        const mappedOrders = dbOrders.map((o: any) => ({
          id: o.id,
          userId: o.user_id,
          items: o.items,
          total: o.total,
          status: o.status,
          createdAt: o.created_at,
          fullName: o.full_name,
          whatsappNumber: o.whatsapp_number,
          deliveryEmail: o.delivery_email,
          paymentMethod: o.payment_method,
          transactionId: o.transaction_id,
          screenshotUrl: o.screenshot_url
        }));
        setOrders(mappedOrders as Order[]);
      }
    } catch (err) {
      console.error("General Fetch Error:", err);
    }
  };

  useEffect(() => {
    const initialize = async () => {
      try {
        const { data: { session } } = await supabase.auth.getSession();
        if (session?.user) {
          setUser({
            id: session.user.id,
            name: session.user.user_metadata.full_name || session.user.email?.split('@')[0] || 'User',
            email: session.user.email || '',
            isAdmin: false
          });
        }
        await fetchData();
      } catch (e) {
        console.error("Initialization error", e);
      } finally {
        setLoading(false);
      }
    };

    initialize();

    const { data: { subscription } } = supabase.auth.onAuthStateChange((event, session) => {
      if (event === 'PASSWORD_RECOVERY') {
        setAuthMode('update');
        setIsAuthModalOpen(true);
      }
      if (session?.user) {
        setUser({
          id: session.user.id,
          name: session.user.user_metadata.full_name || session.user.email?.split('@')[0] || 'User',
          email: session.user.email || '',
          isAdmin: false
        });
      } else {
        setUser(null);
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  const handleAiConsult = async () => {
    if (!aiQuery.trim()) return;
    setIsAiLoading(true);
    setAiResponse(null);
    try {
      const response = await getProductRecommendations(aiQuery, products);
      setAiResponse(response);
    } catch (err) {
      setAiResponse("Something went wrong. Please try again.");
    } finally {
      setIsAiLoading(false);
    }
  };

  const filteredProducts = useMemo(() => {
    // শপে শুধুমাত্র পাবলিশ করা প্রোডাক্ট দেখাবো
    return products.filter(p => {
      const isPublished = p.is_published === undefined || p.is_published === true;
      const matchesCategory = selectedCategory === 'All' || p.category === selectedCategory;
      const matchesSearch = p.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                           p.description.toLowerCase().includes(searchQuery.toLowerCase());
      return isPublished && matchesCategory && matchesSearch;
    });
  }, [products, selectedCategory, searchQuery]);

  const cartCount = useMemo(() => cart.reduce((sum, item) => sum + item.quantity, 0), [cart]);

  const handleAddToCart = (product: Product, quantity: number = 1) => {
    if (!user) { setAuthMode('signin'); setIsAuthModalOpen(true); return; }
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) return prev.map(item => item.id === product.id ? { ...item, quantity: item.quantity + quantity } : item);
      return [...prev, { ...product, quantity }];
    });
    setIsCartOpen(true);
  };

  const resetToShop = () => {
    setCurrentView('shop');
    setSelectedProduct(null);
    setSelectedCategory('All');
    setSearchQuery('');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleAdminAccessTrigger = () => {
    const now = Date.now();
    if (now - lastClickTime.current > 3000) {
      clickCount.current = 1;
    } else {
      clickCount.current += 1;
    }
    lastClickTime.current = now;

    if (clickCount.current >= 5) {
      clickCount.current = 0;
      setShowAdminPassModal(true);
      setAdminError(false);
      setAdminInputPass('');
    }
  };

  const verifyAdmin = (e: React.FormEvent) => {
    e.preventDefault();
    if (adminInputPass === ADMIN_PASSWORD) {
      setIsAdminAuthenticated(true);
      setCurrentView('admin');
      setShowAdminPassModal(false);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    } else {
      setAdminError(true);
      setTimeout(() => setAdminError(false), 2000);
    }
  };

  const handlePlaceOrder = async (orderInfo: Omit<Order, 'id' | 'userId' | 'createdAt'>) => {
    const orderData: any = {
      user_id: user?.id || 'guest',
      items: orderInfo.items,
      total: orderInfo.total,
      status: orderInfo.status,
      full_name: orderInfo.fullName,
      whatsapp_number: orderInfo.whatsappNumber,
      delivery_email: orderInfo.deliveryEmail,
      payment_method: orderInfo.paymentMethod,
      transaction_id: orderInfo.transactionId,
      created_at: new Date().toISOString(),
      screenshot_url: orderInfo.screenshotUrl
    };

    try {
      const { data, error } = await supabase
        .from('orders')
        .insert([orderData])
        .select('*');

      if (error) throw error;

      if (data) {
        alert("✅ Order Placed Successfully! Your order is being verified.");
        setCart([]);
        resetToShop();
        fetchData();
      }
    } catch (err: any) {
      console.error("Order error:", err);
      alert("❌ Failed to place order: " + err.message);
    }
  };

  const handleUpdateOrderStatus = async (orderId: string, status: Order['status']) => {
    try {
      const { error } = await supabase
        .from('orders')
        .update({ status })
        .eq('id', orderId);

      if (error) throw error;

      setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status } : o));
      alert(`✅ Order marked as ${status.toUpperCase()}`);
    } catch (err: any) {
      alert("❌ Failed to update status: " + err.message);
    }
  };

  const handleAddProduct = async (newProduct: Omit<Product, 'id'>) => {
    try {
      const { data, error } = await supabase
        .from('products')
        .insert([{ ...newProduct, is_published: true }])
        .select();

      if (error) throw error;

      if (data) {
        setProducts(prev => [...data, ...prev]);
        alert("✅ Product Added to Database!");
      }
    } catch (err: any) {
      alert("Error adding product: " + err.message);
    }
  };

  const handleUpdateProduct = async (id: string, updatedFields: Partial<Product>) => {
    try {
      // আমরা ID ছাড়া বাকি সব ফিল্ড আপডেট করবো
      const { id: _, ...fieldsToUpdate } = updatedFields as any;
      const { data, error } = await supabase
        .from('products')
        .update(fieldsToUpdate)
        .eq('id', id)
        .select();

      if (error) throw error;

      if (!data || data.length === 0) {
        // যদি ডাটাবেসে এই আইডি না পাওয়া যায় (ডেমো ডাটা হলে), সুুপাবাসে নতুন করে ইনসার্ট করার চেষ্টা করবে।
        const { data: newData, error: insertError } = await supabase
          .from('products')
          .insert([{ ...fieldsToUpdate }])
          .select();

        if (insertError) throw insertError;

        if (newData) {
          setProducts(prev => prev.map(p => p.id === id ? { ...newData[0] } : p));
          alert("✅ Product Saved as New in Database!");
        }
      } else {
        // ডাটাবেস আপডেট সফল হলে
        setProducts(prev => prev.map(p => p.id === id ? { ...p, ...data[0] } : p));
        alert("✅ Product Updated Successfully!");
      }
    } catch (err: any) {
      console.error("Update error:", err);
      alert("❌ Error saving changes: " + err.message);
    }
  };

  const handleDeleteProduct = async (id: string) => {
    const { error } = await supabase.from('products').delete().eq('id', id);
    if (!error) {
      setProducts(prev => prev.filter(p => p.id !== id));
      alert("🗑️ Product Removed Successfully.");
    } else {
      alert("Error deleting product: " + error.message);
    }
  };

  if (loading) return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50">
      <div className="flex flex-col items-center gap-6">
        <div className="relative w-16 h-16">
          <div className="absolute inset-0 border-4 border-blue-600/10 rounded-full"></div>
          <div className="absolute inset-0 border-4 border-blue-600 rounded-full border-t-transparent animate-spin"></div>
        </div>
        <p className="text-slate-900 font-black uppercase tracking-[0.2em] text-xs">Accessing Secure Vault</p>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen flex flex-col bg-[#F8FAFC]">
      <Navbar 
        currentView={currentView} 
        setView={(v) => { if(v === 'shop') resetToShop(); else setCurrentView(v); }} 
        cartCount={cartCount}
        user={user}
        onLogout={async () => { await supabase.auth.signOut(); setUser(null); setCart([]); resetToShop(); }}
        onAuthClick={() => { setAuthMode('signin'); setIsAuthModalOpen(true); }}
      />

      {currentView === 'shop' && <ProductTicker products={products.filter(p => p.is_published !== false)} onProductClick={(p) => { setSelectedProduct(p); setCurrentView('product-detail'); }} />}

      <main className="flex-1 max-w-7xl mx-auto w-full px-4 sm:px-6 lg:px-8 py-8">
        {currentView === 'shop' ? (
          <div className="space-y-12">
            <div className="relative rounded-[2.5rem] overflow-hidden min-h-[450px] flex items-center shadow-2xl border border-white/10"
              style={{ backgroundImage: 'url("https://images.unsplash.com/photo-1451187580459-43490279c0fa?auto=format&fit=crop&q=80&w=2000")', backgroundSize: 'cover', backgroundPosition: 'center' }}>
              <div className="absolute inset-0 bg-slate-900/80"></div>
              <div className="relative z-10 px-8 md:px-16 w-full lg:w-2/3 text-center md:text-left">
                <h1 className="text-4xl md:text-6xl font-black text-white uppercase tracking-tighter mb-4">DS <span className="text-cyan-400">SERVICE STORE</span></h1>
                <p className="text-sm font-black text-blue-200 uppercase tracking-[0.3em] mb-8">Verified Premium Digital Ecosystem</p>
                <div className="flex flex-wrap justify-center md:justify-start gap-4">
                  <button onClick={() => shopSectionRef.current?.scrollIntoView({ behavior: 'smooth' })} className="px-10 py-4 bg-white text-black rounded-2xl font-black uppercase tracking-widest hover:bg-cyan-400 transition-all shadow-lg active:scale-95">Shop Services Now</button>
                </div>
              </div>
            </div>

            <div ref={shopSectionRef} className="flex flex-col lg:flex-row gap-4 items-center justify-between bg-white p-4 rounded-3xl border border-slate-200 shadow-sm scroll-mt-24">
              <div className="flex gap-2 overflow-x-auto w-full lg:w-auto pb-2 lg:pb-0 scrollbar-hide">
                {CATEGORIES.map(cat => (
                  <button key={cat} onClick={() => setSelectedCategory(cat)} className={`px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${selectedCategory === cat ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-50'}`}>{cat}</button>
                ))}
              </div>
              <input type="text" placeholder="Search..." className="w-full lg:w-72 px-5 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none text-sm font-bold" value={searchQuery} onChange={e => setSearchQuery(e.target.value)} />
            </div>

            {filteredProducts.length === 0 ? (
              <div className="py-20 text-center bg-white rounded-[2rem] border-2 border-dashed border-slate-200">
                <div className="w-16 h-16 bg-slate-50 text-slate-300 rounded-full flex items-center justify-center mx-auto mb-4">
                  <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M20 13V6a2 2 0 00-2-2H6a2 2 0 00-2 2v7m16 0a2 2 0 01-2 2H6a2 2 0 01-2-2m16 0V9a2 2 0 00-2-2H6a2 2 0 00-2 2v2m4.688 4.406A4.948 4.948 0 0011 15.19c-.066.002-.132.005-.198.005a4.978 4.978 0 00-2.522.682M10.5 21l-2-2m2 2l2-2m-2 2V15" /></svg>
                </div>
                <h3 className="text-lg font-black text-slate-900 uppercase tracking-tighter">No Services Found</h3>
                <p className="text-slate-500 text-xs font-bold uppercase tracking-widest mt-1">Try another category or search term.</p>
              </div>
            ) : (
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8 pb-20">
                {filteredProducts.map(product => (
                  <ProductCard key={product.id} product={product} onAddToCart={(p) => handleAddToCart(p, 1)} onViewDetails={(p) => { setSelectedProduct(p); setCurrentView('product-detail'); }} />
                ))}
              </div>
            )}
          </div>
        ) : currentView === 'product-detail' && selectedProduct ? (
          <ProductDetail product={selectedProduct} onAddToCart={handleAddToCart} onBack={resetToShop} />
        ) : currentView === 'checkout' ? (
          <CheckoutView items={cart} onBack={resetToShop} onSuccess={handlePlaceOrder} />
        ) : currentView === 'admin' && isAdminAuthenticated ? (
          <AdminPanel 
            products={products} 
            orders={orders}
            onAddProduct={handleAddProduct} 
            onUpdateProduct={handleUpdateProduct}
            onDeleteProduct={handleDeleteProduct} 
