    try {
      const { data, error } = await supabase
        .from('products')
        .insert([{ ...newProduct, is_published: true }])
        .select();

      if (error) throw error;

      if (data) {
        setProducts(prev => [...data, ...prev]);
        alert("✅ Product Added and Published Successfully!");
      }
    } catch (err: any) {
      alert("Error adding product: " + err.message);
    }
