            products={products} 
            orders={orders}
            onAddProduct={handleAddProduct} 
            onUpdateProduct={handleUpdateProduct}
            onDeleteProduct={handleDeleteProduct} 
            onUpdateOrderStatus={async (id, s) => {
              await supabase.from('orders').update({ status: s }).eq('id', id);
              await fetchData();
            }}
            onBack={resetToShop} 
          />
        ) : (
          <div className="text-center py-20">
            <h2 className="text-2xl font-black text-slate-900 uppercase">Access Denied</h2>
            <button onClick={resetToShop} className="mt-6 px-8 py-3 bg-slate-900 text-white rounded-xl font-black uppercase">Home</button>
          </div>
        )}
      </main>

      {showAdminPassModal && (
        <div className="fixed inset-0 z-[300] flex items-center justify-center p-4 bg-slate-900/95 backdrop-blur-xl">
          <div className="bg-white rounded-3xl p-8 w-full max-w-sm shadow-2xl animate-in zoom-in-95">
            <h2 className="text-xl font-black text-slate-900 text-center uppercase mb-6">Admin Key Required</h2>
            <form onSubmit={(e) => { e.preventDefault(); if(adminInputPass === ADMIN_PASSWORD) { setIsAdminAuthenticated(true); setCurrentView('admin'); setShowAdminPassModal(false); } else { setAdminError(true); } }}>
              <input 
                type="password"
                placeholder="Access Key..."
                className={`w-full px-5 py-4 bg-slate-50 border-2 rounded-2xl outline-none text-center font-black ${adminError ? 'border-red-500' : 'border-slate-100'}`}
                value={adminInputPass}
                onChange={e => setAdminInputPass(e.target.value)}
              />
              <div className="grid grid-cols-2 gap-3 mt-4">
                <button type="button" onClick={() => setShowAdminPassModal(false)} className="py-4 bg-slate-100 rounded-2xl font-black uppercase text-xs">Cancel</button>
                <button type="submit" className="py-4 bg-slate-900 text-white rounded-2xl font-black uppercase text-xs">Unlock</button>
              </div>
            </form>
          </div>
        </div>
      )}

      <footer className="bg-[#0F172A] text-white/30 py-10 mt-20 border-t border-white/5">
        <div className="max-w-7xl mx-auto px-8 flex justify-between items-center">
          <p className="text-[10px] font-bold uppercase tracking-widest cursor-pointer" onClick={handleAdminAccessTrigger}>© 2024 DS SERVICE STORE</p>
        </div>
      </footer>

      <CartDrawer isOpen={isCartOpen} onClose={() => setIsCartOpen(false)} items={cart} onRemove={(id) => setCart(cart.filter(i => i.id !== id))} onUpdateQuantity={(id, q) => setCart(cart.map(i => i.id === id ? {...i, quantity: q} : i))} onCheckout={() => { setIsCartOpen(false); setCurrentView('checkout'); }} />
      <AuthModal isOpen={isAuthModalOpen} initialMode={authMode} onClose={() => setIsAuthModalOpen(false)} onLogin={(u) => setUser(u)} />
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { Product, Order } from '../types';
import { CATEGORIES, INITIAL_PRODUCTS } from '../constants';
import { supabase } from '../supabaseClient';

interface AdminPanelProps {
  products: Product[];
  orders: Order[];
  onAddProduct: (p: Omit<Product, 'id'>) => void;
  onUpdateProduct: (id: string, p: Partial<Product>) => void;
  onDeleteProduct: (id: string) => void;
  onUpdateOrderStatus: (orderId: string, status: Order['status']) => void;
  onBack: () => void;
}

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  products, 
  orders, 
  onAddProduct, 
  onUpdateProduct,
  onDeleteProduct, 
  onUpdateOrderStatus,
  onBack 
}) => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'orders' | 'setup'>('inventory');
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [uploading, setUploading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [dbStatus, setDbStatus] = useState<'checking' | 'ready' | 'not-found'>('checking');
  const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState({
    name: '',
    description: '',
    price: 0,
    category: CATEGORIES[1],
    image: '',
    stock: 10,
    rating: 5,
    is_published: true
  });

  useEffect(() => {
    const checkDb = async () => {
      const { error } = await supabase.from('products').select('id').limit(1);
      if (error) setDbStatus('not-found');
      else setDbStatus('ready');
    };
    checkDb();
  }, []);

  const sqlSetup = `CREATE TABLE products (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name TEXT NOT NULL,
  description TEXT,
  price NUMERIC NOT NULL,
  category TEXT NOT NULL,
  image TEXT,
  stock INTEGER DEFAULT 0,
  rating NUMERIC DEFAULT 5,
  is_published BOOLEAN DEFAULT TRUE
);`;

  const manualInsertExample = `INSERT INTO products (name, description, price, category, image, stock, rating, is_published) 
VALUES ('Example Service', 'Service Description', 5.00, 'New Apple Account', 'https://image-url.com', 100, 5, true);`;

  const handleSyncData = async () => {
    if (!confirm("This will push all default demo products to your Supabase database. Continue?")) return;
    setIsSyncing(true);
    try {
      const productsToSync = INITIAL_PRODUCTS.map(({ id, ...rest }) => ({ ...rest, is_published: true }));
      const { error } = await supabase.from('products').insert(productsToSync);
      if (error) throw error;
      alert("✅ Sync Success! Database updated.");
      window.location.reload();
    } catch (error: any) {
      alert("❌ Sync Failed: " + error.message);
    } finally {
      setIsSyncing(false);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    try {
      setUploading(true);
      if (!e.target.files || e.target.files.length === 0) return;
      const file = e.target.files[0];
      const filePath = `product-images/${Math.random()}.${file.name.split('.').pop()}`;
      const { error: uploadError } = await supabase.storage.from('products').upload(filePath, file);
      if (uploadError) throw uploadError;
      const { data } = supabase.storage.from('products').getPublicUrl(filePath);
      if (data) {
        setFormData({ ...formData, image: data.publicUrl });
        alert("✅ Image uploaded!");
      }
    } catch (error: any) {
      alert("Error: " + error.message);
    } finally {
      setUploading(false);
    }
  };

  const handleEditClick = (product: Product) => {
    setEditingId(product.id);
    setFormData({
      name: product.name,
      description: product.description,
      price: product.price,
      category: product.category,
      image: product.image,
      stock: product.stock,
      rating: product.rating,
      is_published: product.is_published !== false
    });
    setIsFormOpen(true);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);
    try {
      if (editingId) {
        await onUpdateProduct(editingId, formData);
      } else {
        await onAddProduct(formData);
      }
      resetForm();
    } catch (err) {
      console.error(err);
    } finally {
      setSaving(false);
    }
  };

  const resetForm = () => {
    setIsFormOpen(false);
    setEditingId(null);
    setFormData({ name: '', description: '', price: 0, category: CATEGORIES[1], image: '', stock: 10, rating: 5, is_published: true });
  };

  return (
