          {isFormOpen && (
            <form onSubmit={handleSubmit} className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-2xl mb-12">
              <h2 className="text-xl font-black text-slate-900 uppercase mb-8">{editingId ? 'Edit Service' : 'New Service'}</h2>
