                  <textarea required className="w-full px-5 py-4 rounded-2xl bg-slate-50 border border-slate-200 font-bold h-32" value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} placeholder="Description" />
                  <div className="grid grid-cols-2 gap-6">
                    <select className="w-full px-5 py-4 rounded-2xl bg-slate-50 border border-slate-200 font-bold" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                      {CATEGORIES.filter(c => c !== 'All').map(c => <option key={c} value={c}>{c}</option>)}
