                    <input type="number" required className="w-full px-5 py-4 rounded-2xl bg-slate-50 border border-slate-200 font-bold" value={formData.stock} onChange={e => setFormData({...formData, stock: parseInt(e.target.value)})} placeholder="Stock" />
