            <p className="text-indigo-200 text-sm mb-6">ডাটাবেস টেবিলটি একদম খালি হলে একবার এই বাটনে ক্লিক করুন যাতে ডেমো প্রোডাক্টগুলো ডাটাবেসে সেভ হয়ে যায়।</p>
            <button 
              onClick={handleSyncData}
              disabled={isSyncing}
              className="px-8 py-4 bg-white text-indigo-900 rounded-2xl font-black uppercase tracking-widest hover:bg-cyan-400 transition-all flex items-center gap-3 shadow-lg"
            >
              {isSyncing ? 'Syncing...' : 'Push Demo Data to DB'}
            </button>
          </section>
        </div>
      )}

      {selectedOrder && (
        <div className="fixed inset-0 z-[400] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/90 backdrop-blur-md" onClick={() => setSelectedOrder(null)} />
          <div className="relative w-full max-w-lg bg-white rounded-[3rem] p-10 shadow-2xl animate-in zoom-in-95">
             <h2 className="text-2xl font-black text-slate-900 uppercase mb-6">Order Details</h2>
             <div className="space-y-4 mb-8">
               <p className="text-sm"><b>Name:</b> {selectedOrder.fullName}</p>
               <p className="text-sm"><b>WhatsApp:</b> {selectedOrder.whatsappNumber}</p>
               <p className="text-sm"><b>Total:</b> ${selectedOrder.total.toFixed(2)}</p>
               {selectedOrder.screenshotUrl && (
                 <div className="mt-4"><img src={selectedOrder.screenshotUrl} className="w-full rounded-xl" alt="Proof" /></div>
               )}
             </div>
             <div className="grid grid-cols-2 gap-3">
               <button onClick={() => { onUpdateOrderStatus(selectedOrder.id, 'confirmed'); setSelectedOrder(null); }} className="py-4 bg-green-600 text-white rounded-2xl font-black uppercase text-xs">Confirm Order</button>
               <button onClick={() => setSelectedOrder(null)} className="py-4 bg-slate-100 rounded-2xl font-black uppercase text-xs">Close</button>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

