             </div>
             <div className="grid grid-cols-2 gap-3">
               <button onClick={() => { onUpdateOrderStatus(selectedOrder.id, 'confirmed'); setSelectedOrder(null); }} className="py-4 bg-green-600 text-white rounded-2xl font-black uppercase text-xs">Confirm Order</button>
               <button onClick={() => setSelectedOrder(null)} className="py-4 bg-slate-100 rounded-2xl font-black uppercase text-xs">Close</button>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

