import { CATEGORIES, INITIAL_PRODUCTS } from '../constants';
import { supabase } from '../supabaseClient';

interface AdminPanelProps {
  products: Product[];
  orders: Order[];
  onAddProduct: (p: Omit<Product, 'id'>) => void;
  onUpdateProduct: (id: string, p: Partial<Product>) => void;
  onDeleteProduct: (id: string) => void;
  onUpdateOrderStatus: (orderId: string, status: Order['status']) => void;
  onBack: () => void;
}

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  products, 
  orders, 
  onAddProduct, 
  onUpdateProduct,
  onDeleteProduct, 
  onUpdateOrderStatus,
  onBack 
}) => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'orders'>('inventory');
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [uploading, setUploading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [dbStatus, setDbStatus] = useState<'checking' | 'ready' | 'not-found'>('checking');
  const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState({
    name: '',
    description: '',
    price: 0,
    category: CATEGORIES[1],
    image: '',
    stock: 10,
    rating: 5,
    is_published: true
  });

  useEffect(() => {
    const checkDb = async () => {
      const { error } = await supabase.from('products').select('id').limit(1);
      if (error) setDbStatus('not-found');
      else setDbStatus('ready');
    };
    checkDb();
  }, []);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    try {
      setUploading(true);
      if (!e.target.files || e.target.files.length === 0) return;
      const file = e.target.files[0];
      const filePath = `product-images/${Math.random()}.${file.name.split('.').pop()}`;
      const { error: uploadError } = await supabase.storage.from('products').upload(filePath, file);
      if (uploadError) throw uploadError;
      const { data } = supabase.storage.from('products').getPublicUrl(filePath);
      if (data) {
        setFormData({ ...formData, image: data.publicUrl });
        alert("✅ Image uploaded!");
      }
    } catch (error: any) {
      alert("Error: " + error.message);
    } finally {
      setUploading(false);
    }
  };

  const handleEditClick = (product: Product) => {
    setEditingId(product.id);
    setFormData({
      name: product.name,
      description: product.description,
      price: product.price,
      category: product.category,
      image: product.image,
      stock: product.stock,
      rating: product.rating,
      is_published: product.is_published !== false
    });
    setIsFormOpen(true);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);
    try {
      if (editingId) {
        await onUpdateProduct(editingId, formData);
      } else {
        await onAddProduct(formData);
      }
      resetForm();
    } catch (err) {
      console.error(err);
    } finally {
      setSaving(false);
    }
  };

  const resetForm = () => {
    setIsFormOpen(false);
    setEditingId(null);
    setFormData({ name: '', description: '', price: 0, category: CATEGORIES[1], image: '', stock: 10, rating: 5, is_published: true });
  };

  return (
    <div className="animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 mb-8">
        <div>
          <h1 className="text-3xl font-black text-slate-900 uppercase tracking-tighter">Admin Console</h1>
          <div className="flex items-center gap-2 mt-1">
            <span className={`w-2 h-2 rounded-full ${dbStatus === 'ready' ? 'bg-green-500 animate-pulse' : dbStatus === 'checking' ? 'bg-amber-400' : 'bg-red-500'}`}></span>
            <p className="text-slate-500 text-xs font-bold uppercase tracking-widest">
              Database: {dbStatus === 'ready' ? 'Online & Syncing' : dbStatus === 'checking' ? 'Connecting...' : 'Table Not Found'}
            </p>
          </div>
        </div>
        <button onClick={onBack} className="px-6 py-3 border-2 border-slate-200 rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-slate-50 transition-all">Exit Admin</button>
      </div>

      <div className="flex flex-wrap gap-4 mb-8 bg-slate-100 p-1.5 rounded-2xl w-fit">
        {['inventory', 'orders'].map((tab) => (
          <button 
            key={tab}
            onClick={() => setActiveTab(tab as any)}
            className={`px-6 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === tab ? 'bg-white text-blue-600 shadow-md' : 'text-slate-500 hover:text-slate-700'}`}
          >
            {tab.charAt(0).toUpperCase() + tab.slice(1)} {tab === 'orders' ? `(${orders.length})` : ''}
          </button>
        ))}
      </div>

      {activeTab === 'inventory' ? (
        <>
          <div className="flex justify-end mb-6">
            <button 
              onClick={() => { if(isFormOpen) resetForm(); else setIsFormOpen(true); }}
              className={`px-6 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest shadow-xl transition-all ${isFormOpen ? 'bg-slate-200 text-slate-600' : 'bg-blue-600 text-white shadow-blue-200 hover:bg-blue-700'}`}
            >
              {isFormOpen ? 'Close Form' : 'Add New Service'}
            </button>
          </div>

          {isFormOpen && (
            <form onSubmit={handleSubmit} className="bg-white p-6 md:p-10 rounded-[3rem] border border-slate-200 shadow-[0_30px_100px_-20px_rgba(0,0,0,0.1)] mb-12 animate-in slide-in-from-top-4 duration-500 overflow-hidden relative">
              <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-50 rounded-full blur-3xl -mr-32 -mt-32 opacity-50"></div>

              <div className="relative">
                <div className="flex items-center gap-4 mb-10">
                    <div className="w-12 h-12 bg-indigo-600 rounded-2xl flex items-center justify-center text-white shadow-lg shadow-indigo-200">
                        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 9v3m0 0v3m0-3h3m-3 0H9m12 0a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                    </div>
                    <div>
                        <h2 className="text-2xl font-black text-slate-900 uppercase tracking-tight">{editingId ? 'Edit Service' : 'Configure New Service'}</h2>
                        <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Store Inventory Management</p>
                    </div>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
                  {/* LEFT: General Info */}
                  <div className="lg:col-span-8 space-y-8">
                    <div className="space-y-4">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Basic Information</label>
                        <input 
                            required 
                            className="w-full px-6 py-5 rounded-[1.5rem] bg-slate-50 border-2 border-slate-100 font-bold outline-none focus:border-indigo-500 focus:bg-white transition-all" 
                            value={formData.name} 
                            onChange={e => setFormData({...formData, name: e.target.value})} 
                            placeholder="Service Name (e.g. New Fresh Apple ID)" 
                        />
                        <textarea 
                            required 
                            className="w-full px-6 py-5 rounded-[1.5rem] bg-slate-50 border-2 border-slate-100 font-bold h-36 outline-none focus:border-indigo-500 focus:bg-white transition-all resize-none" 
                            value={formData.description} 
                            onChange={e => setFormData({...formData, description: e.target.value})} 
                            placeholder="Detailed Description of the service..." 
                        />
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div className="space-y-4">
                            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Service Category</label>
                            <select 
                                className="w-full px-6 py-5 rounded-[1.5rem] bg-slate-50 border-2 border-slate-100 font-bold outline-none focus:border-indigo-500 focus:bg-white transition-all appearance-none cursor-pointer" 
                                value={formData.category} 
                                onChange={e => setFormData({...formData, category: e.target.value})}
                            >
                                {CATEGORIES.filter(c => c !== 'All').map(c => <option key={c} value={c}>{c}</option>)}
                            </select>
                        </div>
                        <div className="space-y-4">
                            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Visual Identity (Image URL)</label>
                            <div className="flex gap-3">
                                <div className="relative flex-1">
                                    <input 
                                        type="url" 
                                        className="w-full px-6 py-5 rounded-[1.5rem] bg-slate-50 border-2 border-slate-100 font-bold outline-none focus:border-indigo-500 focus:bg-white transition-all" 
                                        value={formData.image} 
                                        onChange={e => setFormData({...formData, image: e.target.value})} 
                                        placeholder="https://..." 
                                    />
                                    {formData.image && (
                                        <div className="absolute right-4 top-1/2 -translate-y-1/2 w-10 h-10 rounded-xl border border-slate-200 bg-white overflow-hidden shadow-sm">
                                            <img src={formData.image} className="w-full h-full object-cover" alt="" />
                                        </div>
                                    )}
                                </div>
                                <button 
                                    type="button" 
                                    onClick={() => fileInputRef.current?.click()} 
                                    className="px-6 bg-slate-900 text-white rounded-[1.5rem] hover:bg-indigo-600 transition-all flex items-center justify-center shadow-lg active:scale-95"
                                    title="Upload Image"
                                >
                                    {uploading ? (
                                        <div className="animate-spin rounded-full h-5 w-5 border-2 border-white border-t-transparent"></div>
                                    ) : (
                                        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>
                                    )}
                                </button>
                                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileUpload} />
                            </div>
                        </div>
                    </div>
                  </div>

                  {/* RIGHT: Pricing, Stock & Publish */}
                  <div className="lg:col-span-4 flex flex-col gap-8">
                    <div className="bg-slate-50 p-8 rounded-[2rem] border-2 border-slate-100 space-y-6">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Pricing & Inventory</label>

                        <div className="space-y-2">
                            <span className="text-[10px] font-bold text-slate-500 uppercase ml-1">Price (USD)</span>
                            <div className="relative">
                                <span className="absolute left-6 top-1/2 -translate-y-1/2 font-black text-slate-400">$</span>
                                <input 
                                    type="number" 
                                    step="0.01" 
                                    required 
                                    className="w-full pl-10 pr-6 py-5 rounded-2xl bg-white border-2 border-slate-100 font-black text-indigo-600 outline-none focus:border-indigo-500 transition-all" 
                                    value={formData.price} 
                                    onChange={e => setFormData({...formData, price: parseFloat(e.target.value)})} 
                                    placeholder="0.00" 
                                />
                            </div>
                        </div>

                        <div className="space-y-2">
                            <span className="text-[10px] font-bold text-slate-500 uppercase ml-1">Initial Units</span>
                            <input 
                                type="number" 
                                required 
                                className="w-full px-6 py-5 rounded-2xl bg-white border-2 border-slate-100 font-black text-slate-700 outline-none focus:border-indigo-500 transition-all" 
                                value={formData.stock} 
                                onChange={e => setFormData({...formData, stock: parseInt(e.target.value)})} 
                                placeholder="100" 
                            />
                        </div>
                    </div>

                    <div className="flex-1 flex flex-col justify-between gap-6">
                        <div 
                          className={`p-6 rounded-[2rem] border-2 transition-all cursor-pointer flex items-center justify-between
                            ${formData.is_published ? 'bg-green-50 border-green-100' : 'bg-slate-100 border-slate-200'}
                          `}
                          onClick={() => setFormData({...formData, is_published: !formData.is_published})}
                        >
                            <div>
                                <p className={`text-sm font-black uppercase ${formData.is_published ? 'text-green-700' : 'text-slate-500'}`}>
                                    {formData.is_published ? 'Live in Store' : 'Draft Mode'}
                                </p>
                                <p className="text-[10px] font-bold text-slate-400 mt-0.5">Visibility Status</p>
                            </div>
                            <div className={`w-12 h-6 rounded-full relative transition-all duration-300 ${formData.is_published ? 'bg-green-500' : 'bg-slate-300'}`}>
                                <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all duration-300 ${formData.is_published ? 'left-7' : 'left-1'}`}></div>
                            </div>
                        </div>

                        <div className="flex flex-col gap-3">
                            <button 
                                type="submit" 
                                disabled={uploading || saving} 
                                className="w-full py-6 bg-slate-900 text-white rounded-[1.5rem] font-black uppercase tracking-[0.15em] hover:bg-indigo-600 hover:shadow-2xl hover:shadow-indigo-200 transition-all flex items-center justify-center gap-3 active:scale-[0.98]"
                            >
                                {saving ? (
                                    <div className="animate-spin rounded-full h-5 w-5 border-2 border-white border-t-transparent"></div>
                                ) : (
                                    <>
                                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7" /></svg>
                                        {editingId ? 'Update & Sync' : 'Publish Service'}
                                    </>
                                )}
                            </button>
                            <button 
                                type="button"
                                onClick={resetForm}
                                className="w-full py-5 bg-white text-slate-400 rounded-[1.5rem] font-black uppercase text-[10px] tracking-widest border-2 border-slate-50 hover:bg-red-50 hover:text-red-500 hover:border-red-100 transition-all"
                            >
                                Discard Changes
                            </button>
                        </div>
                    </div>
                  </div>
                </div>
              </div>
            </form>
          )}

          <div className="bg-white rounded-[2.5rem] border border-slate-200 shadow-sm overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead className="bg-slate-50 border-b border-slate-100">
                  <tr>
                    <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">Service</th>
                    <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">Price</th>
                    <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Units</th>
                    <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">Status</th>
                    <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-50">
                  {products.map(p => (
                    <tr key={p.id} className="hover:bg-slate-50/50 transition-colors group">
                      <td className="px-8 py-5">
                        <div className="flex items-center gap-4">
                          <div className="w-12 h-12 rounded-xl overflow-hidden border border-slate-100 flex-shrink-0 bg-slate-50">
                            <img src={p.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" alt="" />
                          </div>
                          <div>
                            <span className="font-black text-slate-900 text-sm block">{p.name}</span>
                            <span className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter">{p.category}</span>
                          </div>
                        </div>
                      </td>
                      <td className="px-8 py-5">
                          <span className="font-black text-blue-600 bg-blue-50 px-3 py-1.5 rounded-lg text-sm">${p.price.toFixed(2)}</span>
                      </td>
                      <td className="px-8 py-5 text-center">
                        <div className="inline-flex flex-col items-center">
                          <span className={`font-black text-sm px-4 py-1.5 rounded-xl border-2 ${p.stock <= 10 ? 'border-amber-100 bg-amber-50 text-amber-600' : 'border-slate-50 bg-slate-50 text-slate-700'}`}>
                            {p.stock}
                          </span>
                        </div>
                      </td>
                      <td className="px-8 py-5">
                        <span className={`px-3 py-1.5 rounded-lg text-[9px] font-black uppercase tracking-widest ${p.is_published !== false ? 'bg-green-100 text-green-600' : 'bg-slate-100 text-slate-400'}`}>
                          {p.is_published !== false ? 'Public' : 'Hidden'}
                        </span>
                      </td>
                      <td className="px-8 py-5 text-right">
                        <div className="flex justify-end gap-2">
                            <button onClick={() => handleEditClick(p)} className="w-10 h-10 flex items-center justify-center bg-slate-50 text-slate-400 hover:bg-indigo-600 hover:text-white rounded-xl transition-all shadow-sm">
                                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M11 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-5M18.364 5.364a2.121 2.121 0 013 3L12 18l-4 1 1-4L18.364 5.364z" /></svg>
                            </button>
                            <button onClick={() => onDeleteProduct(p.id)} className="w-10 h-10 flex items-center justify-center bg-slate-50 text-slate-400 hover:bg-red-500 hover:text-white rounded-xl transition-all shadow-sm">
                                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6" /></svg>
                            </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </>
      ) : (
        <div className="bg-white rounded-[2.5rem] border border-slate-200 overflow-hidden shadow-sm">
          <table className="w-full text-left">
             <thead className="bg-slate-50 border-b border-slate-100">
               <tr>
                 <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">Customer</th>
                 <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">Total</th>
                 <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">Status</th>
               </tr>
             </thead>
             <tbody className="divide-y divide-slate-50">
               {orders.map(o => (
                 <tr key={o.id} className="hover:bg-blue-50/50 cursor-pointer group" onClick={() => setSelectedOrder(o)}>
                   <td className="px-8 py-6">
                       <span className="font-black text-slate-900 text-sm group-hover:text-indigo-600 transition-colors">{o.fullName}</span>
                       <span className="block text-[10px] font-bold text-slate-400 uppercase mt-0.5">{o.deliveryEmail}</span>
                   </td>
                   <td className="px-8 py-6 font-black text-slate-900">${o.total.toFixed(2)}</td>
                   <td className="px-8 py-6">
                       <span className={`px-3 py-1.5 rounded-lg text-[9px] font-black uppercase tracking-widest ${o.status === 'confirmed' ? 'bg-green-100 text-green-600' : 'bg-amber-100 text-amber-600'}`}>
                           {o.status}
                       </span>
                   </td>
                 </tr>
               ))}
             </tbody>
          </table>
        </div>
      )}

      {selectedOrder && (
        <div className="fixed inset-0 z-[400] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/90 backdrop-blur-md" onClick={() => setSelectedOrder(null)} />
          <div className="relative w-full max-w-xl bg-white rounded-[3.5rem] p-10 shadow-2xl animate-in zoom-in-95 duration-300">
             <div className="flex items-center justify-between mb-8">
                 <h2 className="text-3xl font-black text-slate-900 uppercase tracking-tighter">Order Dossier</h2>
                 <button onClick={() => setSelectedOrder(null)} className="w-10 h-10 bg-slate-50 rounded-full flex items-center justify-center text-slate-400 hover:bg-red-50 hover:text-red-500 transition-all">
                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" /></svg>
                 </button>
             </div>

             <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-10">
               <div className="space-y-4">
                 <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Customer Details</p>
                    <p className="text-lg font-black text-slate-900">{selectedOrder.fullName}</p>
                    <p className="text-xs font-bold text-indigo-600">{selectedOrder.deliveryEmail}</p>
                    <p className="text-xs font-bold text-slate-500 mt-2">WhatsApp: {selectedOrder.whatsappNumber}</p>
                 </div>
                 <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Payment Info</p>
                    <p className="text-sm font-black text-slate-900">{selectedOrder.paymentMethod}</p>
                    <p className="text-[10px] font-mono font-bold text-slate-500 mt-1 break-all">TXID: {selectedOrder.transactionId}</p>
                 </div>
               </div>

               <div className="relative rounded-[2rem] border-2 border-slate-100 overflow-hidden bg-slate-50 flex items-center justify-center min-h-[160px]">
                 {selectedOrder.screenshotUrl ? (
                    <img src={selectedOrder.screenshotUrl} className="w-full h-full object-contain cursor-zoom-in" alt="Proof" onClick={() => window.open(selectedOrder.screenshotUrl, '_blank')} />
                 ) : (
                    <div className="text-center p-4">
                        <svg className="w-10 h-10 text-slate-200 mx-auto mb-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                        <p className="text-[10px] font-black text-slate-300 uppercase">No Screenshot Provided</p>
                    </div>
                 )}
               </div>
             </div>

             <div className="grid grid-cols-2 gap-4">
               <button onClick={() => { onUpdateOrderStatus(selectedOrder.id, 'confirmed'); setSelectedOrder(null); }} className="py-5 bg-green-600 text-white rounded-2xl font-black uppercase text-xs tracking-widest hover:bg-green-700 shadow-xl shadow-green-100 active:scale-95 transition-all">Confirm & Activate</button>
               <button onClick={() => { onUpdateOrderStatus(selectedOrder.id, 'cancelled'); setSelectedOrder(null); }} className="py-5 bg-red-50 text-red-500 rounded-2xl font-black uppercase text-xs tracking-widest hover:bg-red-500 hover:text-white transition-all">Decline Order</button>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Product, Order } from '../types';
import { CATEGORIES, INITIAL_PRODUCTS } from '../constants';
import { supabase } from '../supabaseClient';

interface AdminPanelProps {
  products: Product[];
  orders: Order[];
  onAddProduct: (p: Omit<Product, 'id'>) => void;
  onUpdateProduct: (id: string, p: Partial<Product>) => void;
  onDeleteProduct: (id: string) => void;
  onUpdateOrderStatus: (orderId: string, status: Order['status']) => void;
  onBack: () => void;
}

