                        onClick={() => { if(confirm('Decline this order?')) onUpdateOrderStatus(selectedOrder.id, 'cancelled'); setSelectedOrder(null); }} 
                        className="flex-1 py-4 bg-amber-500 text-white rounded-xl font-black uppercase text-[9px] tracking-widest hover:bg-amber-600 transition-all flex items-center justify-center gap-2"
                    >
                        Decline
                    </button>
                    {onDeleteOrder && (
                        <button 
                            onClick={() => { onDeleteOrder(selectedOrder.id); setSelectedOrder(null); }} 
                            className="py-4 px-6 bg-red-600 text-white rounded-xl font-black uppercase text-[9px] tracking-widest hover:bg-red-700 transition-all flex items-center justify-center gap-2"
                        >
                            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6" /></svg>
                            Delete
                        </button>
                    )}
                    <button onClick={() => setSelectedOrder(null)} className="py-4 px-6 bg-white border border-slate-200 text-slate-400 rounded-xl font-black uppercase text-[9px] tracking-widest hover:bg-slate-900 hover:text-white transition-all">
                        Dismiss
                    </button>
                </div>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useRef, useEffect } from 'react';
