        setLoading(false);
      }
    };

    initialize();
  }, []);

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const isPublished = p.is_published !== false;
      const matchesCategory = selectedCategory === 'All' || p.category === selectedCategory;
      const matchesSearch = p.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                           p.description.toLowerCase().includes(searchQuery.toLowerCase());
      return isPublished && matchesCategory && matchesSearch;
    });
  }, [products, selectedCategory, searchQuery]);

  const handleAddProduct = async (newProduct: Omit<Product, 'id'>) => {
    try {
      const { error } = await supabase
        .from('products')
        .insert([{ ...newProduct, is_published: true }]);

      if (error) throw error;

      alert("✅ Product Published Successfully!");
      await fetchData();
    } catch (err: any) {
      alert("❌ Error: " + err.message);
    }
  };

  const handleUpdateProduct = async (id: string, updatedFields: Partial<Product>) => {
    try {
      const { error } = await supabase
        .from('products')
        .upsert({ ...updatedFields, id: id });

      if (error) throw error;

      alert("✅ Product Updated in Database!");
      await fetchData();
    } catch (err: any) {
      alert("❌ Update Failed: " + err.message);
    }
  };

  const handleDeleteProduct = async (id: string) => {
    try {
      const { error } = await supabase.from('products').delete().eq('id', id);
      if (error) throw error;
      alert("🗑️ Product Removed.");
      await fetchData();
    } catch (err: any) {
      alert("Error: " + err.message);
    }
  };

  const resetToShop = () => {
    setCurrentView('shop');
    setSelectedProduct(null);
    setSelectedCategory('All');
    setSearchQuery('');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleAdminAccessTrigger = () => {
    const now = Date.now();
    if (now - lastClickTime.current > 3000) clickCount.current = 1;
    else clickCount.current += 1;
    lastClickTime.current = now;

    if (clickCount.current >= 5) {
      clickCount.current = 0;
      setShowAdminPassModal(true);
      setAdminInputPass('');
    }
  };

  if (loading) return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50">
      <div className="flex flex-col items-center gap-6">
        <div className="relative w-16 h-16">
          <div className="absolute inset-0 border-4 border-blue-600/10 rounded-full"></div>
          <div className="absolute inset-0 border-4 border-blue-600 rounded-full border-t-transparent animate-spin"></div>
        </div>
        <p className="text-slate-900 font-black uppercase tracking-[0.2em] text-xs">Connecting to DS Vault...</p>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen flex flex-col bg-[#F8FAFC] relative">
      {/* BACKGROUND RAIN EFFECT */}
      {(currentView === 'shop' || currentView === 'profile') && <ProductRain products={products.filter(p => p.is_published !== false)} />}

      <Navbar 
        currentView={currentView} 
        setView={(v) => { if(v === 'shop') resetToShop(); else setCurrentView(v); }} 
        cartCount={cart.reduce((s, i) => s + i.quantity, 0)}
        user={user}
        onLogout={async () => { await supabase.auth.signOut(); setUser(null); setCart([]); resetToShop(); }}
        onAuthClick={() => { setAuthMode('signin'); setIsAuthModalOpen(true); }}
      />

      {currentView === 'shop' && <ProductTicker products={products.filter(p => p.is_published !== false)} onProductClick={(p) => { setSelectedProduct(p); setCurrentView('product-detail'); }} />}

      <main className="flex-1 max-w-7xl mx-auto w-full px-4 sm:px-6 lg:px-8 py-8 relative z-10">
        {currentView === 'shop' ? (
          <div className="space-y-12">
            <div className="relative rounded-[2.5rem] overflow-hidden min-h-[450px] flex items-center shadow-2xl border border-white/10"
              style={{ backgroundImage: 'url("https://images.unsplash.com/photo-1451187580459-43490279c0fa?auto=format&fit=crop&q=80&w=2000")', backgroundSize: 'cover', backgroundPosition: 'center' }}>
              <div className="absolute inset-0 bg-slate-900/80"></div>
              <div className="relative z-10 px-8 md:px-16 w-full lg:w-2/3 text-center md:text-left">
                <h1 className="text-4xl md:text-6xl font-black text-white uppercase tracking-tighter mb-4">DS <span className="text-cyan-400">SERVICE STORE</span></h1>
                <p className="text-sm font-black text-blue-200 uppercase tracking-[0.15em] mb-8 leading-relaxed">Buy Now Apple id, Icloud id, Gmail, Facebook, virtual Visa cards</p>
                <div className="flex flex-wrap justify-center md:justify-start gap-4">
                  <button onClick={() => shopSectionRef.current?.scrollIntoView({ behavior: 'smooth' })} className="px-10 py-4 bg-white text-black rounded-2xl font-black uppercase tracking-widest hover:bg-cyan-400 transition-all shadow-lg active:scale-95">Shop Now</button>
                </div>
              </div>
            </div>

            <div ref={shopSectionRef} className="flex flex-col lg:flex-row gap-4 items-center justify-between bg-white/90 backdrop-blur-md p-4 rounded-3xl border border-slate-200 shadow-sm scroll-mt-24">
              <div className="flex gap-2 overflow-x-auto w-full lg:w-auto pb-2 lg:pb-0 scrollbar-hide">
                {CATEGORIES.map(cat => (
                  <button key={cat} onClick={() => setSelectedCategory(cat)} className={`px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${selectedCategory === cat ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-50'}`}>{cat}</button>
                ))}
              </div>
              <input type="text" placeholder="Search services..." className="w-full lg:w-72 px-5 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none text-sm font-bold" value={searchQuery} onChange={e => setSearchQuery(e.target.value)} />
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8 pb-20">
              {filteredProducts.map(product => (
                <ProductCard key={product.id} product={product} onAddToCart={(p) => {
                   if (!user) { setAuthMode('signin'); setIsAuthModalOpen(true); return; }
                   setCart(prev => {
                     const existing = prev.find(item => item.id === p.id);
                     if (existing) return prev.map(item => item.id === p.id ? { ...item, quantity: item.quantity + 1 } : item);
                     return [...prev, { ...p, quantity: 1 }];
                   });
                   setIsCartOpen(true);
                }} onViewDetails={(p) => { setSelectedProduct(p); setCurrentView('product-detail'); }} />
              ))}
            </div>
          </div>
        ) : currentView === 'product-detail' && selectedProduct ? (
          <ProductDetail product={selectedProduct} onAddToCart={(p, q) => {
            if (!user) { setAuthMode('signin'); setIsAuthModalOpen(true); return; }
            setCart(prev => {
              const existing = prev.find(item => item.id === p.id);
              if (existing) return prev.map(item => item.id === p.id ? { ...item, quantity: item.quantity + q } : item);
              return [...prev, { ...p, quantity: q }];
            });
            setIsCartOpen(true);
          }} onBack={resetToShop} />
        ) : currentView === 'checkout' ? (
          <CheckoutView items={cart} onBack={resetToShop} onSuccess={async (order) => {
            const { error } = await supabase.from('orders').insert([{
              user_id: user?.id,
              items: order.items,
              total: order.total,
              status: 'pending',
              full_name: order.fullName,
              whatsapp_number: order.whatsappNumber,
              delivery_email: order.deliveryEmail,
              payment_method: order.paymentMethod,
              transaction_id: order.transactionId,
              screenshot_url: order.screenshotUrl
            }]);
            if (!error) {
              alert("✅ Order Placed Successfully!");
              setCart([]);
              resetToShop();
              fetchData();
            }
          }} />
        ) : currentView === 'profile' && user ? (
          <ProfileView 
            user={user} 
            orders={orders} 
            onBack={resetToShop} 
            onUpdatePassword={() => { setAuthMode('update'); setIsAuthModalOpen(true); }} 
          />
        ) : currentView === 'admin' && isAdminAuthenticated ? (
          <AdminPanel 
            products={products} 
            orders={orders}
            onAddProduct={handleAddProduct} 
            onUpdateProduct={handleUpdateProduct}
            onDeleteProduct={handleDeleteProduct} 
            onUpdateOrderStatus={async (id, s) => {
              const { error } = await supabase.from('orders').update({ status: s }).eq('id', id);
              if (error) {
                alert("❌ Status Update Failed: " + error.message);
              } else {
                await fetchData();
              }
            }}
            onDeleteOrder={async (id) => {
              if (confirm('Permanently delete this order record?')) {
                const { error } = await supabase.from('orders').delete().eq('id', id);
                if (error) {
                  alert("❌ Delete Failed: " + error.message);
                } else {
                  await fetchData();
                }
              }
            }}
            onBack={resetToShop} 
          />
        ) : (
          <div className="text-center py-20">
            <h2 className="text-2xl font-black text-slate-900 uppercase">Access Denied</h2>
            <button onClick={resetToShop} className="mt-6 px-8 py-3 bg-slate-900 text-white rounded-xl font-black uppercase">Home</button>
          </div>
        )}
      </main>

      {/* ULTRA PREMIUM ADMIN PASS MODAL */}
      {showAdminPassModal && (
        <div className="fixed inset-0 z-[300] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-xl transition-all duration-700">
          <div className="relative bg-white rounded-[4rem] p-12 shadow-[0_30px_90px_-15px_rgba(0,0,0,0.1)] animate-in zoom-in-95 duration-500 w-full max-w-[500px] flex flex-col items-center">
            <div className="relative mb-8">
              <div className="absolute inset-[-8px] rounded-full bg-gradient-to-tr from-[#14F195] via-[#22d3ee] to-[#6366f1] opacity-60"></div>
              <div className="relative w-36 h-36 rounded-full border-4 border-white overflow-hidden shadow-xl z-10">
                <img src={ownerPhotoUrl} alt="Mehedi Hasan" className="w-full h-full object-cover" />
              </div>
              <div className="absolute bottom-1 right-2 w-10 h-10 bg-[#6366f1] rounded-full border-4 border-white flex items-center justify-center z-20 shadow-lg">
                  <svg className="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M9 12.75L11.25 15 15 9.75m-3-7.036A11.959 11.959 0 013.598 6 11.99 11.99 0 003 9.749c0 5.592 3.824 10.29 9 11.623 5.176-1.332 9-6.03 9-11.622 0-1.31-.21-2.571-.598-3.751A11.959 11.959 0 0112 2.714z" /></svg>
              </div>
            </div>
            <div className="text-center mb-10">
              <h2 className="text-3xl font-black text-[#0f172a] uppercase tracking-tight mb-3">Mehedi Hasan</h2>
              <div className="inline-flex items-center gap-2 px-5 py-2 bg-[#0f172a] rounded-full">
                  <span className="w-2.5 h-2.5 bg-[#14F195] rounded-full animate-pulse"></span>
                  <span className="text-[11px] font-black text-white uppercase tracking-[0.2em]">Owner Identity Required</span>
              </div>
            </div>
            <form className="w-full space-y-6" onSubmit={(e) => { 
                e.preventDefault(); 
                if(adminInputPass === ADMIN_PASSWORD) { 
                  setIsAdminAuthenticated(true); 
                  setCurrentView('admin'); 
                  setShowAdminPassModal(false); 
                } else { 
                  setAdminError(true); 
                  setTimeout(() => setAdminError(false), 2000);
                } 
              }}>
              <div className="relative">
                  <input autoFocus type="password" placeholder="ENTER MASTER KEY" className={`w-full px-8 py-7 bg-slate-50/50 border-2 rounded-3xl outline-none text-center font-black tracking-[0.3em] transition-all duration-300 text-lg ${adminError ? 'border-red-500 bg-red-50 text-red-600' : 'border-slate-50 focus:border-slate-100 focus:bg-white focus:shadow-lg focus:shadow-slate-100'}`} value={adminInputPass} onChange={e => setAdminInputPass(e.target.value)} />
                  {adminError && <p className="text-center text-[10px] font-black text-red-500 uppercase mt-2">Incorrect Key! Access Denied</p>}
              </div>
              <div className="grid grid-cols-2 gap-4">
                <button type="button" onClick={() => setShowAdminPassModal(false)} className="py-5 bg-slate-50 text-slate-500 rounded-3xl font-black uppercase text-xs tracking-widest hover:bg-slate-100 transition-all">Return Home</button>
                <button type="submit" className="py-5 bg-[#0f172a] text-white rounded-3xl font-black uppercase text-xs tracking-widest hover:bg-black transition-all flex items-center justify-center gap-2">Unlock Access <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M13 7l5 5m0 0l-5 5m5-5H6" /></svg></button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* FOOTER SECTION - Hidden in Admin Panel view */}
      {currentView !== 'admin' && (
        <footer className="bg-[#0F172A] text-white/30 py-16 mt-20 border-t border-white/5 relative z-10">
          <div className="max-w-7xl mx-auto px-8 flex flex-col md:flex-row items-center md:items-start gap-6">
            <div className="relative flex items-center justify-center w-12 h-12 grayscale opacity-50 hover:grayscale-0 hover:opacity-100 transition-all duration-500 group flex-shrink-0">
              <div className="absolute inset-0 border-2 border-cyan-400/30 group-hover:border-cyan-400 rounded-full border-t-transparent animate-[spin_4s_linear_infinite]"></div>
              <div className="flex items-baseline relative z-10 font-black text-lg">
                <span className="text-blue-500">D</span>
                <span className="text-green-500 -ml-1">S</span>
              </div>
            </div>
            <div className="flex flex-col items-center md:items-start gap-1">
              <p className="text-[12px] font-black text-slate-300 uppercase tracking-widest">Owner: Mehedi Hasan</p>
              <p className="text-[10px] font-bold uppercase tracking-[0.2em] cursor-pointer hover:text-white transition-colors" onClick={handleAdminAccessTrigger}>©2005-2024 DS SERVICE STORE</p>
              <div className="h-0.5 w-8 bg-gradient-to-r from-blue-600 to-green-500 rounded-full opacity-30 mt-1"></div>
            </div>
          </div>
        </footer>
      )}

      <CartDrawer isOpen={isCartOpen} onClose={() => setIsCartOpen(false)} items={cart} onRemove={(id) => setCart(cart.filter(i => i.id !== id))} onUpdateQuantity={(id, q) => setCart(cart.map(i => i.id === id ? {...i, quantity: q} : i))} onCheckout={() => { setIsCartOpen(false); setCurrentView('checkout'); }} />
      <AuthModal isOpen={isAuthModalOpen} initialMode={authMode} onClose={() => setIsAuthModalOpen(false)} onLogin={(u) => setUser(u)} />
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { Product, Order, CartItem } from '../types';
import { CATEGORIES, INITIAL_PRODUCTS } from '../constants';
import { supabase } from '../supabaseClient';

interface AdminPanelProps {
  products: Product[];
  orders: Order[];
  onAddProduct: (p: Omit<Product, 'id'>) => void;
  onUpdateProduct: (id: string, p: Partial<Product>) => void;
  onDeleteProduct: (id: string) => void;
  onUpdateOrderStatus: (orderId: string, status: Order['status']) => void;
  onDeleteOrder?: (id: string) => void;
  onBack: () => void;
}

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  products, 
  orders, 
  onAddProduct, 
  onUpdateProduct,
  onDeleteProduct, 
  onUpdateOrderStatus,
  onDeleteOrder,
  onBack 
}) => {
  const [activeTab, setActiveTab] = useState<'inventory' | 'orders'>('inventory');
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [uploading, setUploading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [dbStatus, setDbStatus] = useState<'checking' | 'ready' | 'not-found'>('checking');
  const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const ownerPhotoUrl = "https://media.licdn.com/dms/image/v2/D5603AQF6FS5z4Ky4RQ/profile-displayphoto-shrink_200_200/B56Zu4YNm2G0AY-/0/1768324915128?e=2147483647&v=beta&t=_coKuJKl31AvjMDdGeLrigjfgyD8rtgblh-J_kP8Ruo";

  const [formData, setFormData] = useState({
    name: '',
    description: '',
    price: 0,
    category: CATEGORIES[1],
    image: '',
    stock: 10,
    rating: 5,
    is_published: true
  });

  useEffect(() => {
    const checkDb = async () => {
      const { error } = await supabase.from('products').select('id').limit(1);
      if (error) setDbStatus('not-found');
      else setDbStatus('ready');
    };
    checkDb();
  }, []);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    try {
      setUploading(true);
      if (!e.target.files || e.target.files.length === 0) return;
      const file = e.target.files[0];
      const filePath = `product-images/${Math.random()}.${file.name.split('.').pop()}`;
      const { error: uploadError } = await supabase.storage.from('products').upload(filePath, file);
      if (uploadError) throw uploadError;
      const { data } = supabase.storage.from('products').getPublicUrl(filePath);
      if (data) {
        setFormData({ ...formData, image: data.publicUrl });
        alert("✅ Image uploaded!");
      }
    } catch (error: any) {
      alert("Error: " + error.message);
    } finally {
      setUploading(false);
    }
  };

  const handleEditClick = (product: Product) => {
    setEditingId(product.id);
    setFormData({
      name: product.name,
      description: product.description,
      price: product.price,
      category: product.category,
      image: product.image,
      stock: product.stock,
      rating: product.rating,
      is_published: product.is_published !== false
    });
    setIsFormOpen(true);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);
    try {
      if (editingId) {
        await onUpdateProduct(editingId, formData);
      } else {
        await onAddProduct(formData);
      }
      resetForm();
    } catch (err) {
      console.error(err);
    } finally {
      setSaving(false);
    }
  };

  const resetForm = () => {
    setIsFormOpen(false);
    setEditingId(null);
    setFormData({ name: '', description: '', price: 0, category: CATEGORIES[1], image: '', stock: 10, rating: 5, is_published: true });
  };

  return (
    <div className="animate-in fade-in duration-700">
      {/* PREMIUM HEADER WITH OWNER INFO */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-8 mb-12 bg-white p-6 rounded-[2.5rem] border border-slate-200 shadow-sm">
        <div className="flex items-center gap-6">
          <div className="relative">
            <div className="absolute inset-[-4px] rounded-full bg-gradient-to-tr from-indigo-500 via-cyan-400 to-green-400 opacity-40 animate-pulse"></div>
            <div className="relative w-16 h-16 rounded-full border-2 border-white overflow-hidden shadow-lg z-10">
              <img src={ownerPhotoUrl} alt="Owner" className="w-full h-full object-cover" />
            </div>
            <div className="absolute -bottom-1 -right-1 w-6 h-6 bg-blue-600 rounded-full border-2 border-white flex items-center justify-center z-20 shadow-md">
                <svg className="w-3 h-3 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="4" d="M5 13l4 4L19 7" /></svg>
            </div>
          </div>
          <div>
            <h1 className="text-xl font-black text-slate-900 uppercase tracking-tight">Mehedi Hasan</h1>
            <p className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em]">DS Service Store</p>
            <div className="flex items-center gap-2 mt-1">
              <span className={`w-1.5 h-1.5 rounded-full ${dbStatus === 'ready' ? 'bg-green-500 animate-pulse' : 'bg-red-500'}`}></span>
              <p className="text-slate-400 text-[9px] font-bold uppercase tracking-widest">System Active</p>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-4 w-full md:w-auto">
          <div className="hidden lg:block text-right mr-4">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Control Panel</p>
              <p className="text-xs font-black text-slate-900 uppercase tracking-tighter">DS Vault Access</p>
          </div>
          <button 
            onClick={onBack} 
            className="flex-1 md:flex-none px-8 py-3.5 bg-slate-900 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-red-600 transition-all shadow-lg shadow-slate-200 active:scale-95 flex items-center justify-center gap-2"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
            Logout Access
          </button>
        </div>
      </div>

      {/* TAB SELECTOR */}
      <div className="flex flex-wrap gap-4 mb-10 bg-slate-100/50 p-2 rounded-[1.8rem] w-fit border border-slate-200/50">
        <button 
          onClick={() => setActiveTab('inventory')}
          className={`px-8 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all flex items-center gap-3 ${activeTab === 'inventory' ? 'bg-white text-indigo-600 shadow-xl shadow-slate-200/50' : 'text-slate-500 hover:text-slate-700'}`}
        >
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4" /></svg>
          Inventory List
        </button>
        <button 
          onClick={() => setActiveTab('orders')}
          className={`px-8 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all flex items-center gap-3 ${activeTab === 'orders' ? 'bg-white text-indigo-600 shadow-xl shadow-slate-200/50' : 'text-slate-500 hover:text-slate-700'}`}
        >
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" /></svg>
          Order Center
          {orders.length > 0 && <span className="px-2 py-0.5 bg-indigo-100 text-indigo-600 rounded-lg text-[9px]">{orders.length}</span>}
        </button>
      </div>

      {activeTab === 'inventory' ? (
        <>
          <div className="flex justify-between items-center mb-8">
            <h2 className="text-sm font-black text-slate-400 uppercase tracking-[0.2em]">Service Catalog Management</h2>
            <button 
              onClick={() => { if(isFormOpen) resetForm(); else setIsFormOpen(true); }}
              className={`px-8 py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl transition-all flex items-center gap-2 ${isFormOpen ? 'bg-slate-200 text-slate-600 shadow-none' : 'bg-indigo-600 text-white shadow-indigo-100 hover:bg-indigo-700'}`}
            >
              {isFormOpen ? (
                  <>
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12" /></svg>
                    Close Editor
                  </>
              ) : (
