               <div className="mt-8 flex gap-4">
                  <button type="submit" className="flex-1 py-5 bg-indigo-600 text-white rounded-2xl font-black uppercase text-[10px]">{saving ? 'Saving...' : 'Save Configuration'}</button>
                  <button type="button" onClick={resetForm} className="px-8 py-5 bg-slate-100 text-slate-500 rounded-2xl font-black uppercase text-[10px]">Cancel</button>
               </div>
            </form>
          )}

          <div className="bg-white rounded-[3rem] border border-slate-200 overflow-hidden shadow-sm">
            <table className="w-full text-left">
              <thead className="bg-slate-50">
                <tr>
                  <th className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase">Service</th>
                  <th className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase">Price</th>
                  <th className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase text-center">Stock</th>
                  <th className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase text-right">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {products.map(p => (
                  <tr key={p.id} className="hover:bg-slate-50/50">
                    <td className="px-10 py-5">
                      <div className="flex items-center gap-4">
                        <img src={p.image} className="w-10 h-10 rounded-lg object-cover" />
                        <div>
                          <p className="font-black text-slate-900 text-sm">{p.name}</p>
                          <p className="text-[9px] font-bold text-slate-400 uppercase">{p.category}</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-10 py-5 font-black text-indigo-600">${p.price.toFixed(2)}</td>
                    <td className="px-10 py-5 text-center font-bold text-slate-500">{p.stock}</td>
                    <td className="px-10 py-5 text-right">
                       <button onClick={() => handleEditClick(p)} className="p-2 text-slate-400 hover:text-indigo-600 mr-2"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M11 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-5M18.364 5.364a2.121 2.121 0 013 3L12 18l-4 1 1-4L18.364 5.364z" /></svg></button>
                       <button onClick={() => { if(confirm('Delete service?')) onDeleteProduct(p.id); }} className="p-2 text-slate-400 hover:text-red-500"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6" /></svg></button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </>
      ) : (
        /* ORDERS CENTER */
        <div className="bg-white rounded-[3rem] border border-slate-200 overflow-hidden shadow-sm">
          <table className="w-full text-left">
             <thead className="bg-slate-50">
               <tr>
                 <th className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase">Customer</th>
                 <th className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase text-center">Amount</th>
                 <th className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase text-center">Status</th>
                 <th className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase text-right">View</th>
               </tr>
             </thead>
             <tbody className="divide-y divide-slate-50">
               {orders.map(o => (
                 <tr key={o.id} className="hover:bg-slate-50/50">
                   <td className="px-10 py-5">
                       <p className="font-black text-slate-900 text-xs">{o.fullName}</p>
                       <p className="text-[9px] font-bold text-slate-400">{o.deliveryEmail}</p>
                   </td>
                   <td className="px-10 py-5 text-center font-black text-slate-900 text-xs">${o.total.toFixed(2)}</td>
                   <td className="px-10 py-5 text-center">
                       <span className={`px-2 py-1 rounded-md text-[8px] font-black uppercase tracking-widest border ${o.status === 'confirmed' ? 'bg-green-50 text-green-600' : 'bg-amber-50 text-amber-600'}`}>{o.status}</span>
                   </td>
                   <td className="px-10 py-5 text-right">
                       <button onClick={() => setSelectedOrder(o)} className="px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-[8px] font-black uppercase tracking-widest">Details</button>
                   </td>
                 </tr>
               ))}
             </tbody>
          </table>
        </div>
      )}

      {/* COMPACT ORDER DOSSIER MODAL */}
      {selectedOrder && (
        <div className="fixed inset-0 z-[400] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/90 backdrop-blur-md" onClick={() => setSelectedOrder(null)} />
          <div className="relative w-full max-w-2xl bg-white rounded-[2rem] shadow-2xl overflow-hidden flex flex-col max-h-[90vh]" onClick={(e) => e.stopPropagation()}>

             <div className="flex items-center justify-between p-5 border-b border-slate-50">
                 <div>
                    <h2 className="text-xl font-black text-slate-900 uppercase">Order Details</h2>
                    <p className="text-[8px] font-black text-slate-400 uppercase mt-0.5">ID: {selectedOrder.id}</p>
                 </div>
                 <button onClick={() => setSelectedOrder(null)} className="w-8 h-8 text-slate-300 hover:text-red-500 transition-all"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M6 18L18 6M6 6l12 12" /></svg></button>
             </div>

             <div className="flex-1 overflow-y-auto p-5 space-y-4">
                <div className="grid grid-cols-2 gap-4">
                    <div className="p-4 bg-slate-50 rounded-xl border border-slate-100">
                        <p className="text-[7px] font-black text-slate-400 uppercase mb-1">Customer</p>
                        <p className="text-xs font-black text-slate-900">{selectedOrder.fullName}</p>
                        <p className="text-[9px] font-bold text-indigo-600">{selectedOrder.deliveryEmail}</p>
                        <p className="text-[8px] font-bold text-slate-400">WA: {selectedOrder.whatsappNumber}</p>
                    </div>
                    <div className="p-4 bg-slate-50 rounded-xl border border-slate-100">
                        <p className="text-[7px] font-black text-slate-400 uppercase mb-1">Payment</p>
                        <p className="text-xs font-black text-slate-900 uppercase">{selectedOrder.paymentMethod}</p>
                        <p className="text-[9px] font-bold text-indigo-600 truncate">TXID: {selectedOrder.transactionId}</p>
                    </div>
                </div>

                <div className="bg-white rounded-xl border border-slate-100 overflow-hidden">
                    <table className="w-full text-left">
                        <thead className="bg-slate-50"><tr className="text-[7px] font-black uppercase text-slate-400"><th className="px-4 py-2">Item</th><th className="px-4 py-2 text-center">Qty</th><th className="px-4 py-2 text-right">Price</th></tr></thead>
                        <tbody className="divide-y divide-slate-50">
                            {selectedOrder.items.map((item, i) => (
                                <tr key={i}><td className="px-4 py-2 text-[9px] font-bold">{item.name}</td><td className="px-4 py-2 text-[9px] text-center">x{item.quantity}</td><td className="px-4 py-2 text-[9px] text-right">${(item.price * item.quantity).toFixed(2)}</td></tr>
                            ))}
                        </tbody>
                    </table>
                </div>

                <div className="h-64 rounded-xl border border-slate-200 overflow-hidden bg-slate-100">
                    {selectedOrder.screenshotUrl ? (
                        <img src={selectedOrder.screenshotUrl} className="w-full h-full object-contain cursor-zoom-in" onClick={() => window.open(selectedOrder.screenshotUrl, '_blank')} />
                    ) : (
                        <div className="h-full flex items-center justify-center text-slate-300 text-[10px] font-bold uppercase">No Screenshot</div>
                    )}
                </div>
             </div>

             <div className="p-5 bg-slate-50 border-t border-slate-100">
                <div className="flex flex-wrap gap-2">
                    <button 
                        onClick={() => { if(confirm('Confirm order?')) { onUpdateOrderStatus(selectedOrder.id, 'confirmed'); setSelectedOrder(null); } }} 
                        className="flex-1 py-3 bg-green-600 text-white rounded-lg font-black uppercase text-[8px] hover:bg-green-700 transition-all"
                    >Confirm Order</button>
                    <button 
                        onClick={() => { if(confirm('Decline order?')) { onUpdateOrderStatus(selectedOrder.id, 'cancelled'); setSelectedOrder(null); } }} 
                        className="flex-1 py-3 bg-amber-500 text-white rounded-lg font-black uppercase text-[8px] hover:bg-amber-600 transition-all"
                    >Decline</button>
                    {onDeleteOrder && (
                        <button 
                            onClick={() => { if(confirm('Delete permanently?')) { onDeleteOrder(selectedOrder.id); setSelectedOrder(null); } }} 
                            className="px-4 py-3 bg-red-600 text-white rounded-lg font-black uppercase text-[8px] hover:bg-red-700 transition-all"
                        >Delete</button>
                    )}
                    <button onClick={() => setSelectedOrder(null)} className="px-4 py-3 bg-white border border-slate-200 text-slate-400 rounded-lg font-black uppercase text-[8px]">Close</button>
                </div>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Navbar } from './components/Navbar';
import { ProductCard } from './components/ProductCard';
import { CartDrawer } from './components/CartDrawer';
import { ProductDetail } from './components/ProductDetail';
import { ProductTicker } from './components/ProductTicker';
import { CheckoutView } from './components/CheckoutView';
import { AuthModal } from './components/AuthModal';
import { AdminPanel } from './components/AdminPanel';
import { ProductRain } from './components/ProductRain';
import { ProfileView } from './components/ProfileView';
import { Product, CartItem, User, View, Order } from './types';
import { INITIAL_PRODUCTS, CATEGORIES } from './constants';
import { supabase } from './supabaseClient';
import { getProductRecommendations } from './services/geminiService';

const App: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [currentView, setCurrentView] = useState<View>('shop');
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [searchQuery, setSearchQuery] = useState('');
  const [user, setUser] = useState<User | null>(null);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
  const [authMode, setAuthMode] = useState<'signin' | 'signup' | 'forgot' | 'update'>('signin');
  const [loading, setLoading] = useState(true);

  const [isAdminAuthenticated, setIsAdminAuthenticated] = useState(false);
  const [showAdminPassModal, setShowAdminPassModal] = useState(false);
  const [adminInputPass, setAdminInputPass] = useState('');
  const [adminError, setAdminError] = useState(false);

  const shopSectionRef = useRef<HTMLDivElement>(null);
  const clickCount = useRef(0);
  const lastClickTime = useRef(0);
  const ADMIN_PASSWORD = "Ajmir@#123";

  const ownerPhotoUrl = "https://media.licdn.com/dms/image/v2/D5603AQF6FS5z4Ky4RQ/profile-displayphoto-shrink_200_200/B56Zu4YNm2G0AY-/0/1768324915128?e=2147483647&v=beta&t=_coKuJKl31AvjMDdGeLrigjfgyD8rtgblh-J_kP8Ruo"; 

  const fetchData = async () => {
    try {
      const { data: dbProducts, error: prodError } = await supabase
        .from('products')
        .select('*')
        .order('name', { ascending: true });

      if (!prodError && dbProducts) {
        setProducts(dbProducts.length > 0 ? dbProducts : INITIAL_PRODUCTS);
      } else {
        setProducts(INITIAL_PRODUCTS);
      }

      const { data: dbOrders, error: orderError } = await supabase
        .from('orders')
        .select('*')
        .order('created_at', { ascending: false });

      if (!orderError && dbOrders) {
        const mappedOrders = dbOrders.map((o: any) => ({
          id: o.id,
          userId: o.user_id,
          items: o.items,
          total: o.total,
          status: o.status,
          createdAt: o.created_at,
          fullName: o.full_name,
          whatsappNumber: o.whatsapp_number,
          deliveryEmail: o.delivery_email || o.deliveryEmail || '',
          paymentMethod: o.payment_method,
          transactionId: o.transaction_id,
          screenshotUrl: o.screenshot_url
        }));
        setOrders(mappedOrders as Order[]);
      }
    } catch (err) {
      console.error("General Fetch Error:", err);
    }
  };

  useEffect(() => {
    const initialize = async () => {
      try {
        const { data: { session } } = await supabase.auth.getSession();
        if (session?.user) {
          setUser({
            id: session.user.id,
            name: session.user.user_metadata.full_name || session.user.email?.split('@')[0] || 'User',
            email: session.user.email || '',
            isAdmin: false
          });
        }
        await fetchData();
      } catch (e) {
        console.error("Initialization error", e);
      } finally {
        setLoading(false);
      }
    };

    initialize();
  }, []);

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const isPublished = p.is_published !== false;
      const matchesCategory = selectedCategory === 'All' || p.category === selectedCategory;
      const matchesSearch = p.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                           p.description.toLowerCase().includes(searchQuery.toLowerCase());
      return isPublished && matchesCategory && matchesSearch;
    });
  }, [products, selectedCategory, searchQuery]);

  const handleAddProduct = async (newProduct: Omit<Product, 'id'>) => {
    try {
      const { error } = await supabase
        .from('products')
        .insert([{ ...newProduct, is_published: true }]);

      if (error) throw error;

      alert("✅ Product Published Successfully!");
      await fetchData();
    } catch (err: any) {
      alert("❌ Error: " + err.message);
    }
  };

  const handleUpdateProduct = async (id: string, updatedFields: Partial<Product>) => {
    try {
      const { error } = await supabase
        .from('products')
        .upsert({ ...updatedFields, id: id });

      if (error) throw error;

      alert("✅ Product Updated in Database!");
      await fetchData();
    } catch (err: any) {
      alert("❌ Update Failed: " + err.message);
    }
  };

  const handleDeleteProduct = async (id: string) => {
    try {
      const { error } = await supabase.from('products').delete().eq('id', id);
      if (error) throw error;
      alert("🗑️ Product Removed.");
      await fetchData();
    } catch (err: any) {
      alert("Error: " + err.message);
    }
  };

  const resetToShop = () => {
    setCurrentView('shop');
    setSelectedProduct(null);
    setSelectedCategory('All');
    setSearchQuery('');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleAdminAccessTrigger = () => {
    const now = Date.now();
    if (now - lastClickTime.current > 3000) clickCount.current = 1;
    else clickCount.current += 1;
    lastClickTime.current = now;

    if (clickCount.current >= 5) {
      clickCount.current = 0;
      setShowAdminPassModal(true);
      setAdminInputPass('');
    }
  };

  if (loading) return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50">
      <div className="flex flex-col items-center gap-6">
        <div className="relative w-16 h-16">
          <div className="absolute inset-0 border-4 border-blue-600/10 rounded-full"></div>
          <div className="absolute inset-0 border-4 border-blue-600 rounded-full border-t-transparent animate-spin"></div>
        </div>
        <p className="text-slate-900 font-black uppercase tracking-[0.2em] text-xs">Connecting to DS Vault...</p>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen flex flex-col bg-[#F8FAFC] relative">
      {(currentView === 'shop' || currentView === 'profile') && <ProductRain products={products.filter(p => p.is_published !== false)} />}

      <Navbar 
        currentView={currentView} 
        setView={(v) => { if(v === 'shop') resetToShop(); else setCurrentView(v); }} 
        cartCount={cart.reduce((s, i) => s + i.quantity, 0)}
        user={user}
        onLogout={async () => { await supabase.auth.signOut(); setUser(null); setCart([]); resetToShop(); }}
        onAuthClick={() => { setAuthMode('signin'); setIsAuthModalOpen(true); }}
      />

      {currentView === 'shop' && <ProductTicker products={products.filter(p => p.is_published !== false)} onProductClick={(p) => { setSelectedProduct(p); setCurrentView('product-detail'); }} />}

      <main className="flex-1 max-w-7xl mx-auto w-full px-4 sm:px-6 lg:px-8 py-8 relative z-10">
        {currentView === 'shop' ? (
          <div className="space-y-12">
            <div className="relative rounded-[2.5rem] overflow-hidden min-h-[450px] flex items-center shadow-2xl border border-white/10"
              style={{ backgroundImage: 'url("https://images.unsplash.com/photo-1451187580459-43490279c0fa?auto=format&fit=crop&q=80&w=2000")', backgroundSize: 'cover', backgroundPosition: 'center' }}>
              <div className="absolute inset-0 bg-slate-900/80"></div>
              <div className="relative z-10 px-8 md:px-16 w-full lg:w-2/3 text-center md:text-left">
                <h1 className="text-4xl md:text-6xl font-black text-white uppercase tracking-tighter mb-4">DS <span className="text-cyan-400">SERVICE STORE</span></h1>
                <p className="text-sm font-black text-blue-200 uppercase tracking-[0.15em] mb-8 leading-relaxed">Buy Now Apple id, Icloud id, Gmail, Facebook, virtual Visa cards</p>
                <div className="flex flex-wrap justify-center md:justify-start gap-4">
                  <button onClick={() => shopSectionRef.current?.scrollIntoView({ behavior: 'smooth' })} className="px-10 py-4 bg-white text-black rounded-2xl font-black uppercase tracking-widest hover:bg-cyan-400 transition-all shadow-lg active:scale-95">Shop Now</button>
                </div>
              </div>
            </div>

            <div ref={shopSectionRef} className="flex flex-col lg:flex-row gap-4 items-center justify-between bg-white/90 backdrop-blur-md p-4 rounded-3xl border border-slate-200 shadow-sm scroll-mt-24">
              <div className="flex gap-2 overflow-x-auto w-full lg:w-auto pb-2 lg:pb-0 scrollbar-hide">
                {CATEGORIES.map(cat => (
                  <button key={cat} onClick={() => setSelectedCategory(cat)} className={`px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${selectedCategory === cat ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-50'}`}>{cat}</button>
                ))}
              </div>
              <input type="text" placeholder="Search services..." className="w-full lg:w-72 px-5 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none text-sm font-bold" value={searchQuery} onChange={e => setSearchQuery(e.target.value)} />
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8 pb-20">
              {filteredProducts.map(product => (
                <ProductCard key={product.id} product={product} onAddToCart={(p) => {
                   if (!user) { setAuthMode('signin'); setIsAuthModalOpen(true); return; }
                   setCart(prev => {
                     const existing = prev.find(item => item.id === p.id);
                     if (existing) return prev.map(item => item.id === p.id ? { ...item, quantity: item.quantity + 1 } : item);
                     return [...prev, { ...p, quantity: 1 }];
                   });
                   setIsCartOpen(true);
                }} onViewDetails={(p) => { setSelectedProduct(p); setCurrentView('product-detail'); }} />
              ))}
            </div>
          </div>
        ) : currentView === 'product-detail' && selectedProduct ? (
          <ProductDetail product={selectedProduct} onAddToCart={(p, q) => {
            if (!user) { setAuthMode('signin'); setIsAuthModalOpen(true); return; }
            setCart(prev => {
              const existing = prev.find(item => item.id === p.id);
              if (existing) return prev.map(item => item.id === p.id ? { ...item, quantity: item.quantity + q } : item);
              return [...prev, { ...p, quantity: q }];
            });
            setIsCartOpen(true);
          }} onBack={resetToShop} />
        ) : currentView === 'checkout' ? (
          <CheckoutView items={cart} onBack={resetToShop} onSuccess={async (order) => {
            const { error } = await supabase.from('orders').insert([{
              user_id: user?.id,
              items: order.items,
              total: order.total,
              status: 'pending',
              full_name: order.fullName,
              whatsapp_number: order.whatsappNumber,
              delivery_email: order.deliveryEmail,
              payment_method: order.paymentMethod,
              transaction_id: order.transactionId,
              screenshot_url: order.screenshotUrl
            }]);
            if (!error) {
              alert("✅ Order Placed Successfully!");
              setCart([]);
              resetToShop();
              fetchData();
            }
          }} />
        ) : currentView === 'profile' && user ? (
          <ProfileView 
            user={user} 
            orders={orders} 
            onBack={resetToShop} 
            onUpdatePassword={() => { setAuthMode('update'); setIsAuthModalOpen(true); }} 
          />
        ) : currentView === 'admin' && isAdminAuthenticated ? (
          <AdminPanel 
            products={products} 
            orders={orders}
            onAddProduct={handleAddProduct} 
            onUpdateProduct={handleUpdateProduct}
            onDeleteProduct={handleDeleteProduct} 
            onUpdateOrderStatus={async (id, s) => {
              const { error } = await supabase.from('orders').update({ status: s }).eq('id', id);
              if (!error) await fetchData();
              else alert("❌ Error updating status: " + error.message);
            }}
            onDeleteOrder={async (id) => {
              if (confirm('Permanently delete this order record?')) {
                const { error } = await supabase.from('orders').delete().eq('id', id);
                if (!error) await fetchData();
                else alert("❌ Error deleting order: " + error.message);
              }
            }}
            onBack={resetToShop} 
          />
        ) : (
          <div className="text-center py-20">
            <h2 className="text-2xl font-black text-slate-900 uppercase">Access Denied</h2>
            <button onClick={resetToShop} className="mt-6 px-8 py-3 bg-slate-900 text-white rounded-xl font-black uppercase">Home</button>
          </div>
        )}
      </main>

      {/* ULTRA-PREMIUM ADMIN PASS MODAL */}
      {showAdminPassModal && (
        <div className="fixed inset-0 z-[300] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-2xl transition-all duration-700">
