              {products.sort((a,b) => a.stock - b.stock).slice(0, 6).map(p => (
                <div key={p.id} className="flex items-center gap-4">
                  <div className="flex-1">
                    <div className="flex justify-between mb-1">
                      <span className="text-[10px] font-black uppercase text-slate-700">{p.name}</span>
                      <span className={`text-[10px] font-black ${p.stock <= 5 ? 'text-red-500' : 'text-slate-400'}`}>{p.stock} Units</span>
                    </div>
                    <div className="h-2 bg-slate-100 rounded-full overflow-hidden">
                      <div className={`h-full transition-all duration-1000 ${p.stock <= 5 ? 'bg-red-500' : 'bg-blue-600'}`} style={{ width: `${Math.min(100, (p.stock / 50) * 100)}%` }}></div>
