  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const isPublished = p.is_published !== false;
      const matchesCategory = selectedCategory === 'All' || p.category === selectedCategory;
      const matchesSearch = p.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                           p.description.toLowerCase().includes(searchQuery.toLowerCase());
      return isPublished && matchesCategory && matchesSearch;
    });
  }, [products, selectedCategory, searchQuery]);

  const handleAddProduct = async (newProduct: Omit<Product, 'id'>) => {
    try {
      const { error } = await supabase
        .from('products')
        .insert([{ ...newProduct, is_published: true }]);

      if (error) throw error;

      alert("✅ Product Published Successfully!");
      await fetchData();
    } catch (err: any) {
      alert("❌ Error: " + err.message);
    }
  };

  const handleUpdateProduct = async (id: string, updatedFields: Partial<Product>) => {
    try {
      const { error } = await supabase
        .from('products')
        .upsert({ ...updatedFields, id: id });

      if (error) throw error;

      alert("✅ Product Updated in Database!");
      await fetchData();
    } catch (err: any) {
      alert("❌ Update Failed: " + err.message);
    }
  };

  const handleDeleteProduct = async (id: string) => {
    try {
      const { error } = await supabase.from('products').delete().eq('id', id);
      if (error) throw error;
      alert("🗑️ Product Removed.");
      await fetchData();
    } catch (err: any) {
      alert("Error: " + err.message);
    }
  };

  const handleUpdateOrderStatus = async (orderId: string, newStatus: Order['status']) => {
    try {
      const orderToUpdate = orders.find(o => o.id === orderId);
      if (!orderToUpdate) return;

      // Robust Stock Deduction when status transitions to 'delivered'
      if (newStatus === 'delivered' && orderToUpdate.status !== 'delivered') {
        for (const item of orderToUpdate.items) {
          // 1. Fetch the absolute latest stock from DB to avoid race conditions
          const { data: currentProduct, error: fetchError } = await supabase
            .from('products')
            .select('stock')
            .eq('id', item.id)
            .single();

          if (!fetchError && currentProduct) {
            const currentStock = currentProduct.stock;
            const deduction = item.quantity;
            const finalStock = Math.max(0, currentStock - deduction);

            // 2. Perform the update
            await supabase
              .from('products')
              .update({ stock: finalStock })
              .eq('id', item.id);
          }
        }
      }

      // Update the order status itself
      const { error: orderUpdateError } = await supabase
        .from('orders')
        .update({ status: newStatus })
        .eq('id', orderId);

      if (orderUpdateError) throw orderUpdateError;

      // Refresh local state
      await fetchData();

      if (newStatus === 'delivered') {
        alert(`✅ Order Fulfilled! Stock reduced by total units sold in this order.`);
      } else {
        alert(`✅ Order status updated to: ${newStatus.toUpperCase()}`);
