                          </div>
                          <button onClick={() => copyToClipboard(bdNumber, 'nagad')} className={`px-4 py-2 rounded-xl text-xs font-bold transition-all ${copiedId === 'nagad' ? 'bg-orange-500' : 'bg-white/10 hover:bg-white/20'}`}>
                            {copiedId === 'nagad' ? 'Copied!' : 'Copy'}
