                <span className={`text-[9px] md:text-[10px] font-black uppercase tracking-tighter ${isOutOfStock ? 'text-red-500' : isLowStock ? 'text-amber-600' : 'text-slate-400'}`}>
                    {isOutOfStock ? 'Sold Out' : `In Stock`}
