                        <select className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-black focus:border-blue-600 appearance-none" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                          {categories.length === 0 && <option value="">No categories - Run DB Setup</option>}
                          {categories.map(c => <option key={c.id} value={c.name}>{c.name}</option>)}
                        </select>
                      </div>
                      <div className="space-y-2">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Service Narrative</label>
                        <textarea required className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-bold h-40 focus:border-blue-600 resize-none" value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} />
                      </div>

                      <div className="p-6 bg-slate-50 rounded-[2rem] border border-slate-100 space-y-4">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Visibility Status</label>
                        <div className="flex gap-4">
                           <button 
                            type="button" 
                            onClick={() => setFormData({...formData, isPublic: true})}
                            className={`flex-1 py-4 rounded-xl font-black text-[10px] uppercase tracking-widest flex items-center justify-center gap-2 border-2 transition-all ${formData.isPublic ? 'bg-green-600 border-green-600 text-white shadow-lg' : 'bg-white border-slate-200 text-slate-400 hover:border-green-200'}`}
                           >
                             <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542 7z" /></svg>
                             Public
                           </button>
                           <button 
                            type="button" 
                            onClick={() => setFormData({...formData, isPublic: false})}
                            className={`flex-1 py-4 rounded-xl font-black text-[10px] uppercase tracking-widest flex items-center justify-center gap-2 border-2 transition-all ${!formData.isPublic ? 'bg-slate-900 border-slate-900 text-white shadow-lg' : 'bg-white border-slate-200 text-slate-400 hover:border-slate-400'}`}
                           >
                             <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88L4.59 4.59m9.531 9.53l5.29 5.29M21.542 12c-1.274 4.057-5.064 7-9.542 7-1.042 0-2.052-.132-3.016-.381m10.114-10.114A9.957 9.957 0 0121.543 12z" /></svg>
                             Unpublic
                           </button>
                        </div>
                      </div>
                    </div>

                    {/* Right side: Photo & Price */}
                    <div className="space-y-6">
                       <div className="space-y-2">
                          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Service Photo (Device Upload)</label>
                          <div 
                            onClick={() => fileInputRef.current?.click()}
                            className="relative aspect-video rounded-[2.5rem] border-4 border-dashed border-slate-100 bg-slate-50 hover:bg-slate-100 hover:border-blue-400 transition-all cursor-pointer overflow-hidden flex flex-col items-center justify-center group"
                          >
                            {formData.image ? (
                              <img src={formData.image} className="w-full h-full object-cover group-hover:scale-105 transition-transform" />
                            ) : (
                              <div className="text-center p-6">
                                <div className="w-16 h-16 bg-white rounded-2xl shadow-sm flex items-center justify-center mx-auto mb-4 text-slate-300 group-hover:text-blue-500 transition-colors">
                                  <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                                </div>
                                <p className="font-black text-slate-900 text-sm uppercase">Choose Photo</p>
                              </div>
                            )}
                            {uploading && (
                              <div className="absolute inset-0 bg-white/80 backdrop-blur-sm flex flex-col items-center justify-center">
                                <div className="w-10 h-10 border-4 border-blue-600 border-t-transparent rounded-full animate-spin"></div>
                                <p className="text-[10px] font-black text-blue-600 mt-4 uppercase animate-pulse">Uploading to Server...</p>
                              </div>
                            )}
                          </div>
                          <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileUpload} />
                       </div>

                       <div className="grid grid-cols-2 gap-4">
                         <div className="space-y-2">
                            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Unit Valuation ($)</label>
                            <input type="number" step="0.01" className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-black text-blue-600 text-xl" value={formData.price} onChange={e => setFormData({...formData, price: parseFloat(e.target.value)})} />
                         </div>
                         <div className="space-y-2">
                            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Initial Stock</label>
                            <input type="number" className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-black text-xl" value={formData.stock} onChange={e => setFormData({...formData, stock: parseInt(e.target.value)})} />
                         </div>
                       </div>

                       <div className="pt-4 flex gap-4">
                          <button type="submit" disabled={uploading || saving} className="flex-1 py-5 bg-blue-600 text-white rounded-2xl font-black uppercase text-xs tracking-widest shadow-xl hover:bg-slate-900 transition-all">
                            {saving ? 'Processing...' : (editingId ? 'Update Service' : 'Confirm Launch')}
                          </button>
                          <button type="button" onClick={resetForm} className="px-8 py-5 bg-slate-100 text-slate-500 rounded-2xl font-black uppercase text-xs">Abandon</button>
                       </div>
                    </div>
                 </div>
              </form>
           )}

           <div className="bg-white rounded-[3rem] border border-slate-200 overflow-hidden shadow-sm">
              <table className="w-full text-left">
                <thead className="bg-slate-50">
                  <tr>
                    <th className="px-10 py-7 text-[10px] font-black text-slate-400 uppercase tracking-widest">Service Item</th>
                    <th className="px-10 py-7 text-[10px] font-black text-slate-400 uppercase tracking-widest">Valuation</th>
                    <th className="px-10 py-7 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Stock / Visibility</th>
                    <th className="px-10 py-7 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Operational Tools</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {products.map(p => (
                    <tr key={p.id} className="hover:bg-slate-50 transition-colors group">
                      <td className="px-10 py-6">
                        <div className="flex items-center gap-5">
                          <img src={p.image} className="w-14 h-14 rounded-2xl object-cover border-2 border-slate-100 shadow-sm transition-transform group-hover:scale-110" />
                          <div>
                            <p className="font-black text-slate-900 text-sm tracking-tight">{p.name}</p>
                            <p className="text-[9px] font-black text-blue-600 uppercase tracking-widest">{p.category}</p>
                          </div>
                        </div>
                      </td>
                      <td className="px-10 py-6"><span className="font-black text-slate-900">${p.price.toFixed(2)}</span></td>
                      <td className="px-10 py-6 text-center">
                        <div className="flex flex-col items-center gap-2">
                           <span className={`px-4 py-1.5 rounded-xl text-[9px] font-black border-2 ${p.stock <= 5 ? 'bg-red-50 border-red-200 text-red-600' : 'bg-white border-slate-100 text-slate-700'}`}>
                             {p.stock} Units
                           </span>
                           <span className={`px-3 py-1 rounded-lg text-[8px] font-black uppercase tracking-widest border ${p.isPublic ? 'bg-green-50 text-green-600 border-green-100' : 'bg-slate-100 text-slate-500 border-slate-200'}`}>
                              {p.isPublic ? '● Public' : '○ Private'}
                           </span>
                        </div>
                      </td>
                      <td className="px-10 py-6 text-right">
                         <div className="flex justify-end gap-3 opacity-0 group-hover:opacity-100 transition-opacity">
                            <button onClick={() => handleEditClick(p)} className="w-10 h-10 flex items-center justify-center bg-white border border-slate-200 rounded-xl text-slate-400 hover:text-blue-600 transition-all"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M11 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-5M18.364 5.364a2.121 2.121 0 013 3L12 18l-4 1 1-4L18.364 5.364z" /></svg></button>
                            <button onClick={() => { if(confirm('Terminate this service?')) onDeleteProduct(p.id); }} className="w-10 h-10 flex items-center justify-center bg-white border border-slate-200 rounded-xl text-slate-400 hover:text-red-500 transition-all"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6" /></svg></button>
                         </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
           </div>
        </div>
      )}

      {activeTab === 'orders' && (
        <div className="animate-in slide-in-from-bottom-6 duration-700">
           <div className="bg-white rounded-[3rem] border border-slate-200 overflow-hidden shadow-sm">
              <table className="w-full text-left">
                 <thead className="bg-slate-50">
                   <tr>
                     <th className="px-10 py-7 text-[10px] font-black text-slate-400 uppercase tracking-widest">Digital Consignee</th>
                     <th className="px-10 py-7 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Amount ($)</th>
                     <th className="px-10 py-7 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Lifecycle Status</th>
                     <th className="px-10 py-7 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Dossier</th>
                   </tr>
                 </thead>
                 <tbody className="divide-y divide-slate-100">
                   {orders.map(o => (
                     <tr key={o.id} className="hover:bg-slate-50 transition-colors group">
                       <td className="px-10 py-6">
                           <p className="font-black text-slate-900 text-sm tracking-tight">{o.fullName}</p>
                           <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">{o.deliveryEmail}</p>
                       </td>
                       <td className="px-10 py-6 text-center font-black text-slate-900 text-sm">${o.total.toFixed(2)}</td>
                       <td className="px-10 py-6 text-center">
                           <span className={`px-4 py-1.5 rounded-xl text-[9px] font-black uppercase tracking-[0.15em] border-2 ${o.status === 'confirmed' || o.status === 'delivered' ? 'bg-green-50 border-green-200 text-green-600' : o.status === 'cancelled' ? 'bg-red-50 border-red-200 text-red-600' : 'bg-amber-50 border-amber-200 text-amber-600 animate-pulse'}`}>
                              {o.status}
                           </span>
                       </td>
                       <td className="px-10 py-6 text-right">
                           <button onClick={() => setSelectedOrder(o)} className="px-6 py-2.5 bg-white border border-slate-200 rounded-xl text-[9px] font-black uppercase tracking-widest text-slate-500 hover:border-blue-600 hover:text-blue-600 transition-all shadow-sm">Review File</button>
                       </td>
                     </tr>
                   ))}
                 </tbody>
              </table>
           </div>
        </div>
      )}

      {selectedOrder && (
        <div className="fixed inset-0 z-[400] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/90 backdrop-blur-xl transition-opacity duration-700" onClick={() => setSelectedOrder(null)} />
          <div className="relative w-full max-w-2xl bg-white rounded-[3rem] shadow-2xl overflow-hidden flex flex-col max-h-[90vh] animate-in zoom-in-95 duration-500">
             <div className="flex items-center justify-between p-8 border-b border-slate-100 bg-slate-50/50">
                 <div>
                    <h2 className="text-2xl font-black text-slate-900 uppercase tracking-tighter">Order Dossier</h2>
                 </div>
                 <button onClick={() => setSelectedOrder(null)} className="w-10 h-10 text-slate-300 hover:text-red-500 transition-all hover:rotate-90"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12" /></svg></button>
             </div>
             <div className="flex-1 overflow-y-auto p-8 space-y-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="p-6 bg-slate-900 rounded-[2rem] text-white space-y-4">
                        <p className="text-[8px] font-black text-slate-500 uppercase tracking-[0.2em]">Consignee File</p>
                        <div className="space-y-1">
                          <p className="text-lg font-black">{selectedOrder.fullName}</p>
                          <p className="text-xs font-bold text-cyan-400 underline">{selectedOrder.deliveryEmail}</p>
                        </div>
                    </div>
                    <div className="p-6 bg-blue-50 rounded-[2rem] border border-blue-100 flex flex-col justify-between">
                        <div className="space-y-1">
                          <p className="text-[8px] font-black text-blue-400 uppercase tracking-[0.2em]">Financial Summary</p>
                          <p className="text-3xl font-black text-blue-600">${selectedOrder.total.toFixed(2)}</p>
                        </div>
                    </div>
                </div>
                <div className="bg-white rounded-[2rem] border border-slate-100 overflow-hidden shadow-inner">
                    <div className="bg-slate-50 px-6 py-3 border-b border-slate-100 flex justify-between">
                       <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Provisioning Manifest</span>
                    </div>
                    <div className="max-h-32 overflow-y-auto p-4 space-y-2">
                        {selectedOrder.items.map((item, i) => (
                            <div key={i} className="flex justify-between items-center text-xs font-black">
                               <span className="text-slate-900 uppercase tracking-tight">{item.name}</span>
                               <span className="text-slate-400">x{item.quantity}</span>
                            </div>
                        ))}
                    </div>
                </div>
                {selectedOrder.screenshotUrl && (
                   <div className="h-64 rounded-[2.5rem] border border-slate-200 overflow-hidden bg-slate-50">
                      <img src={selectedOrder.screenshotUrl} className="w-full h-full object-contain cursor-zoom-in" onClick={() => window.open(selectedOrder.screenshotUrl, '_blank')} />
                   </div>
                )}
             </div>
             <div className="p-8 bg-slate-50/50 border-t border-slate-100">
                <div className="flex flex-wrap gap-3">
                    {selectedOrder.status === 'pending' && (
                        <>
                            <button onClick={() => { onUpdateOrderStatus(selectedOrder.id, 'confirmed'); setSelectedOrder(null); }} className="flex-1 py-4 bg-green-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest hover:bg-green-700 transition-all shadow-xl shadow-green-100 flex items-center justify-center gap-3">
                                Authorize Order
                            </button>
                        </>
                    )}
                    <button onClick={() => setSelectedOrder(null)} className="px-6 py-4 bg-white border border-slate-200 text-slate-400 rounded-2xl font-black uppercase text-[10px] tracking-widest hover:bg-slate-900 hover:text-white transition-all">Dismiss</button>
                </div>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

export interface Product {
  id: string;
  name: string;
  description: string;
  price: number;
  category: string;
  image: string;
  stock: number;
  rating: number;
  isPublic: boolean;
}

export interface Category {
  id: string;
  name: string;
  created_at?: string;
}

export interface CartItem extends Product {
  quantity: number;
}

export interface User {
  id: string;
  name: string;
  email: string;
  isAdmin: boolean;
}

export interface Order {
  id: string;
  userId: string;
  items: CartItem[];
  total: number;
  status: 'pending' | 'confirmed' | 'delivered' | 'cancelled';
  createdAt: string;
  fullName: string;
  whatsappNumber: string;
  deliveryEmail: string;
  paymentMethod: string;
  transactionId: string;
  screenshotUrl?: string;
}

export interface Notification {
  id: string;
  message: string;
  type: 'order_status' | 'system';
  createdAt: string;
  isRead: boolean;
  orderId?: string;
}

export type View = 'shop' | 'product-detail' | 'checkout' | 'cart' | 'admin' | 'profile';

import React, { useState } from 'react';
import { View, User, Notification } from '../types';

interface NavbarProps {
  currentView: View;
  setView: (view: View) => void;
  cartCount: number;
  user: User | null;
  notifications: Notification[];
  onLogout: () => void;
  onAuthClick: () => void;
  onMarkNotificationsRead: () => void;
}

export const Navbar: React.FC<NavbarProps> = ({ 
  currentView, 
  setView, 
  cartCount, 
  user, 
  notifications,
  onLogout, 
  onAuthClick,
  onMarkNotificationsRead
}) => {
  const [isNotifOpen, setIsNotifOpen] = useState(false);
  const unreadCount = notifications.filter(n => !n.isRead).length;

  return (
    <nav className="sticky top-0 z-50 bg-white/80 backdrop-blur-md border-b border-slate-200">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center h-20">
          {/* LEFT SIDE: LOGO + NAVIGATION */}
          <div className="flex items-center gap-12">
            <div className="flex items-center gap-4 cursor-pointer group" onClick={() => setView('shop')}>
              <div className="relative flex items-center justify-center w-12 h-12">
                <div className="absolute inset-0 border-2 border-cyan-400 rounded-full border-t-transparent animate-[spin_3s_linear_infinite]"></div>
                <div className="absolute inset-1 border border-blue-500 rounded-full border-b-transparent animate-[spin_2s_linear_infinite_reverse]"></div>
                <div className="flex items-baseline relative z-10 font-black text-lg">
                  <span className="text-blue-600 drop-shadow-sm">D</span>
                  <span className="text-green-500 -ml-1 drop-shadow-sm">S</span>
                </div>
              </div>
              <div className="flex flex-col">
                <div className="flex items-center gap-2">
                  <span className="text-xl font-bold tracking-tight text-slate-900 group-hover:text-blue-600 transition-colors">
                    DS <span className="font-medium text-slate-600">SERVICE STORE</span>
                  </span>
                </div>
              </div>
            </div>
          </div>

          {/* RIGHT SIDE: ACTIONS */}
          <div className="flex items-center gap-2 sm:gap-4">
            {/* NOTIFICATION BELL */}
            {user && (
              <div className="relative">
                <button 
                  onClick={() => { setIsNotifOpen(!isNotifOpen); if(!isNotifOpen) onMarkNotificationsRead(); }}
                  className="p-2.5 bg-slate-50 rounded-xl text-slate-600 hover:text-blue-600 hover:bg-white hover:shadow-md transition-all relative"
                >
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 17h5l-1.405-1.405A2.032 2.032 0 0118 14.158V11a6.002 6.002 0 00-4-5.659V5a2 2 0 10-4 0v.341C7.67 6.165 6 8.388 6 11v3.159c0 .538-.214 1.055-.595 1.436L4 17h5m6 0v1a3 3 0 11-6 0v-1m6 0H9" />
                  </svg>
                  {unreadCount > 0 && (
                    <span className="absolute top-2 right-2.5 w-2.5 h-2.5 bg-red-500 border-2 border-white rounded-full"></span>
                  )}
                </button>

                {/* NOTIFICATION DROPDOWN */}
                {isNotifOpen && (
                  <div className="absolute right-0 mt-3 w-80 bg-white rounded-3xl shadow-2xl border border-slate-100 overflow-hidden animate-in zoom-in-95 duration-200">
                    <div className="p-5 border-b border-slate-50 flex items-center justify-between bg-slate-50/50">
                      <span className="text-[10px] font-black text-slate-900 uppercase tracking-widest">Notifications</span>
                      {unreadCount > 0 && <span className="bg-blue-600 text-white text-[8px] font-black px-2 py-0.5 rounded-full uppercase">New</span>}
                    </div>
                    <div className="max-h-[350px] overflow-y-auto">
                      {notifications.length === 0 ? (
                        <div className="p-10 text-center">
                          <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest">No notifications yet</p>
                        </div>
                      ) : (
                        notifications.map(n => (
                          <div key={n.id} className={`p-4 border-b border-slate-50 hover:bg-slate-50 transition-colors ${!n.isRead ? 'bg-blue-50/30' : ''}`}>
                            <div className="flex gap-3">
                              <div className={`w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 ${n.type === 'order_status' ? 'bg-blue-100 text-blue-600' : 'bg-green-100 text-green-600'}`}>
                                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                              </div>
                              <div className="flex-1">
                                <p className="text-[11px] font-bold text-slate-900 leading-relaxed">{n.message}</p>
                                <p className="text-[9px] font-black text-slate-400 uppercase tracking-tighter mt-1">{new Date(n.createdAt).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</p>
                              </div>
                            </div>
                          </div>
                        ))
                      )}
                    </div>
                  </div>
                )}
              </div>
            )}

            <button 
              onClick={() => setView('cart')}
              className="relative p-2.5 bg-slate-50 rounded-xl text-slate-600 hover:text-blue-600 hover:bg-white hover:shadow-md transition-all"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" />
              </svg>
              {cartCount > 0 && (
                <span className="absolute -top-1 -right-1 bg-blue-600 text-white text-[10px] font-black px-1.5 py-0.5 rounded-full ring-2 ring-white">
                  {cartCount}
                </span>
              )}
            </button>

            {user ? (
              <div className="flex items-center gap-3 pl-2 border-l border-slate-200">
                <div className="hidden sm:block text-right">
                  <p className="text-xs font-black text-slate-900 cursor-pointer hover:text-blue-600 transition-colors" onClick={() => setView('profile')}>{user.name}</p>
                  <button onClick={onLogout} className="text-[10px] text-slate-400 hover:text-red-500 font-bold uppercase tracking-tighter">Sign Out</button>
                </div>
                <div 
                  className="w-10 h-10 rounded-2xl bg-gradient-to-br from-blue-500 to-green-400 p-[2px] cursor-pointer hover:scale-105 transition-transform"
                  onClick={() => setView('profile')}
                >
                    <div className="w-full h-full rounded-[14px] bg-white flex items-center justify-center text-xs font-black text-blue-600">
                        {user.name.charAt(0)}
                    </div>
                </div>
              </div>
            ) : (
              <div className="flex items-center gap-2">
                <button onClick={onAuthClick} className="hidden sm:block text-sm font-black text-slate-600 hover:text-blue-600 px-4 py-2.5 transition-all">Sign In</button>
                <button onClick={onAuthClick} className="text-sm font-black bg-slate-900 text-white px-6 py-2.5 rounded-xl hover:bg-blue-600 transition-all shadow-lg shadow-slate-200">Sign Up</button>
              </div>
            )}
          </div>
        </div>
      </div>
    </nav>
  );
};

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Navbar } from './components/Navbar';
import { ProductCard } from './components/ProductCard';
import { CartDrawer } from './components/CartDrawer';
import { ProductDetail } from './components/ProductDetail';
import { ProductTicker } from './components/ProductTicker';
import { CheckoutView } from './components/CheckoutView';
import { AuthModal } from './components/AuthModal';
import { AdminPanel } from './components/AdminPanel';
import { ProductRain } from './components/ProductRain';
import { ProfileView } from './components/ProfileView';
import { HeroBanner } from './components/HeroBanner';
import { Product, CartItem, User, View, Order, Category, Notification } from './types';
import { INITIAL_PRODUCTS } from './constants';
import { supabase } from './supabaseClient';

const App: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [currentView, setCurrentView] = useState<View>('shop');
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [searchQuery, setSearchQuery] = useState('');
  const [user, setUser] = useState<User | null>(null);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
  const [authMode, setAuthMode] = useState<'signin' | 'signup' | 'forgot' | 'update'>('signin');
  const [loading, setLoading] = useState(true);

  const [isAdminAuthenticated, setIsAdminAuthenticated] = useState(false);
  const [showAdminPassModal, setShowAdminPassModal] = useState(false);
  const [adminInputPass, setAdminInputPass] = useState('');

  const shopSectionRef = useRef<HTMLDivElement>(null);
  const clickCount = useRef(0);
  const lastClickTime = useRef(0);
  const ADMIN_PASSWORD = "Ajmir@#123";
  const ADMIN_SESSION_KEY = "ds_admin_session_v1";
  const TWENTY_FOUR_HOURS = 24 * 60 * 60 * 1000;

  const ownerPhotoUrl = "https://media.licdn.com/dms/image/v2/D5603AQF6FS5z4Ky4RQ/profile-displayphoto-shrink_200_200/B56Zu4YNm2G0AY-/0/1768324915128?e=2147483647&v=beta&t=_coKuJKl31AvjMDdGeLrigjfgyD8rtgblh-J_kP8Ruo"; 

  const fetchData = async () => {
    try {
      // Fetch Categories
      const { data: dbCats, error: catError } = await supabase
        .from('categories')
        .select('*')
        .order('name', { ascending: true });

      if (!catError && dbCats) {
        setCategories(dbCats);
      }

      // Fetch Products
      const { data: dbProducts, error: prodError } = await supabase
        .from('products')
        .select('*')
        .order('name', { ascending: true });

      if (!prodError && dbProducts) {
        const mappedProducts = (dbProducts as any[]).map((p: any) => ({
          ...p,
          isPublic: p.is_public !== undefined ? p.is_public : true
        }));
        setProducts(mappedProducts.length > 0 ? mappedProducts : INITIAL_PRODUCTS);
      }

      // Fetch Orders
      const { data: dbOrders, error: orderError } = await supabase
        .from('orders')
        .select('*')
        .order('created_at', { ascending: false });

      if (!orderError && dbOrders) {
        const mappedOrders = (dbOrders as any[]).map((o: any) => ({
          id: o.id,
          userId: o.user_id,
          items: o.items,
          total: o.total,
          status: o.status,
          createdAt: o.created_at,
          fullName: o.full_name,
          whatsappNumber: o.whatsapp_number,
          deliveryEmail: o.delivery_email || o.deliveryEmail || '',
          paymentMethod: o.payment_method,
          transactionId: o.transaction_id,
          screenshotUrl: o.screenshot_url
        }));
        setOrders(mappedOrders as Order[]);
      }
    } catch (err) {
      console.error("General Fetch Error:", err);
    }
  };

  // REAL-TIME NOTIFICATIONS LOGIC
  useEffect(() => {
    if (!user) {
      setNotifications([]);
      return;
    }

    // Load existing notifications from local storage for persistence
    const stored = localStorage.getItem(`notifs_${user.id}`);
    if (stored) setNotifications(JSON.parse(stored));

    // Subscribe to Orders Table Changes
    const channel = supabase
      .channel('order_updates')
      .on(
        'postgres_changes',
        { event: 'UPDATE', schema: 'public', table: 'orders', filter: `user_id=eq.${user.id}` },
        (payload) => {
          const newStatus = payload.new.status;
          const oldStatus = payload.old.status;

          if (newStatus !== oldStatus) {
            const newNotif: Notification = {
              id: Date.now().toString(),
              message: `Your Order ID: #${payload.new.id.slice(0,8)} is now ${newStatus.toUpperCase()}`,
              type: 'order_status',
              createdAt: new Date().toISOString(),
              isRead: false,
              orderId: payload.new.id
            };
            setNotifications(prev => {
              const updated = [newNotif, ...prev];
              localStorage.setItem(`notifs_${user.id}`, JSON.stringify(updated.slice(0, 20))); // Keep last 20
              return updated;
            });
            // Show simple toast alert for live feedback
            alert(`🔔 Order Update: Your order is now ${newStatus}!`);
          }
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [user]);

  useEffect(() => {
    const initialize = async () => {
      try {
        const storedSession = localStorage.getItem(ADMIN_SESSION_KEY);
        if (storedSession) {
          const sessionData = JSON.parse(storedSession);
          const now = Date.now();
          if (now - sessionData.timestamp < TWENTY_FOUR_HOURS) {
            setIsAdminAuthenticated(true);
          } else {
            localStorage.removeItem(ADMIN_SESSION_KEY);
          }
        }

        const { data: { session } } = await supabase.auth.getSession();
        if (session?.user) {
          setUser({
            id: session.user.id,
            name: session.user.user_metadata.full_name || session.user.email?.split('@')[0] || 'User',
            email: session.user.email || '',
            isAdmin: false
          });
        }
        await fetchData();
      } catch (e) {
        console.error("Initialization error", e);
      } finally {
        setLoading(false);
      }
    };

    initialize();
  }, []);

  const handleMarkNotifsRead = () => {
    if (!user) return;
    setNotifications(prev => {
      const updated = prev.map(n => ({ ...n, isRead: true }));
      localStorage.setItem(`notifs_${user.id}`, JSON.stringify(updated));
      return updated;
    });
  };

  const handleAddCategory = async (name: string) => {
    const { error } = await supabase.from('categories').insert([{ name }]);
    if (error) throw error;
    await fetchData();
  };

  const handleUpdateCategory = async (id: string, name: string) => {
    const { error } = await supabase.from('categories').update({ name }).eq('id', id);
    if (error) throw error;
    await fetchData();
  };

  const handleDeleteCategory = async (id: string) => {
    const { error } = await supabase.from('categories').delete().eq('id', id);
    if (error) throw error;
    await fetchData();
  };

  const handleAddProduct = async (p: Omit<Product, 'id'>) => {
    const { error } = await supabase.from('products').insert([{
      name: p.name,
      description: p.description,
      price: p.price,
      category: p.category,
      image: p.image,
      stock: p.stock,
      rating: p.rating,
      is_public: p.isPublic
    }]);
    if (error) return;
    await fetchData();
  };

  const handleUpdateProduct = async (id: string, p: Partial<Product>) => {
    const updateData: any = { ...p };
    if (p.isPublic !== undefined) {
      updateData.is_public = p.isPublic;
      delete updateData.isPublic;
    }
    const { error } = await supabase.from('products').update(updateData).eq('id', id);
    if (error) return;
    await fetchData();
  };

  const handleDeleteProduct = async (id: string) => {
    const { error } = await supabase.from('products').delete().eq('id', id);
    if (error) return;
    await fetchData();
  };

  const handleUpdateOrderStatus = async (orderId: string, status: Order['status']) => {
    const { error } = await supabase.from('orders').update({ status }).eq('id', orderId);
    if (error) return;
    await fetchData();
  };

  const dynamicCategories = useMemo(() => {
    return ['All', ...categories.map(c => c.name)];
  }, [categories]);

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const isVisible = currentView === 'admin' || p.isPublic;
      const matchesCategory = selectedCategory === 'All' || p.category === selectedCategory;
      const matchesSearch = p.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                           p.description.toLowerCase().includes(searchQuery.toLowerCase());
      return isVisible && matchesCategory && matchesSearch;
    });
  }, [products, selectedCategory, searchQuery, currentView]);

  const resetToShop = () => {
    setCurrentView('shop');
    setSelectedProduct(null);
    setSelectedCategory('All');
    setSearchQuery('');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleAdminAccessTrigger = () => {
    if (isAdminAuthenticated) {
      setCurrentView('admin');
      return;
    }
    const now = Date.now();
    if (now - lastClickTime.current > 3000) clickCount.current = 1;
    else clickCount.current += 1;
    lastClickTime.current = now;

    if (clickCount.current >= 5) {
      clickCount.current = 0;
      setShowAdminPassModal(true);
      setAdminInputPass('');
    }
  };

  const handleAdminLogout = () => {
    localStorage.removeItem(ADMIN_SESSION_KEY);
    setIsAdminAuthenticated(false);
    resetToShop();
  };

  if (loading) return (
    <div className="min-h-screen flex items-center justify-center bg-white">
      <div className="flex flex-col items-center gap-8">
        <div className="w-12 h-12 border-[6px] border-[#0F172A] border-t-transparent rounded-full animate-spin"></div>
        <p className="text-[#0F172A] font-black uppercase tracking-[0.3em] text-[10px] animate-pulse">Server Connection Established</p>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen flex flex-col bg-[#F8FAFC] relative">
      {(currentView === 'shop' || currentView === 'profile') && <ProductRain products={products.filter(p => p.isPublic)} />}

      <Navbar 
        currentView={currentView} 
        setView={(v) => { if(v === 'shop') resetToShop(); else setCurrentView(v); }} 
        cartCount={cart.reduce((s, i) => s + i.quantity, 0)}
        user={user}
        notifications={notifications}
        onLogout={async () => { await supabase.auth.signOut(); setUser(null); setCart([]); resetToShop(); }}
        onAuthClick={() => { setAuthMode('signin'); setIsAuthModalOpen(true); }}
        onMarkNotificationsRead={handleMarkNotifsRead}
      />

      {currentView === 'shop' && <ProductTicker products={products.filter(p => p.isPublic)} onProductClick={(p) => { setSelectedProduct(p); setCurrentView('product-detail'); }} />}

      <main className="flex-1 max-w-7xl mx-auto w-full px-4 sm:px-6 lg:px-8 py-4 md:py-6 relative z-10">
        {currentView === 'shop' ? (
          <div className="space-y-4 md:space-y-6">
            <HeroBanner onShopClick={() => shopSectionRef.current?.scrollIntoView({ behavior: 'smooth' })} />

            <div ref={shopSectionRef} className="bg-white border border-slate-200 rounded-2xl md:rounded-[2rem] p-1 shadow-sm flex flex-col md:flex-row items-center gap-1 md:gap-4 sticky top-24 z-30">
                <div className="flex flex-wrap items-center gap-1 w-full md:flex-1 p-1">
                    {dynamicCategories.map(cat => (
                        <button 
                            key={cat} 
                            onClick={() => setSelectedCategory(cat)} 
                            className={`px-3 py-1.5 md:px-4 md:py-2 rounded-xl text-[8px] md:text-[9px] font-black uppercase tracking-tight md:tracking-widest transition-all whitespace-nowrap
                                ${selectedCategory === cat ? 'bg-[#0F172A] text-white shadow-md' : 'text-slate-400 hover:bg-slate-50'}`}
                        >
                            {cat}
                        </button>
                    ))}
                </div>
                <div className="w-full md:w-auto p-1 md:pr-2">
                    <input 
                      type="text" 
                      placeholder="Search..." 
                      className="w-full md:w-40 px-4 py-1.5 md:py-2 bg-slate-50 border border-slate-100 rounded-xl outline-none text-[10px] md:text-xs font-bold focus:bg-white focus:border-blue-600 transition-all" 
                      value={searchQuery} 
                      onChange={e => setSearchQuery(e.target.value)} 
                    />
                </div>
            </div>

            <div className="pb-24">
                <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4 md:gap-8 px-1 md:px-2 animate-in fade-in duration-1000">
                  {filteredProducts.map(product => (
                    <ProductCard key={product.id} product={product} onAddToCart={(p) => {
                       if (!user) { setAuthMode('signin'); setIsAuthModalOpen(true); return; }
                       setCart(prev => {
                         const existing = prev.find(item => item.id === p.id);
                         if (existing) return prev.map(item => item.id === p.id ? { ...item, quantity: item.quantity + 1 } : item);
                         return [...prev, { ...p, quantity: 1 }];
                       });
                       setIsCartOpen(true);
                    }} onViewDetails={(p) => { setSelectedProduct(p); setCurrentView('product-detail'); }} />
                  ))}
                </div>
            </div>
          </div>
        ) : currentView === 'product-detail' && selectedProduct ? (
          <ProductDetail product={selectedProduct} onAddToCart={(p, q) => {
            if (!user) { setAuthMode('signin'); setIsAuthModalOpen(true); return; }
            setCart(prev => {
              const existing = prev.find(item => item.id === p.id);
              if (existing) return prev.map(item => item.id === p.id ? { ...item, quantity: item.quantity + q } : item);
              return [...prev, { ...p, quantity: q }];
            });
            setIsCartOpen(true);
          }} onBack={resetToShop} />
        ) : currentView === 'checkout' ? (
          <CheckoutView items={cart} onBack={resetToShop} onSuccess={async (order) => {
            const { error, data } = await supabase.from('orders').insert([{
              user_id: user?.id,
              items: order.items,
              total: order.total,
              status: 'pending',
              full_name: order.fullName,
              whatsapp_number: order.whatsappNumber,
              delivery_email: order.deliveryEmail,
              payment_method: order.paymentMethod,
              transaction_id: order.transactionId,
              screenshot_url: order.screenshotUrl
            }]).select();
            if (!error) {
              const newNotif: Notification = {
                id: Date.now().toString(),
                message: `✅ Order Placed! ID: #${data[0].id.slice(0,8)}. Admin will verify soon.`,
                type: 'system',
                createdAt: new Date().toISOString(),
                isRead: false
              };
              setNotifications(prev => [newNotif, ...prev]);
              setCart([]);
              resetToShop();
              fetchData();
            }
          }} />
        ) : currentView === 'profile' && user ? (
          <ProfileView user={user} orders={orders} onBack={resetToShop} onUpdatePassword={() => { setAuthMode('update'); setIsAuthModalOpen(true); }} />
        ) : currentView === 'admin' && isAdminAuthenticated ? (
          <AdminPanel 
            products={products} 
            orders={orders} 
            categories={categories}
            onAddProduct={handleAddProduct} 
            onUpdateProduct={handleUpdateProduct} 
            onDeleteProduct={handleDeleteProduct} 
            onUpdateOrderStatus={handleUpdateOrderStatus}
            onAddCategory={handleAddCategory}
            onUpdateCategory={handleUpdateCategory}
            onDeleteCategory={handleDeleteCategory}
            onBack={handleAdminLogout} 
          />
        ) : (
          <div className="text-center py-20"><button onClick={resetToShop} className="px-12 py-5 bg-[#0F172A] text-white rounded-[2rem] font-black uppercase tracking-widest shadow-2xl">Return to Catalog</button></div>
        )}
      </main>

      {/* Admin Pass Modal */}
      {showAdminPassModal && (
        <div className="fixed inset-0 z-[300] flex items-center justify-center p-4 bg-[#0F172A]/80 backdrop-blur-3xl transition-all duration-700 animate-in fade-in">
          <div className="relative bg-white rounded-[4rem] p-12 shadow-[0_50px_100px_rgba(0,0,0,0.4)] animate-in zoom-in-95 duration-500 w-full max-w-[440px] flex flex-col items-center">
            <div className="relative mb-10 group">
              <div className="absolute inset-[-15px] rounded-full border-2 border-dashed border-blue-500/30 animate-[spin_10s_linear_infinite]"></div>
              <div className="absolute inset-[-10px] rounded-full bg-gradient-to-tr from-blue-600 via-cyan-400 to-blue-600 opacity-20 blur-xl group-hover:opacity-40 transition-opacity duration-700"></div>
              <div className="relative w-40 h-40 rounded-full border-[8px] border-white overflow-hidden shadow-2xl z-10 transition-transform duration-700 group-hover:scale-105">
                <img src={ownerPhotoUrl} alt="Mehedi Hasan" className="w-full h-full object-cover" />
              </div>
              <div className="absolute bottom-2 right-2 z-20 w-10 h-10 bg-white rounded-full flex items-center justify-center shadow-lg border-2 border-slate-50 scale-100 group-hover:scale-110 transition-transform duration-500">
                <svg className="w-6 h-6 text-blue-600 fill-current" viewBox="0 0 24 24"><path d="M9 16.17L4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41z" /></svg>
              </div>
            </div>
            <div className="text-center mb-10">
                <h3 className="text-3xl font-black text-[#0F172A] uppercase tracking-tighter">Mehedi Hasan</h3>
                <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.5em] whitespace-nowrap">Security Terminal</h2>
            </div>
            <form className="w-full space-y-8" onSubmit={(e) => { 
                e.preventDefault(); 
                if(adminInputPass === ADMIN_PASSWORD) { 
                  localStorage.setItem(ADMIN_SESSION_KEY, JSON.stringify({ auth: true, timestamp: Date.now() }));
                  setIsAdminAuthenticated(true); setCurrentView('admin'); setShowAdminPassModal(false); 
                } else { alert("❌ Invalid Identity Key"); }
              }}>
              <input type="password" placeholder="••••••••" className="w-full px-8 py-6 bg-slate-50 border-2 border-slate-100 rounded-[2.5rem] text-center font-black tracking-[0.8em] transition-all text-2xl focus:border-blue-500 focus:bg-white outline-none shadow-inner" value={adminInputPass} onChange={e => setAdminInputPass(e.target.value)} />
              <button type="submit" className="w-full py-6 bg-[#0F172A] text-white rounded-[2.5rem] font-black uppercase text-xs tracking-[0.3em] hover:bg-blue-600 shadow-2xl transition-all">Authorize Access</button>
            </form>
            <button onClick={() => setShowAdminPassModal(false)} className="mt-10 text-[9px] font-black text-slate-300 uppercase tracking-widest hover:text-red-500 transition-colors">Cancel Authentication</button>
          </div>
        </div>
      )}

      <footer className="bg-white border-t border-slate-100 py-16 mt-20 relative z-10">
        <div className="max-w-7xl mx-auto px-8 flex flex-col md:flex-row items-center justify-between gap-10">
          <div className="flex items-center gap-4">
            <div className="relative flex items-center justify-center w-12 h-12 flex-shrink-0 group">
              <div className="absolute inset-0 border border-cyan-400/40 rounded-full group-hover:border-cyan-400 transition-colors"></div>
              <div className="flex items-baseline relative z-10 font-black text-sm"><span className="text-blue-600">D</span><span className="text-green-500 -ml-0.5">S</span></div>
            </div>
            <div className="flex flex-col items-start">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-0.5">Platform Owner</p>
              <p className="text-xs font-black text-slate-900 uppercase tracking-widest cursor-pointer hover:text-blue-600 transition-colors" onClick={handleAdminAccessTrigger}>Mehedi Hasan • DS STORE GLOBAL</p>
            </div>
          </div>
          <p className="text-[9px] font-black text-slate-300 uppercase tracking-[0.3em]">© 2005-2025 DS SERVICE STORE</p>
        </div>
      </footer>

      <CartDrawer isOpen={isCartOpen} onClose={() => setIsCartOpen(false)} items={cart} onRemove={(id) => setCart(cart.filter(i => i.id !== id))} onUpdateQuantity={(id, q) => setCart(cart.map(i => i.id === id ? {...i, quantity: q} : i))} onCheckout={() => { setIsCartOpen(false); setCurrentView('checkout'); }} />
      <AuthModal isOpen={isAuthModalOpen} initialMode={authMode} onClose={() => setIsAuthModalOpen(false)} onLogin={(u) => setUser(u)} />
    </div>
  );
};

export default App;

export interface Product {
  id: string;
  name: string;
  description: string;
  price: number;
  category: string;
  image: string;
  stock: number;
  rating: number;
  isPublic: boolean;
}

export interface Category {
  id: string;
  name: string;
  created_at?: string;
}

export interface CartItem extends Product {
  quantity: number;
}

export interface User {
  id: string;
  name: string;
  email: string;
  isAdmin: boolean;
}

export interface Order {
  id: string;
  userId: string;
  items: CartItem[];
  total: number;
  status: 'pending' | 'confirmed' | 'delivered' | 'cancelled';
  createdAt: string;
  fullName: string;
  whatsappNumber: string;
  deliveryEmail: string;
  paymentMethod: string;
  transactionId: string;
  screenshotUrl?: string;
}

export interface Notification {
  id: string;
  message: string;
  type: 'order_status' | 'system';
  createdAt: string;
  isRead: boolean;
  orderId?: string;
}

export type View = 'shop' | 'product-detail' | 'checkout' | 'cart' | 'admin' | 'profile' | 'contact';

import React, { useState } from 'react';
import { View, User, Notification } from '../types';

interface NavbarProps {
  currentView: View;
  setView: (view: View) => void;
  cartCount: number;
  user: User | null;
  notifications: Notification[];
  onLogout: () => void;
  onAuthClick: () => void;
  onMarkNotificationsRead: () => void;
  onServicesClick: () => void;
}

export const Navbar: React.FC<NavbarProps> = ({ 
  currentView, 
  setView, 
  cartCount, 
  user, 
  notifications,
  onLogout, 
  onAuthClick,
  onMarkNotificationsRead,
  onServicesClick
}) => {
  const [isNotifOpen, setIsNotifOpen] = useState(false);
  const unreadCount = notifications.filter(n => !n.isRead).length;

  return (
    <nav className="sticky top-0 z-50 bg-white/80 backdrop-blur-md border-b border-slate-200">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center h-20">
          {/* LEFT SIDE: LOGO + NAVIGATION */}
          <div className="flex items-center gap-8 md:gap-12">
            <div className="flex items-center gap-4 cursor-pointer group" onClick={() => setView('shop')}>
              <div className="relative flex items-center justify-center w-10 h-10 md:w-12 md:h-12">
                <div className="absolute inset-0 border-2 border-cyan-400 rounded-full border-t-transparent animate-[spin_3s_linear_infinite]"></div>
                <div className="absolute inset-1 border border-blue-500 rounded-full border-b-transparent animate-[spin_2s_linear_infinite_reverse]"></div>
                <div className="flex items-baseline relative z-10 font-black text-sm md:text-lg">
                  <span className="text-blue-600 drop-shadow-sm">D</span>
                  <span className="text-green-500 -ml-1 drop-shadow-sm">S</span>
                </div>
              </div>
              <div className="hidden sm:flex flex-col">
                <span className="text-base md:text-xl font-bold tracking-tight text-slate-900 group-hover:text-blue-600 transition-colors">
                  DS <span className="font-medium text-slate-600">STORE</span>
                </span>
              </div>
            </div>

            {/* NAV LINKS */}
            <div className="flex items-center gap-4 md:gap-8">
              <button 
                onClick={onServicesClick}
                className="text-[10px] md:text-xs font-black text-slate-500 hover:text-blue-600 uppercase tracking-widest transition-colors"
              >
                Services
              </button>
              <button 
                onClick={() => setView('contact')}
                className={`text-[10px] md:text-xs font-black uppercase tracking-widest transition-colors ${currentView === 'contact' ? 'text-blue-600' : 'text-slate-500 hover:text-blue-600'}`}
              >
                Contact
              </button>
            </div>
          </div>

          {/* RIGHT SIDE: ACTIONS */}
          <div className="flex items-center gap-2 sm:gap-4">
            {/* NOTIFICATION BELL */}
            {user && (
              <div className="relative">
                <button 
                  onClick={() => { setIsNotifOpen(!isNotifOpen); if(!isNotifOpen) onMarkNotificationsRead(); }}
                  className="p-2.5 bg-slate-50 rounded-xl text-slate-600 hover:text-blue-600 hover:bg-white hover:shadow-md transition-all relative"
                >
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 17h5l-1.405-1.405A2.032 2.032 0 0118 14.158V11a6.002 6.002 0 00-4-5.659V5a2 2 0 10-4 0v.341C7.67 6.165 6 8.388 6 11v3.159c0 .538-.214 1.055-.595 1.436L4 17h5m6 0v1a3 3 0 11-6 0v-1m6 0H9" />
                  </svg>
                  {unreadCount > 0 && (
                    <span className="absolute top-2 right-2.5 w-2.5 h-2.5 bg-red-500 border-2 border-white rounded-full"></span>
                  )}
                </button>

                {/* NOTIFICATION DROPDOWN */}
                {isNotifOpen && (
                  <div className="absolute right-0 mt-3 w-80 bg-white rounded-3xl shadow-2xl border border-slate-100 overflow-hidden animate-in zoom-in-95 duration-200">
                    <div className="p-5 border-b border-slate-50 flex items-center justify-between bg-slate-50/50">
                      <span className="text-[10px] font-black text-slate-900 uppercase tracking-widest">Notifications</span>
                      {unreadCount > 0 && <span className="bg-blue-600 text-white text-[8px] font-black px-2 py-0.5 rounded-full uppercase">New</span>}
                    </div>
                    <div className="max-h-[350px] overflow-y-auto">
                      {notifications.length === 0 ? (
                        <div className="p-10 text-center">
                          <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest">No notifications yet</p>
                        </div>
                      ) : (
                        notifications.map(n => (
                          <div key={n.id} className={`p-4 border-b border-slate-50 hover:bg-slate-50 transition-colors ${!n.isRead ? 'bg-blue-50/30' : ''}`}>
                            <div className="flex gap-3">
                              <div className={`w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 ${n.type === 'order_status' ? 'bg-blue-100 text-blue-600' : 'bg-green-100 text-green-600'}`}>
                                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                              </div>
                              <div className="flex-1">
                                <p className="text-[11px] font-bold text-slate-900 leading-relaxed">{n.message}</p>
                                <p className="text-[9px] font-black text-slate-400 uppercase tracking-tighter mt-1">{new Date(n.createdAt).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</p>
                              </div>
                            </div>
                          </div>
                        ))
                      )}
                    </div>
                  </div>
                )}
              </div>
            )}

            <button 
              onClick={() => setView('cart')}
              className="relative p-2.5 bg-slate-50 rounded-xl text-slate-600 hover:text-blue-600 hover:bg-white hover:shadow-md transition-all"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" />
              </svg>
              {cartCount > 0 && (
                <span className="absolute -top-1 -right-1 bg-blue-600 text-white text-[10px] font-black px-1.5 py-0.5 rounded-full ring-2 ring-white">
                  {cartCount}
                </span>
              )}
            </button>

            {user ? (
              <div className="flex items-center gap-3 pl-2 border-l border-slate-200">
                <div className="hidden sm:block text-right">
                  <p className="text-xs font-black text-slate-900 cursor-pointer hover:text-blue-600 transition-colors" onClick={() => setView('profile')}>{user.name}</p>
                  <button onClick={onLogout} className="text-[10px] text-slate-400 hover:text-red-500 font-bold uppercase tracking-tighter">Sign Out</button>
                </div>
                <div 
                  className="w-10 h-10 rounded-2xl bg-gradient-to-br from-blue-500 to-green-400 p-[2px] cursor-pointer hover:scale-105 transition-transform"
                  onClick={() => setView('profile')}
                >
                    <div className="w-full h-full rounded-[14px] bg-white flex items-center justify-center text-xs font-black text-blue-600">
                        {user.name.charAt(0)}
                    </div>
                </div>
              </div>
            ) : (
              <div className="flex items-center gap-2">
                <button onClick={onAuthClick} className="hidden sm:block text-sm font-black text-slate-600 hover:text-blue-600 px-4 py-2.5 transition-all">Sign In</button>
                <button onClick={onAuthClick} className="text-sm font-black bg-slate-900 text-white px-6 py-2.5 rounded-xl hover:bg-blue-600 transition-all shadow-lg shadow-slate-200">Sign Up</button>
              </div>
            )}
          </div>
        </div>
      </div>
    </nav>
  );
};

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Navbar } from './components/Navbar';
import { ProductCard } from './components/ProductCard';
import { CartDrawer } from './components/CartDrawer';
import { ProductDetail } from './components/ProductDetail';
import { ProductTicker } from './components/ProductTicker';
import { CheckoutView } from './components/CheckoutView';
import { AuthModal } from './components/AuthModal';
import { AdminPanel } from './components/AdminPanel';
import { ProductRain } from './components/ProductRain';
import { ProfileView } from './components/ProfileView';
import { HeroBanner } from './components/HeroBanner';
import { ContactView } from './components/ContactView';
import { Product, CartItem, User, View, Order, Category, Notification } from './types';
import { INITIAL_PRODUCTS } from './constants';
import { supabase } from './supabaseClient';

const App: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [currentView, setCurrentView] = useState<View>('shop');
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [searchQuery, setSearchQuery] = useState('');
  const [user, setUser] = useState<User | null>(null);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
  const [authMode, setAuthMode] = useState<'signin' | 'signup' | 'forgot' | 'update'>('signin');
  const [loading, setLoading] = useState(true);

  const [isAdminAuthenticated, setIsAdminAuthenticated] = useState(false);
  const [showAdminPassModal, setShowAdminPassModal] = useState(false);
  const [adminInputPass, setAdminInputPass] = useState('');

  const shopSectionRef = useRef<HTMLDivElement>(null);
  const clickCount = useRef(0);
  const lastClickTime = useRef(0);
  const ADMIN_PASSWORD = "Ajmir@#123";
  const ADMIN_SESSION_KEY = "ds_admin_session_v1";
  const TWENTY_FOUR_HOURS = 24 * 60 * 60 * 1000;

  const ownerPhotoUrl = "https://media.licdn.com/dms/image/v2/D5603AQF6FS5z4Ky4RQ/profile-displayphoto-shrink_200_200/B56Zu4YNm2G0AY-/0/1768324915128?e=2147483647&v=beta&t=_coKuJKl31AvjMDdGeLrigjfgyD8rtgblh-J_kP8Ruo"; 

  const fetchData = async () => {
    try {
      // Fetch Categories
      const { data: dbCats, error: catError } = await supabase
        .from('categories')
        .select('*')
        .order('name', { ascending: true });

      if (!catError && dbCats) {
        setCategories(dbCats);
      }

      // Fetch Products
      const { data: dbProducts, error: prodError } = await supabase
        .from('products')
        .select('*')
        .order('name', { ascending: true });

      if (!prodError && dbProducts) {
        const mappedProducts = (dbProducts as any[]).map((p: any) => ({
          ...p,
          isPublic: p.is_public !== undefined ? p.is_public : true
        }));
        setProducts(mappedProducts.length > 0 ? mappedProducts : INITIAL_PRODUCTS);
      }

      // Fetch Orders
      const { data: dbOrders, error: orderError } = await supabase
        .from('orders')
        .select('*')
        .order('created_at', { ascending: false });

      if (!orderError && dbOrders) {
        const mappedOrders = (dbOrders as any[]).map((o: any) => ({
          id: o.id,
          userId: o.user_id,
          items: o.items,
          total: o.total,
          status: o.status,
          createdAt: o.created_at,
          fullName: o.full_name,
          whatsappNumber: o.whatsapp_number,
          deliveryEmail: o.delivery_email || o.deliveryEmail || '',
          paymentMethod: o.payment_method,
          transactionId: o.transaction_id,
          screenshotUrl: o.screenshot_url
        }));
        setOrders(mappedOrders as Order[]);
      }
    } catch (err) {
      console.error("General Fetch Error:", err);
    }
  };

  // REAL-TIME NOTIFICATIONS LOGIC
  useEffect(() => {
    if (!user) {
      setNotifications([]);
      return;
    }

    // Load existing notifications from local storage for persistence
    const stored = localStorage.getItem(`notifs_${user.id}`);
    if (stored) setNotifications(JSON.parse(stored));

    // Subscribe to Orders Table Changes
    const channel = supabase
      .channel('order_updates')
      .on(
        'postgres_changes',
        { event: 'UPDATE', schema: 'public', table: 'orders', filter: `user_id=eq.${user.id}` },
        (payload) => {
          const newStatus = payload.new.status;
          const oldStatus = payload.old.status;

          if (newStatus !== oldStatus) {
            const newNotif: Notification = {
              id: Date.now().toString(),
              message: `Your Order ID: #${payload.new.id.slice(0,8)} is now ${newStatus.toUpperCase()}`,
              type: 'order_status',
              createdAt: new Date().toISOString(),
              isRead: false,
              orderId: payload.new.id
            };
            setNotifications(prev => {
              const updated = [newNotif, ...prev];
              localStorage.setItem(`notifs_${user.id}`, JSON.stringify(updated.slice(0, 20))); // Keep last 20
              return updated;
            });
            // Show simple toast alert for live feedback
            alert(`🔔 Order Update: Your order is now ${newStatus}!`);
          }
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [user]);

  useEffect(() => {
    const initialize = async () => {
      try {
        const storedSession = localStorage.getItem(ADMIN_SESSION_KEY);
        if (storedSession) {
          const sessionData = JSON.parse(storedSession);
          const now = Date.now();
          if (now - sessionData.timestamp < TWENTY_FOUR_HOURS) {
            setIsAdminAuthenticated(true);
          } else {
            localStorage.removeItem(ADMIN_SESSION_KEY);
          }
        }

        const { data: { session } } = await supabase.auth.getSession();
        if (session?.user) {
          setUser({
            id: session.user.id,
            name: session.user.user_metadata.full_name || session.user.email?.split('@')[0] || 'User',
            email: session.user.email || '',
            isAdmin: false
          });
        }
        await fetchData();
      } catch (e) {
        console.error("Initialization error", e);
      } finally {
        setLoading(false);
      }
    };

    initialize();
  }, []);

  const handleMarkNotifsRead = () => {
    if (!user) return;
    setNotifications(prev => {
      const updated = prev.map(n => ({ ...n, isRead: true }));
      localStorage.setItem(`notifs_${user.id}`, JSON.stringify(updated));
      return updated;
    });
  };

  const handleAddCategory = async (name: string) => {
    const { error } = await supabase.from('categories').insert([{ name }]);
    if (error) throw error;
    await fetchData();
  };

  const handleUpdateCategory = async (id: string, name: string) => {
    const { error } = await supabase.from('categories').update({ name }).eq('id', id);
    if (error) throw error;
    await fetchData();
  };

  const handleDeleteCategory = async (id: string) => {
    const { error } = await supabase.from('categories').delete().eq('id', id);
    if (error) throw error;
    await fetchData();
  };

  const handleAddProduct = async (p: Omit<Product, 'id'>) => {
    const { error } = await supabase.from('products').insert([{
      name: p.name,
      description: p.description,
      price: p.price,
      category: p.category,
      image: p.image,
      stock: p.stock,
      rating: p.rating,
      is_public: p.isPublic
    }]);
    if (error) return;
    await fetchData();
  };

  const handleUpdateProduct = async (id: string, p: Partial<Product>) => {
    const updateData: any = { ...p };
    if (p.isPublic !== undefined) {
      updateData.is_public = p.isPublic;
      delete updateData.isPublic;
    }
    const { error } = await supabase.from('products').update(updateData).eq('id', id);
    if (error) return;
    await fetchData();
  };

  const handleDeleteProduct = async (id: string) => {
    const { error } = await supabase.from('products').delete().eq('id', id);
    if (error) return;
    await fetchData();
  };

  const handleUpdateOrderStatus = async (orderId: string, status: Order['status']) => {
    const { error } = await supabase.from('orders').update({ status }).eq('id', orderId);
    if (error) return;
    await fetchData();
  };

  const dynamicCategories = useMemo(() => {
    return ['All', ...categories.map(c => c.name)];
  }, [categories]);

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const isVisible = currentView === 'admin' || p.isPublic;
      const matchesCategory = selectedCategory === 'All' || p.category === selectedCategory;
      const matchesSearch = p.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                           p.description.toLowerCase().includes(searchQuery.toLowerCase());
      return isVisible && matchesCategory && matchesSearch;
    });
  }, [products, selectedCategory, searchQuery, currentView]);

  const resetToShop = () => {
    setCurrentView('shop');
    setSelectedProduct(null);
    setSelectedCategory('All');
    setSearchQuery('');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleAdminAccessTrigger = () => {
    if (isAdminAuthenticated) {
      setCurrentView('admin');
      return;
    }
    const now = Date.now();
    if (now - lastClickTime.current > 3000) clickCount.current = 1;
    else clickCount.current += 1;
    lastClickTime.current = now;

    if (clickCount.current >= 5) {
      clickCount.current = 0;
      setShowAdminPassModal(true);
      setAdminInputPass('');
    }
  };

  const handleAdminLogout = () => {
    localStorage.removeItem(ADMIN_SESSION_KEY);
    setIsAdminAuthenticated(false);
    resetToShop();
  };

  const handleServicesNav = () => {
    if (currentView !== 'shop') {
      setCurrentView('shop');
      setTimeout(() => {
        shopSectionRef.current?.scrollIntoView({ behavior: 'smooth' });
      }, 100);
    } else {
      shopSectionRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  };

  if (loading) return (
    <div className="min-h-screen flex items-center justify-center bg-white">
      <div className="flex flex-col items-center gap-8">
        <div className="w-12 h-12 border-[6px] border-[#0F172A] border-t-transparent rounded-full animate-spin"></div>
        <p className="text-[#0F172A] font-black uppercase tracking-[0.3em] text-[10px] animate-pulse">Server Connection Established</p>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen flex flex-col bg-[#F8FAFC] relative">
      {(currentView === 'shop' || currentView === 'profile' || currentView === 'contact') && <ProductRain products={products.filter(p => p.isPublic)} />}

      <Navbar 
        currentView={currentView} 
        setView={(v) => { if(v === 'shop') resetToShop(); else setCurrentView(v); }} 
        cartCount={cart.reduce((s, i) => s + i.quantity, 0)}
        user={user}
        notifications={notifications}
        onLogout={async () => { await supabase.auth.signOut(); setUser(null); setCart([]); resetToShop(); }}
        onAuthClick={() => { setAuthMode('signin'); setIsAuthModalOpen(true); }}
        onMarkNotificationsRead={handleMarkNotifsRead}
        onServicesClick={handleServicesNav}
      />

      {currentView === 'shop' && <ProductTicker products={products.filter(p => p.isPublic)} onProductClick={(p) => { setSelectedProduct(p); setCurrentView('product-detail'); }} />}

      <main className="flex-1 max-w-7xl mx-auto w-full px-4 sm:px-6 lg:px-8 py-4 md:py-6 relative z-10">
        {currentView === 'shop' ? (
          <div className="space-y-4 md:space-y-6">
            <HeroBanner onShopClick={() => shopSectionRef.current?.scrollIntoView({ behavior: 'smooth' })} />

            <div ref={shopSectionRef} className="bg-white border border-slate-200 rounded-2xl md:rounded-[2rem] p-1 shadow-sm flex flex-col md:flex-row items-center gap-1 md:gap-4 sticky top-24 z-30">
                <div className="flex flex-wrap items-center gap-1 w-full md:flex-1 p-1">
                    {dynamicCategories.map(cat => (
                        <button 
                            key={cat} 
                            onClick={() => setSelectedCategory(cat)} 
                            className={`px-3 py-1.5 md:px-4 md:py-2 rounded-xl text-[8px] md:text-[9px] font-black uppercase tracking-tight md:tracking-widest transition-all whitespace-nowrap
                                ${selectedCategory === cat ? 'bg-[#0F172A] text-white shadow-md' : 'text-slate-400 hover:bg-slate-50'}`}
                        >
                            {cat}
                        </button>
                    ))}
                </div>
                <div className="w-full md:w-auto p-1 md:pr-2">
                    <input 
                      type="text" 
                      placeholder="Search..." 
                      className="w-full md:w-40 px-4 py-1.5 md:py-2 bg-slate-50 border border-slate-100 rounded-xl outline-none text-[10px] md:text-xs font-bold focus:bg-white focus:border-blue-600 transition-all" 
                      value={searchQuery} 
                      onChange={e => setSearchQuery(e.target.value)} 
                    />
                </div>
            </div>

            <div className="pb-24">
                <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4 md:gap-8 px-1 md:px-2 animate-in fade-in duration-1000">
                  {filteredProducts.map(product => (
                    <ProductCard key={product.id} product={product} onAddToCart={(p) => {
                       if (!user) { setAuthMode('signin'); setIsAuthModalOpen(true); return; }
                       setCart(prev => {
                         const existing = prev.find(item => item.id === p.id);
                         if (existing) return prev.map(item => item.id === p.id ? { ...item, quantity: item.quantity + 1 } : item);
                         return [...prev, { ...p, quantity: 1 }];
                       });
                       setIsCartOpen(true);
                    }} onViewDetails={(p) => { setSelectedProduct(p); setCurrentView('product-detail'); }} />
                  ))}
                </div>
            </div>
          </div>
        ) : currentView === 'product-detail' && selectedProduct ? (
          <ProductDetail product={selectedProduct} onAddToCart={(p, q) => {
            if (!user) { setAuthMode('signin'); setIsAuthModalOpen(true); return; }
            setCart(prev => {
              const existing = prev.find(item => item.id === p.id);
              if (existing) return prev.map(item => item.id === p.id ? { ...item, quantity: item.quantity + q } : item);
              return [...prev, { ...p, quantity: q }];
            });
            setIsCartOpen(true);
          }} onBack={resetToShop} />
        ) : currentView === 'checkout' ? (
          <CheckoutView items={cart} onBack={resetToShop} onSuccess={async (order) => {
            const { error, data } = await supabase.from('orders').insert([{
              user_id: user?.id,
              items: order.items,
              total: order.total,
              status: 'pending',
              full_name: order.fullName,
              whatsapp_number: order.whatsappNumber,
              delivery_email: order.deliveryEmail,
              payment_method: order.paymentMethod,
              transaction_id: order.transactionId,
              screenshot_url: order.screenshotUrl
            }]).select();
            if (!error) {
              const newNotif: Notification = {
                id: Date.now().toString(),
                message: `✅ Order Placed! ID: #${data[0].id.slice(0,8)}. Admin will verify soon.`,
                type: 'system',
                createdAt: new Date().toISOString(),
                isRead: false
              };
              setNotifications(prev => [newNotif, ...prev]);
              setCart([]);
              resetToShop();
              fetchData();
            }
          }} />
        ) : currentView === 'profile' && user ? (
          <ProfileView user={user} orders={orders} onBack={resetToShop} onUpdatePassword={() => { setAuthMode('update'); setIsAuthModalOpen(true); }} />
        ) : currentView === 'admin' && isAdminAuthenticated ? (
          <AdminPanel 
            products={products} 
            orders={orders} 
            categories={categories}
            onAddProduct={handleAddProduct} 
            onUpdateProduct={handleUpdateProduct} 
            onDeleteProduct={handleDeleteProduct} 
            onUpdateOrderStatus={handleUpdateOrderStatus}
            onAddCategory={handleAddCategory}
            onUpdateCategory={handleUpdateCategory}
            onDeleteCategory={handleDeleteCategory}
            onBack={handleAdminLogout} 
          />
        ) : currentView === 'contact' ? (
          <ContactView onBack={resetToShop} />
        ) : (
          <div className="text-center py-20"><button onClick={resetToShop} className="px-12 py-5 bg-[#0F172A] text-white rounded-[2rem] font-black uppercase tracking-widest shadow-2xl">Return to Catalog</button></div>
        )}
      </main>

      {/* Admin Pass Modal */}
      {showAdminPassModal && (
        <div className="fixed inset-0 z-[300] flex items-center justify-center p-4 bg-[#0F172A]/80 backdrop-blur-3xl transition-all duration-700 animate-in fade-in">
          <div className="relative bg-white rounded-[4rem] p-12 shadow-[0_50px_100px_rgba(0,0,0,0.4)] animate-in zoom-in-95 duration-500 w-full max-w-[440px] flex flex-col items-center">
            <div className="relative mb-10 group">
              <div className="absolute inset-[-15px] rounded-full border-2 border-dashed border-blue-500/30 animate-[spin_10s_linear_infinite]"></div>
              <div className="absolute inset-[-10px] rounded-full bg-gradient-to-tr from-blue-600 via-cyan-400 to-blue-600 opacity-20 blur-xl group-hover:opacity-40 transition-opacity duration-700"></div>
              <div className="relative w-40 h-40 rounded-full border-[8px] border-white overflow-hidden shadow-2xl z-10 transition-transform duration-700 group-hover:scale-105">
                <img src={ownerPhotoUrl} alt="Mehedi Hasan" className="w-full h-full object-cover" />
              </div>
              <div className="absolute bottom-2 right-2 z-20 w-10 h-10 bg-white rounded-full flex items-center justify-center shadow-lg border-2 border-slate-50 scale-100 group-hover:scale-110 transition-transform duration-500">
                <svg className="w-6 h-6 text-blue-600 fill-current" viewBox="0 0 24 24"><path d="M9 16.17L4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41z" /></svg>
              </div>
            </div>
            <div className="text-center mb-10">
                <h3 className="text-3xl font-black text-[#0F172A] uppercase tracking-tighter">Mehedi Hasan</h3>
                <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.5em] whitespace-nowrap">Security Terminal</h2>
            </div>
            <form className="w-full space-y-8" onSubmit={(e) => { 
                e.preventDefault(); 
                if(adminInputPass === ADMIN_PASSWORD) { 
                  localStorage.setItem(ADMIN_SESSION_KEY, JSON.stringify({ auth: true, timestamp: Date.now() }));
                  setIsAdminAuthenticated(true); setCurrentView('admin'); setShowAdminPassModal(false); 
                } else { alert("❌ Invalid Identity Key"); }
              }}>
              <input type="password" placeholder="••••••••" className="w-full px-8 py-6 bg-slate-50 border-2 border-slate-100 rounded-[2.5rem] text-center font-black tracking-[0.8em] transition-all text-2xl focus:border-blue-500 focus:bg-white outline-none shadow-inner" value={adminInputPass} onChange={e => setAdminInputPass(e.target.value)} />
              <button type="submit" className="w-full py-6 bg-[#0F172A] text-white rounded-[2.5rem] font-black uppercase text-xs tracking-[0.3em] hover:bg-blue-600 shadow-2xl transition-all">Authorize Access</button>
            </form>
            <button onClick={() => setShowAdminPassModal(false)} className="mt-10 text-[9px] font-black text-slate-300 uppercase tracking-widest hover:text-red-500 transition-colors">Cancel Authentication</button>
          </div>
        </div>
      )}

      {currentView !== 'admin' && (
        <footer className="bg-white border-t border-slate-100 py-16 mt-20 relative z-10">
          <div className="max-w-7xl mx-auto px-8 flex flex-col md:flex-row items-center justify-between gap-10">
            <div className="flex items-center gap-4">
              <div className="relative flex items-center justify-center w-12 h-12 flex-shrink-0 group">
                <div className="absolute inset-0 border border-cyan-400/40 rounded-full group-hover:border-cyan-400 transition-colors"></div>
                <div className="flex items-baseline relative z-10 font-black text-sm"><span className="text-blue-600">D</span><span className="text-green-500 -ml-0.5">S</span></div>
              </div>
              <div className="flex flex-col items-start">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-0.5">Platform Owner</p>
                <p className="text-xs font-black text-slate-900 uppercase tracking-widest cursor-pointer hover:text-blue-600 transition-colors" onClick={handleAdminAccessTrigger}>Mehedi Hasan • DS STORE GLOBAL</p>
              </div>
            </div>
            <p className="text-[9px] font-black text-slate-300 uppercase tracking-[0.3em]">© 2005-2025 DS SERVICE STORE</p>
          </div>
        </footer>
      )}

      <CartDrawer isOpen={isCartOpen} onClose={() => setIsCartOpen(false)} items={cart} onRemove={(id) => setCart(cart.filter(i => i.id !== id))} onUpdateQuantity={(id, q) => setCart(cart.map(i => i.id === id ? {...i, quantity: q} : i))} onCheckout={() => { setIsCartOpen(false); setCurrentView('checkout'); }} />
      <AuthModal isOpen={isAuthModalOpen} initialMode={authMode} onClose={() => setIsAuthModalOpen(false)} onLogin={(u) => setUser(u)} />
    </div>
  );
};

export default App;

export interface Product {
  id: string;
  name: string;
  description: string;
  price: number;
  category: string;
  image: string;
  stock: number;
  rating: number;
  isPublic: boolean;
}

export interface Category {
  id: string;
  name: string;
  order_index: number;
  created_at?: string;
}

export interface CartItem extends Product {
  quantity: number;
}

export interface User {
  id: string;
  name: string;
  email: string;
  isAdmin: boolean;
}

export interface Order {
  id: string;
  userId: string;
  items: CartItem[];
  total: number;
  status: 'pending' | 'confirmed' | 'delivered' | 'cancelled';
  createdAt: string;
  fullName: string;
  whatsappNumber: string;
  deliveryEmail: string;
  paymentMethod: string;
  transactionId: string;
  screenshotUrl?: string;
}

export interface Notification {
  id: string;
  message: string;
  type: 'order_status' | 'system';
  createdAt: string;
  isRead: boolean;
  orderId?: string;
}

export type View = 'shop' | 'product-detail' | 'checkout' | 'cart' | 'admin' | 'profile' | 'contact';

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Navbar } from './components/Navbar';
import { ProductCard } from './components/ProductCard';
import { CartDrawer } from './components/CartDrawer';
import { ProductDetail } from './components/ProductDetail';
import { ProductTicker } from './components/ProductTicker';
import { CheckoutView } from './components/CheckoutView';
import { AuthModal } from './components/AuthModal';
import { AdminPanel } from './components/AdminPanel';
import { ProductRain } from './components/ProductRain';
import { ProfileView } from './components/ProfileView';
import { HeroBanner } from './components/HeroBanner';
import { ContactView } from './components/ContactView';
import { Product, CartItem, User, View, Order, Category, Notification } from './types';
import { INITIAL_PRODUCTS } from './constants';
import { supabase } from './supabaseClient';

const App: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [currentView, setCurrentView] = useState<View>('shop');
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [searchQuery, setSearchQuery] = useState('');
  const [user, setUser] = useState<User | null>(null);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
  const [authMode, setAuthMode] = useState<'signin' | 'signup' | 'forgot' | 'update'>('signin');
  const [loading, setLoading] = useState(true);

  const [isAdminAuthenticated, setIsAdminAuthenticated] = useState(false);
  const [showAdminPassModal, setShowAdminPassModal] = useState(false);
  const [adminInputPass, setAdminInputPass] = useState('');

  const shopSectionRef = useRef<HTMLDivElement>(null);
  const clickCount = useRef(0);
  const lastClickTime = useRef(0);
  const ADMIN_PASSWORD = "Ajmir@#123";
  const ADMIN_SESSION_KEY = "ds_admin_session_v1";
  const TWENTY_FOUR_HOURS = 24 * 60 * 60 * 1000;

  const ownerPhotoUrl = "https://media.licdn.com/dms/image/v2/D5603AQF6FS5z4Ky4RQ/profile-displayphoto-shrink_200_200/B56Zu4YNm2G0AY-/0/1768324915128?e=2147483647&v=beta&t=_coKuJKl31AvjMDdGeLrigjfgyD8rtgblh-J_kP8Ruo"; 

  const fetchData = async () => {
    try {
      // Fetch Categories - Sorted by order_index
      const { data: dbCats, error: catError } = await supabase
        .from('categories')
        .select('*')
        .order('order_index', { ascending: true });

      if (!catError && dbCats) {
        setCategories(dbCats);
      }

      // Fetch Products
      const { data: dbProducts, error: prodError } = await supabase
        .from('products')
        .select('*')
        .order('name', { ascending: true });

      if (!prodError && dbProducts) {
        const mappedProducts = (dbProducts as any[]).map((p: any) => ({
          ...p,
          isPublic: p.is_public !== undefined ? p.is_public : true
        }));
        setProducts(mappedProducts.length > 0 ? mappedProducts : INITIAL_PRODUCTS);
      }

      // Fetch Orders
      const { data: dbOrders, error: orderError } = await supabase
        .from('orders')
        .select('*')
        .order('created_at', { ascending: false });

      if (!orderError && dbOrders) {
        const mappedOrders = (dbOrders as any[]).map((o: any) => ({
          id: o.id,
          userId: o.user_id,
          items: o.items,
          total: o.total,
          status: o.status,
          createdAt: o.created_at,
          fullName: o.full_name,
          whatsappNumber: o.whatsapp_number,
          deliveryEmail: o.delivery_email || o.deliveryEmail || '',
          paymentMethod: o.payment_method,
          transactionId: o.transaction_id,
          screenshotUrl: o.screenshot_url
        }));
        setOrders(mappedOrders as Order[]);
      }
    } catch (err) {
      console.error("General Fetch Error:", err);
    }
  };

  useEffect(() => {
    if (!user) {
      setNotifications([]);
      return;
    }

    const stored = localStorage.getItem(`notifs_${user.id}`);
    if (stored) setNotifications(JSON.parse(stored));

    const channel = supabase
      .channel('order_updates')
      .on(
        'postgres_changes',
        { event: 'UPDATE', schema: 'public', table: 'orders', filter: `user_id=eq.${user.id}` },
        (payload) => {
          const newStatus = payload.new.status;
          const oldStatus = payload.old.status;

          if (newStatus !== oldStatus) {
            const newNotif: Notification = {
              id: Date.now().toString(),
              message: `Your Order ID: #${payload.new.id.slice(0,8)} is now ${newStatus.toUpperCase()}`,
              type: 'order_status',
              createdAt: new Date().toISOString(),
              isRead: false,
              orderId: payload.new.id
            };
            setNotifications(prev => {
              const updated = [newNotif, ...prev];
              localStorage.setItem(`notifs_${user.id}`, JSON.stringify(updated.slice(0, 20)));
              return updated;
            });
            alert(`🔔 Order Update: Your order is now ${newStatus}!`);
          }
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [user]);

  useEffect(() => {
    const initialize = async () => {
      try {
        const storedSession = localStorage.getItem(ADMIN_SESSION_KEY);
        if (storedSession) {
          const sessionData = JSON.parse(storedSession);
          const now = Date.now();
          if (now - sessionData.timestamp < TWENTY_FOUR_HOURS) {
            setIsAdminAuthenticated(true);
          } else {
            localStorage.removeItem(ADMIN_SESSION_KEY);
          }
        }

        const { data: { session } } = await supabase.auth.getSession();
        if (session?.user) {
          setUser({
            id: session.user.id,
            name: session.user.user_metadata.full_name || session.user.email?.split('@')[0] || 'User',
            email: session.user.email || '',
            isAdmin: false
          });
        }
        await fetchData();
      } catch (e) {
        console.error("Initialization error", e);
      } finally {
        setLoading(false);
      }
    };

    initialize();
  }, []);

  const handleMarkNotifsRead = () => {
    if (!user) return;
    setNotifications(prev => {
      const updated = prev.map(n => ({ ...n, isRead: true }));
      localStorage.setItem(`notifs_${user.id}`, JSON.stringify(updated));
      return updated;
    });
  };

  const handleAddCategory = async (name: string) => {
    const maxIndex = categories.reduce((max, c) => Math.max(max, c.order_index), 0);
    const { error } = await supabase.from('categories').insert([{ name, order_index: maxIndex + 1 }]);
    if (error) throw error;
    await fetchData();
  };

  const handleUpdateCategory = async (id: string, name: string) => {
    const { error } = await supabase.from('categories').update({ name }).eq('id', id);
    if (error) throw error;
    await fetchData();
  };

  const handleDeleteCategory = async (id: string) => {
    const { error } = await supabase.from('categories').delete().eq('id', id);
    if (error) throw error;
    await fetchData();
  };

  const handleAddProduct = async (p: Omit<Product, 'id'>) => {
    const { error } = await supabase.from('products').insert([{
      name: p.name,
      description: p.description,
      price: p.price,
      category: p.category,
      image: p.image,
      stock: p.stock,
      rating: p.rating,
      is_public: p.isPublic
    }]);
    if (error) return;
    await fetchData();
  };

  const handleUpdateProduct = async (id: string, p: Partial<Product>) => {
    const updateData: any = { ...p };
    if (p.isPublic !== undefined) {
      updateData.is_public = p.isPublic;
      delete updateData.isPublic;
    }
    const { error } = await supabase.from('products').update(updateData).eq('id', id);
    if (error) return;
    await fetchData();
  };

  const handleDeleteProduct = async (id: string) => {
    const { error } = await supabase.from('products').delete().eq('id', id);
    if (error) return;
    await fetchData();
  };

  const handleUpdateOrderStatus = async (orderId: string, status: Order['status']) => {
    const { error } = await supabase.from('orders').update({ status }).eq('id', orderId);
    if (error) return;
    await fetchData();
  };

  const dynamicCategories = useMemo(() => {
    return ['All', ...categories.map(c => c.name)];
  }, [categories]);

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const isVisible = currentView === 'admin' || p.isPublic;
      const matchesCategory = selectedCategory === 'All' || p.category === selectedCategory;
      const matchesSearch = p.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                           p.description.toLowerCase().includes(searchQuery.toLowerCase());
      return isVisible && matchesCategory && matchesSearch;
    });
  }, [products, selectedCategory, searchQuery, currentView]);

  const resetToShop = () => {
    setCurrentView('shop');
    setSelectedProduct(null);
    setSelectedCategory('All');
    setSearchQuery('');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleAdminAccessTrigger = () => {
    if (isAdminAuthenticated) {
      setCurrentView('admin');
      return;
    }
    const now = Date.now();
    if (now - lastClickTime.current > 3000) clickCount.current = 1;
    else clickCount.current += 1;
    lastClickTime.current = now;

    if (clickCount.current >= 5) {
      clickCount.current = 0;
      setShowAdminPassModal(true);
      setAdminInputPass('');
    }
  };

  const handleAdminLogout = () => {
    localStorage.removeItem(ADMIN_SESSION_KEY);
    setIsAdminAuthenticated(false);
    resetToShop();
  };

  const handleServicesNav = () => {
    if (currentView !== 'shop') {
      setCurrentView('shop');
      setTimeout(() => {
        shopSectionRef.current?.scrollIntoView({ behavior: 'smooth' });
      }, 100);
    } else {
      shopSectionRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  };

  if (loading) return (
    <div className="min-h-screen flex items-center justify-center bg-white">
      <div className="flex flex-col items-center gap-8">
        <div className="w-12 h-12 border-[6px] border-[#0F172A] border-t-transparent rounded-full animate-spin"></div>
        <p className="text-[#0F172A] font-black uppercase tracking-[0.3em] text-[10px] animate-pulse">Server Connection Established</p>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen flex flex-col bg-[#F8FAFC] relative">
      {(currentView === 'shop' || currentView === 'profile' || currentView === 'contact') && <ProductRain products={products.filter(p => p.isPublic)} />}

      <Navbar 
        currentView={currentView} 
        setView={(v) => { if(v === 'shop') resetToShop(); else setCurrentView(v); }} 
        cartCount={cart.reduce((s, i) => s + i.quantity, 0)}
        user={user}
        notifications={notifications}
        onLogout={async () => { await supabase.auth.signOut(); setUser(null); setCart([]); resetToShop(); }}
        onAuthClick={() => { setAuthMode('signin'); setIsAuthModalOpen(true); }}
        onMarkNotificationsRead={handleMarkNotifsRead}
        onServicesClick={handleServicesNav}
      />

      {currentView === 'shop' && <ProductTicker products={products.filter(p => p.isPublic)} onProductClick={(p) => { setSelectedProduct(p); setCurrentView('product-detail'); }} />}

      <main className="flex-1 max-w-7xl mx-auto w-full px-4 sm:px-6 lg:px-8 py-4 md:py-6 relative z-10">
        {currentView === 'shop' ? (
          <div className="space-y-4 md:space-y-6">
            <HeroBanner onShopClick={() => shopSectionRef.current?.scrollIntoView({ behavior: 'smooth' })} />

            <div ref={shopSectionRef} className="bg-white border border-slate-200 rounded-2xl md:rounded-[2rem] p-1 shadow-sm flex flex-col md:flex-row items-center gap-1 md:gap-4 sticky top-24 z-30">
                <div className="flex flex-wrap items-center gap-1 w-full md:flex-1 p-1">
                    {dynamicCategories.map(cat => (
                        <button 
                            key={cat} 
                            onClick={() => setSelectedCategory(cat)} 
                            className={`px-3 py-1.5 md:px-4 md:py-2 rounded-xl text-[8px] md:text-[9px] font-black uppercase tracking-tight md:tracking-widest transition-all whitespace-nowrap
                                ${selectedCategory === cat ? 'bg-[#0F172A] text-white shadow-md' : 'text-slate-400 hover:bg-slate-50'}`}
                        >
                            {cat}
                        </button>
                    ))}
                </div>
                <div className="w-full md:w-auto p-1 md:pr-2">
                    <input 
                      type="text" 
                      placeholder="Search..." 
                      className="w-full md:w-40 px-4 py-1.5 md:py-2 bg-slate-50 border border-slate-100 rounded-xl outline-none text-[10px] md:text-xs font-bold focus:bg-white focus:border-blue-600 transition-all" 
                      value={searchQuery} 
                      onChange={e => setSearchQuery(e.target.value)} 
                    />
                </div>
            </div>

            <div className="pb-24">
                <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4 md:gap-8 px-1 md:px-2 animate-in fade-in duration-1000">
                  {filteredProducts.map(product => (
                    <ProductCard key={product.id} product={product} onAddToCart={(p) => {
                       if (!user) { setAuthMode('signin'); setIsAuthModalOpen(true); return; }
                       setCart(prev => {
                         const existing = prev.find(item => item.id === p.id);
                         if (existing) return prev.map(item => item.id === p.id ? { ...item, quantity: item.quantity + 1 } : item);
                         return [...prev, { ...p, quantity: 1 }];
                       });
                       setIsCartOpen(true);
                    }} onViewDetails={(p) => { setSelectedProduct(p); setCurrentView('product-detail'); }} />
                  ))}
                </div>
            </div>
          </div>
        ) : currentView === 'product-detail' && selectedProduct ? (
          <ProductDetail product={selectedProduct} onAddToCart={(p, q) => {
            if (!user) { setAuthMode('signin'); setIsAuthModalOpen(true); return; }
            setCart(prev => {
              const existing = prev.find(item => item.id === p.id);
              if (existing) return prev.map(item => item.id === p.id ? { ...item, quantity: item.quantity + q } : item);
              return [...prev, { ...p, quantity: q }];
            });
            setIsCartOpen(true);
          }} onBack={resetToShop} />
        ) : currentView === 'checkout' ? (
          <CheckoutView items={cart} onBack={resetToShop} onSuccess={async (order) => {
            const { error, data } = await supabase.from('orders').insert([{
              user_id: user?.id,
              items: order.items,
              total: order.total,
              status: 'pending',
              full_name: order.fullName,
              whatsapp_number: order.whatsappNumber,
              delivery_email: order.deliveryEmail,
              payment_method: order.paymentMethod,
              transaction_id: order.transactionId,
              screenshot_url: order.screenshotUrl
            }]).select();
            if (!error) {
              const newNotif: Notification = {
                id: Date.now().toString(),
                message: `✅ Order Placed! ID: #${data[0].id.slice(0,8)}. Admin will verify soon.`,
                type: 'system',
                createdAt: new Date().toISOString(),
                isRead: false
              };
              setNotifications(prev => [newNotif, ...prev]);
              setCart([]);
              resetToShop();
              fetchData();
            }
          }} />
        ) : currentView === 'profile' && user ? (
          <ProfileView user={user} orders={orders} onBack={resetToShop} onUpdatePassword={() => { setAuthMode('update'); setIsAuthModalOpen(true); }} />
        ) : currentView === 'admin' && isAdminAuthenticated ? (
          <AdminPanel 
            products={products} 
            orders={orders} 
            categories={categories}
            onAddProduct={handleAddProduct} 
            onUpdateProduct={handleUpdateProduct} 
            onDeleteProduct={handleDeleteProduct} 
            onUpdateOrderStatus={handleUpdateOrderStatus}
            onAddCategory={handleAddCategory}
            onUpdateCategory={handleUpdateCategory}
            onDeleteCategory={handleDeleteCategory}
            onBack={handleAdminLogout} 
          />
        ) : currentView === 'contact' ? (
          <ContactView onBack={resetToShop} />
        ) : (
          <div className="text-center py-20"><button onClick={resetToShop} className="px-12 py-5 bg-[#0F172A] text-white rounded-[2rem] font-black uppercase tracking-widest shadow-2xl">Return to Catalog</button></div>
        )}
      </main>

      {showAdminPassModal && (
        <div className="fixed inset-0 z-[300] flex items-center justify-center p-4 bg-[#0F172A]/80 backdrop-blur-3xl transition-all duration-700 animate-in fade-in">
          <div className="relative bg-white rounded-[4rem] p-12 shadow-[0_50px_100px_rgba(0,0,0,0.4)] animate-in zoom-in-95 duration-500 w-full max-w-[440px] flex flex-col items-center">
            <div className="relative mb-10 group">
              <div className="absolute inset-[-15px] rounded-full border-2 border-dashed border-blue-500/30 animate-[spin_10s_linear_infinite]"></div>
              <div className="absolute inset-[-10px] rounded-full bg-gradient-to-tr from-blue-600 via-cyan-400 to-blue-600 opacity-20 blur-xl group-hover:opacity-40 transition-opacity duration-700"></div>
              <div className="relative w-40 h-40 rounded-full border-[8px] border-white overflow-hidden shadow-2xl z-10 transition-transform duration-700 group-hover:scale-105">
                <img src={ownerPhotoUrl} alt="Mehedi Hasan" className="w-full h-full object-cover" />
              </div>
              <div className="absolute bottom-2 right-2 z-20 w-10 h-10 bg-white rounded-full flex items-center justify-center shadow-lg border-2 border-slate-50 scale-100 group-hover:scale-110 transition-transform duration-500">
                <svg className="w-6 h-6 text-blue-600 fill-current" viewBox="0 0 24 24"><path d="M9 16.17L4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41z" /></svg>
              </div>
            </div>
            <div className="text-center mb-10">
                <h3 className="text-3xl font-black text-[#0F172A] uppercase tracking-tighter">Mehedi Hasan</h3>
                <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.5em] whitespace-nowrap">Security Terminal</h2>
            </div>
            <form className="w-full space-y-8" onSubmit={(e) => { 
                e.preventDefault(); 
                if(adminInputPass === ADMIN_PASSWORD) { 
                  localStorage.setItem(ADMIN_SESSION_KEY, JSON.stringify({ auth: true, timestamp: Date.now() }));
                  setIsAdminAuthenticated(true); setCurrentView('admin'); setShowAdminPassModal(false); 
                } else { alert("❌ Invalid Identity Key"); }
              }}>
              <input type="password" placeholder="••••••••" className="w-full px-8 py-6 bg-slate-50 border-2 border-slate-100 rounded-[2.5rem] text-center font-black tracking-[0.8em] transition-all text-2xl focus:border-blue-500 focus:bg-white outline-none shadow-inner" value={adminInputPass} onChange={e => setAdminInputPass(e.target.value)} />
