          <div className="bg-slate-900 p-8 rounded-[3rem] text-white shadow-2xl flex flex-col justify-center items-center text-center">
             <div className="w-20 h-20 bg-blue-600 rounded-3xl flex items-center justify-center mb-6 shadow-xl">
                <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" /></svg>
             </div>
             <h3 className="text-2xl font-black uppercase tracking-tighter">Business Growth</h3>
             <p className="text-slate-400 text-sm font-bold mt-2">Manage your services effectively to scale your digital store.</p>
          </div>
        </div>
