                      </div>
                      <div>
                        <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-2">Stock Units</label>
                        <input required type="number" className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold outline-none focus:ring-2 focus:ring-blue-600" value={formData.stock} onChange={e => setFormData({...formData, stock: parseInt(e.target.value)})} />
                      </div>
                    </div>
