                      <select className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold outline-none focus:ring-2 focus:ring-blue-600" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                        {categories.map(cat => <option key={cat.id} value={cat.name}>{cat.name}</option>)}
                      </select>
                    </div>
                    <div>
                      <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-2">Service Image</label>
                      <div className="flex gap-4 items-center">
                        <div className="w-24 h-24 bg-slate-100 rounded-3xl border border-slate-200 overflow-hidden flex-shrink-0">
                          {formData.image ? <img src={formData.image} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center text-slate-300"><svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg></div>}
                        </div>
                        <div className="flex-1">
                          <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileUpload} />
                          <button type="button" onClick={() => fileInputRef.current?.click()} className="w-full py-4 bg-slate-100 text-slate-600 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-slate-200 transition-all mb-2">{uploading ? 'Uploading...' : 'Change Image'}</button>
                          <p className="text-[9px] font-bold text-slate-400 uppercase tracking-tighter text-center">Standard Size: 800x600px</p>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
                <div className="flex gap-4 pt-8">
                  <button type="submit" disabled={saving || uploading} className="flex-1 py-5 bg-blue-600 text-white rounded-2xl font-black uppercase text-xs tracking-widest shadow-xl hover:bg-slate-900 transition-all disabled:opacity-50">{saving ? 'Saving...' : (editingId ? 'Update Service' : 'Post Service')}</button>
                  <button type="button" onClick={resetForm} className="px-10 py-5 bg-slate-100 text-slate-500 rounded-2xl font-black uppercase text-xs tracking-widest hover:bg-red-50 transition-all">Cancel</button>
                </div>
              </form>
            </div>
          )}

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
             {products.map(p => (
               <div key={p.id} className="bg-white p-6 rounded-[2.5rem] border border-slate-200 shadow-sm group hover:shadow-xl transition-all flex gap-4">
                  <img src={p.image} className="w-20 h-20 rounded-2xl object-cover border border-slate-50 shadow-sm" />
                  <div className="flex-1">
                     <h4 className="font-black text-slate-900 uppercase tracking-tight text-xs mb-1 line-clamp-1">{p.name}</h4>
                     <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest mb-3">${p.price.toFixed(2)} • {p.stock} Units</p>
                     <div className="flex gap-2">
                        <button onClick={() => handleEditClick(p)} className="p-2 bg-blue-50 text-blue-600 rounded-lg hover:bg-blue-600 hover:text-white transition-all"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M11 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-5M18.364 5.364a2.121 2.121 0 013 3L12 18l-4 1 1-4L18.364 5.364z" /></svg></button>
                        <button onClick={() => { if(confirm('Delete product?')) onDeleteProduct(p.id); }} className="p-2 bg-red-50 text-red-600 rounded-lg hover:bg-red-600 hover:text-white transition-all"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg></button>
                     </div>
                  </div>
               </div>
             ))}
          </div>
        </div>
      )}

      {activeTab === 'orders' && (
        <div className="animate-in slide-in-from-bottom-4 space-y-8">
           <div className="bg-white p-6 rounded-[2.5rem] border border-slate-200 shadow-sm">
             <h2 className="text-xl font-black text-slate-900 uppercase tracking-tighter ml-4">Order Fulfilment Panel</h2>
           </div>
           <div className="bg-white rounded-[3rem] border border-slate-200 overflow-hidden shadow-xl">
             <table className="w-full text-left">
               <thead className="bg-slate-50/50 border-b border-slate-100">
                 <tr>
                   <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">Order Info</th>
                   <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Customer</th>
                   <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Amount</th>
