                       <p className="text-[10px] font-black text-slate-400 uppercase">Tab Control</p>
                       <div className="flex gap-2">
                          <button onClick={() => { setEditingCategoryId(cat.id); setCategoryName(cat.name); setIsCategoryFormOpen(true); }} className="text-slate-300 hover:text-blue-600 transition-colors"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M11 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-5M18.364 5.364a2.121 2.121 0 013 3L12 18l-4 1 1-4L18.364 5.364z" /></svg></button>
                          <button onClick={() => { if(confirm(`Delete "${cat.name}" tab?`)) onDeleteCategory(cat.id); }} className="text-slate-300 hover:text-red-500 transition-colors"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6" /></svg></button>
                       </div>
                    </div>
                 </div>
              ))}
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Product, Order, CartItem, Category } from '../types';
import { supabase } from '../supabaseClient';
import { CATEGORIES as DEFAULT_CATEGORIES } from '../constants';

interface AdminPanelProps {
  products: Product[];
  orders: Order[];
  categories: Category[];
  onAddProduct: (p: Omit<Product, 'id'>) => void;
  onUpdateProduct: (id: string, p: Partial<Product>) => void;
  onDeleteProduct: (id: string) => void;
  onUpdateOrderStatus: (orderId: string, status: Order['status']) => void;
  onAddCategory: (name: string) => void;
  onUpdateCategory: (id: string, name: string) => void;
  onDeleteCategory: (id: string) => void;
  onBack: () => void;
}

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  products, 
  orders, 
  categories,
  onAddProduct, 
  onUpdateProduct,
  onDeleteProduct, 
  onUpdateOrderStatus,
  onAddCategory,
  onUpdateCategory,
  onDeleteCategory,
  onBack 
}) => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'inventory' | 'orders' | 'tabs'>('dashboard');
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [uploading, setUploading] = useState(false);
  const [saving, setSaving] = useState(false);

  // Category Form State
  const [isCategoryFormOpen, setIsCategoryFormOpen] = useState(false);
  const [editingCategoryId, setEditingCategoryId] = useState<string | null>(null);
  const [categoryName, setCategoryName] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);

  const ownerPhotoUrl = "https://media.licdn.com/dms/image/v2/D5603AQF6FS5z4Ky4RQ/profile-displayphoto-shrink_200_200/B56Zu4YNm2G0AY-/0/1768324915128?e=2147483647&v=beta&t=_coKuJKl31AvjMDdGeLrigjfgyD8rtgblh-J_kP8Ruo";

  const [formData, setFormData] = useState({
    name: '',
    description: '',
    price: 0,
    category: '',
    image: '',
    stock: 10,
    rating: 5,
    isPublic: true
  });

  // Sync default category when categories list changes
  useEffect(() => {
    if (!formData.category && categories.length > 0) {
      setFormData(prev => ({ ...prev, category: categories[0].name }));
    } else if (!formData.category && categories.length === 0) {
      setFormData(prev => ({ ...prev, category: DEFAULT_CATEGORIES[1] })); // Fallback to first non-"All" default
    }
  }, [categories, isFormOpen]);

  const totalSales = orders.reduce((sum, o) => (o.status === 'confirmed' || o.status === 'delivered') ? sum + o.total : sum, 0);
  const pendingCount = orders.filter(o => o.status === 'pending').length;

  const handleImportDefaultTabs = async () => {
    if (!confirm("Are you sure you want to import default tabs?")) return;
    setSaving(true);
    try {
      // Filter out 'All' from defaults as it's a UI-only filter
      const tabsToImport = DEFAULT_CATEGORIES.filter(c => c !== 'All');
      for (let i = 0; i < tabsToImport.length; i++) {
        await onAddCategory(tabsToImport[i]);
      }
      alert("✅ Default tabs imported successfully!");
    } catch (e) {
      alert("❌ Failed to import tabs");
    } finally {
      setSaving(false);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    try {
      setUploading(true);
      if (!e.target.files || e.target.files.length === 0) return;
      const file = e.target.files[0];
      const localUrl = URL.createObjectURL(file);
      setFormData(prev => ({ ...prev, image: localUrl }));
      const fileExt = file.name.split('.').pop();
      const fileName = `${Math.random()}.${fileExt}`;
      const filePath = `product-images/${fileName}`;
      const { error: uploadError } = await supabase.storage.from('products').upload(filePath, file);
      if (uploadError) throw uploadError;
      const { data } = supabase.storage.from('products').getPublicUrl(filePath);
      if (data) {
        setFormData(prev => ({ ...prev, image: data.publicUrl }));
        alert("✅ Image Uploaded!");
      }
    } catch (error: any) {
      alert("❌ Upload Failed: " + error.message);
    } finally {
      setUploading(false);
    }
  };

  const handleEditClick = (product: Product) => {
    setEditingId(product.id);
    setFormData({
      name: product.name,
      description: product.description,
      price: product.price,
      category: product.category,
      image: product.image,
      stock: product.stock,
      rating: product.rating,
      isPublic: product.isPublic !== undefined ? product.isPublic : true
    });
    setIsFormOpen(true);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (categories.length === 0 && !confirm("Warning: You have no active tabs. This product might not appear correctly in filters. Continue?")) return;

    setSaving(true);
    try {
      if (editingId) { await onUpdateProduct(editingId, formData); }
      else { await onAddProduct(formData); }
      resetForm();
    } catch (e) {
      alert("❌ Error saving product");
    } finally { setSaving(false); }
  };

  const handleCategorySubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!categoryName.trim()) return;
    setSaving(true);
    try {
      if (editingCategoryId) { await onUpdateCategory(editingCategoryId, categoryName); }
      else { await onAddCategory(categoryName); }
      setCategoryName('');
      setEditingCategoryId(null);
      setIsCategoryFormOpen(false);
    } catch (e) {
      alert("❌ Error managing tab");
    } finally {
      setSaving(false);
    }
  };

  const resetForm = () => {
    setIsFormOpen(false);
    setEditingId(null);
    setFormData({ 
      name: '', description: '', price: 0, 
      category: categories.length > 0 ? categories[0].name : DEFAULT_CATEGORIES[1], 
      image: '', stock: 10, rating: 5, isPublic: true 
    });
  };

  return (
    <div className="animate-in fade-in duration-1000 max-w-7xl mx-auto space-y-10 pb-20">
      {/* Admin Header */}
      <div className="relative overflow-hidden bg-slate-900 rounded-[3rem] p-8 shadow-2xl border border-white/10">
        <div className="absolute inset-0 bg-gradient-to-br from-blue-600/20 to-transparent"></div>
        <div className="relative z-10 flex flex-col md:flex-row justify-between items-center gap-8">
          <div className="flex items-center gap-6">
            <div className="relative w-24 h-24 rounded-full border-4 border-white overflow-hidden shadow-2xl">
              <img src={ownerPhotoUrl} alt="Mehedi Hasan" className="w-full h-full object-cover" />
            </div>
            <div>
              <h1 className="text-3xl font-black text-white uppercase tracking-tighter">Mehedi Hasan</h1>
              <p className="text-xs font-black text-cyan-400 uppercase tracking-[0.3em] mb-2">DS Store Panel v3.0</p>
              <div className="flex items-center gap-2">
                <span className="w-2 h-2 bg-green-400 rounded-full animate-pulse"></span>
                <span className="text-[10px] font-black text-white/50 uppercase tracking-widest tracking-widest">Administrator Connected</span>
              </div>
            </div>
          </div>
          <button onClick={onBack} className="px-8 py-4 bg-white/10 backdrop-blur-md text-white border border-white/20 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-white hover:text-slate-900 transition-all shadow-xl">Exit Admin Mode</button>
        </div>
      </div>

      {/* Quick Navigation Stats */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        {[
          { label: 'Total Revenue', value: `$${totalSales.toFixed(2)}`, icon: 'M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2', color: 'bg-blue-600' },
          { label: 'Pending Orders', value: pendingCount, icon: 'M12 8v4l3 3', color: 'bg-amber-500' },
          { label: 'Active Services', value: products.length, icon: 'M20 7l-8-4-8 4', color: 'bg-indigo-600' },
          { label: 'Tabs Configured', value: categories.length, icon: 'M7 7h.01M7 3h5', color: 'bg-green-600' }
        ].map((stat, i) => (
          <div key={i} className="bg-white p-6 rounded-[2.5rem] border border-slate-200 shadow-sm flex items-center justify-between">
            <div>
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{stat.label}</p>
              <p className="text-3xl font-black text-slate-900 tracking-tight">{stat.value}</p>
            </div>
            <div className={`w-14 h-14 ${stat.color} text-white rounded-[1.5rem] flex items-center justify-center`}><svg className="w-7 h-7" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d={stat.icon} /></svg></div>
          </div>
        ))}
      </div>

      {/* Tabs Menu */}
      <div className="bg-white p-2 rounded-full border border-slate-200 flex flex-wrap gap-1 w-full md:w-fit shadow-sm">
        {[
          { id: 'dashboard', label: 'Dashboard' },
          { id: 'inventory', label: 'Inventory' },
          { id: 'orders', label: 'Orders' },
          { id: 'tabs', label: 'Tab Manager' }
        ].map(tab => (
          <button 
            key={tab.id} 
            onClick={() => setActiveTab(tab.id as any)} 
            className={`px-8 py-3.5 rounded-full text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === tab.id ? 'bg-[#0F172A] text-white shadow-xl' : 'text-slate-500 hover:bg-slate-50'}`}
          >
            {tab.label}
          </button>
        ))}
      </div>

      {/* Content Areas */}
      {activeTab === 'dashboard' && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 animate-in slide-in-from-bottom-4">
          <div className="bg-white p-8 rounded-[3rem] border border-slate-200 shadow-sm">
            <h3 className="text-xl font-black text-slate-900 uppercase tracking-tight mb-6">Recent Sales Activity</h3>
            {orders.length > 0 ? (
              <div className="space-y-4">
                {orders.slice(0, 5).map(order => (
                  <div key={order.id} className="flex items-center justify-between p-5 bg-slate-50 rounded-2xl border border-slate-100">
                    <div>
                      <p className="text-xs font-black text-slate-900">Order #{order.id.slice(0, 8)}</p>
                      <p className="text-[10px] font-bold text-slate-400 uppercase">{order.fullName} • {order.paymentMethod}</p>
                    </div>
                    <div className="text-right">
                      <p className="text-sm font-black text-blue-600">${order.total.toFixed(2)}</p>
                      <p className={`text-[9px] font-black uppercase ${order.status === 'delivered' ? 'text-green-500' : 'text-amber-500'}`}>{order.status}</p>
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <div className="py-20 text-center flex flex-col items-center">
                <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center text-slate-300 mb-4">
                  <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                </div>
                <p className="text-xs font-black text-slate-400 uppercase tracking-widest">Awaiting First Order</p>
              </div>
            )}
          </div>
          <div className="bg-slate-900 p-8 rounded-[3rem] text-white shadow-2xl flex flex-col justify-center items-center text-center">
             <div className="w-20 h-20 bg-blue-600 rounded-3xl flex items-center justify-center mb-6 shadow-xl shadow-blue-500/20">
                <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" /></svg>
             </div>
             <h3 className="text-2xl font-black uppercase tracking-tighter">Business Overview</h3>
             <p className="text-slate-400 text-sm font-bold mt-2 max-w-xs">Your store has {products.length} live services and {orders.length} total orders recorded.</p>
          </div>
        </div>
      )}

      {activeTab === 'inventory' && (
        <div className="space-y-8 animate-in slide-in-from-bottom-4">
          <div className="flex flex-col sm:flex-row justify-between items-center bg-white p-6 rounded-[2.5rem] border border-slate-200 shadow-sm gap-4">
             <h2 className="text-xl font-black text-slate-900 uppercase tracking-tighter">Product Inventory ({products.length})</h2>
             <button onClick={() => { resetForm(); setIsFormOpen(true); }} className="w-full sm:w-auto px-8 py-4 bg-blue-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl hover:bg-[#0F172A] transition-all">+ Add New Service</button>
          </div>

          {isFormOpen && (
            <div className="bg-white rounded-[3rem] border border-slate-200 p-10 shadow-2xl animate-in zoom-in-95 duration-500">
              <form onSubmit={handleSubmit} className="space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="space-y-6">
                    <div>
                      <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-2">Service Name</label>
                      <input required type="text" className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold outline-none focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 transition-all" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
                    </div>
                    <div>
                      <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-2">Full Description</label>
                      <textarea required className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold outline-none focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 min-h-[120px] transition-all" value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} />
                    </div>
                  </div>
                  <div className="space-y-6">
                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-2">Price ($)</label>
                        <input required type="number" step="0.01" className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold outline-none focus:border-blue-500 transition-all" value={formData.price} onChange={e => setFormData({...formData, price: parseFloat(e.target.value)})} />
                      </div>
                      <div>
                        <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-2">Stock</label>
                        <input required type="number" className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold outline-none focus:border-blue-500 transition-all" value={formData.stock} onChange={e => setFormData({...formData, stock: parseInt(e.target.value)})} />
                      </div>
                    </div>
                    <div>
                      <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-2">Category (Tab)</label>
                      <select className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold outline-none focus:border-blue-500 transition-all appearance-none" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                        {categories.length === 0 && <option value="">No Tabs Found (Create one first)</option>}
                        {categories.map(cat => <option key={cat.id} value={cat.name}>{cat.name}</option>)}
                      </select>
                    </div>
                    <div>
                        <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-2">Cover Image</label>
                        <div className="flex gap-4 items-center">
                            <div className="w-20 h-20 bg-slate-100 rounded-2xl border border-slate-200 overflow-hidden flex-shrink-0">
                                {formData.image ? <img src={formData.image} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center text-slate-300"><svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg></div>}
                            </div>
                            <div className="flex-1">
                                <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileUpload} />
                                <button type="button" onClick={() => fileInputRef.current?.click()} className="w-full py-4 bg-slate-100 text-slate-600 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-slate-200 transition-all">{uploading ? 'Processing...' : 'Upload Image'}</button>
                            </div>
                        </div>
                    </div>
                  </div>
                </div>
                <div className="flex gap-4 pt-4">
                  <button type="submit" disabled={saving || uploading} className="flex-1 py-5 bg-blue-600 text-white rounded-2xl font-black uppercase text-xs tracking-widest shadow-xl hover:bg-[#0F172A] transition-all disabled:opacity-50">{saving ? 'Syncing...' : (editingId ? 'Update Service' : 'Publish Service')}</button>
                  <button type="button" onClick={resetForm} className="px-10 py-5 bg-slate-100 text-slate-500 rounded-2xl font-black uppercase text-xs tracking-widest hover:bg-red-50 transition-all">Cancel</button>
                </div>
              </form>
            </div>
          )}

          {products.length > 0 ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
               {products.map(p => (
                 <div key={p.id} className="bg-white p-6 rounded-[2.5rem] border border-slate-200 shadow-sm flex gap-4 group hover:shadow-xl transition-all">
                    <img src={p.image} className="w-20 h-20 rounded-2xl object-cover border border-slate-50 flex-shrink-0" />
                    <div className="flex-1 overflow-hidden">
                       <h4 className="font-black text-slate-900 uppercase tracking-tight text-xs mb-1 truncate">{p.name}</h4>
                       <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest mb-3">${p.price.toFixed(2)} • Qty: {p.stock}</p>
                       <div className="flex gap-2">
                          <button onClick={() => handleEditClick(p)} className="p-2 bg-blue-50 text-blue-600 rounded-lg hover:bg-blue-600 hover:text-white transition-all"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M11 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-5M18.364 5.364a2.121 2.121 0 013 3L12 18l-4 1 1-4L18.364 5.364z" /></svg></button>
                          <button onClick={() => { if(confirm('Permanently delete this service?')) onDeleteProduct(p.id); }} className="p-2 bg-red-50 text-red-600 rounded-lg hover:bg-red-600 hover:text-white transition-all"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg></button>
                       </div>
                    </div>
                 </div>
               ))}
            </div>
          ) : (
             <div className="py-24 text-center bg-white rounded-[3rem] border-2 border-dashed border-slate-200 flex flex-col items-center">
                <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center text-slate-200 mb-6">
                    <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M20 13V6a2 2 0 00-2-2H6a2 2 0 00-2 2v7m14 0v2a2 2 0 01-2 2H6a2 2 0 01-2-2v-2m14 0h-2m-10 0H4" /></svg>
                </div>
                <h3 className="text-xl font-black text-slate-900 uppercase tracking-tighter mb-2">Inventory Empty</h3>
                <p className="text-slate-400 font-bold mb-8">Start your digital empire by adding your first service.</p>
