  // Analytics Calculations
  const analytics = useMemo(() => {
    const totalRevenueUSD = orders.reduce((sum, o) => (o.status === 'confirmed' || o.status === 'delivered') ? sum + o.total : sum, 0);
    const confirmedOrders = orders.filter(o => o.status === 'confirmed' || o.status === 'delivered').length;
    const pendingOrders = orders.filter(o => o.status === 'pending').length;
    const lowStock = products.filter(p => p.stock <= 5);
    const totalBDT = Math.ceil(totalRevenueUSD * 125); // Estimated rate

    return { totalRevenueUSD, confirmedOrders, pendingOrders, lowStock, totalBDT };
  }, [orders, products]);

  const handleImportDefaultTabs = async () => {
    if (!confirm("Import default tabs into database?")) return;
    setSaving(true);
    try {
      const tabsToImport = DEFAULT_CATEGORIES.filter(c => c !== 'All');
      for (const tab of tabsToImport) {
        await onAddCategory(tab);
      }
      alert("✅ Defaults Imported!");
    } catch (e) {
      alert("❌ Import Failed");
    } finally {
      setSaving(false);
    }
