          </div>
          {isFormOpen && (
            <div className="bg-white rounded-[3rem] border border-slate-200 p-10 shadow-2xl">
              <form onSubmit={handleSubmit} className="space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="space-y-6">
                    <div>
                      <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-2">Service Name</label>
                      <input required type="text" className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold outline-none focus:border-blue-500" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
                    </div>
                    <div>
                      <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-2">Description</label>
                      <textarea required className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold outline-none focus:border-blue-500 min-h-[120px]" value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} />
                    </div>
                  </div>
                  <div className="space-y-6">
                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-2">Price ($)</label>
                        <input required type="number" step="0.01" className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold" value={formData.price} onChange={e => setFormData({...formData, price: parseFloat(e.target.value)})} />
                      </div>
                      <div>
                        <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-2">Stock</label>
                        <input required type="number" className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold" value={formData.stock} onChange={e => setFormData({...formData, stock: parseInt(e.target.value)})} />
                      </div>
                    </div>
                    <div>
                      <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-2">Category</label>
                      <select className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                        {categories.map(cat => <option key={cat.id} value={cat.name}>{cat.name}</option>)}
                      </select>
                    </div>
                    <div>
                        <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileUpload} />
                        <button type="button" onClick={() => fileInputRef.current?.click()} className="w-full py-4 bg-slate-100 text-slate-600 rounded-2xl font-black text-[10px] uppercase">{uploading ? 'Processing...' : 'Upload Image'}</button>
                    </div>
                  </div>
                </div>
                <div className="flex gap-4">
                  <button type="submit" disabled={saving || uploading} className="flex-1 py-5 bg-blue-600 text-white rounded-2xl font-black uppercase text-xs tracking-widest shadow-xl">{saving ? 'Syncing...' : (editingId ? 'Update Service' : 'Publish Service')}</button>
                  <button type="button" onClick={resetForm} className="px-10 py-5 bg-slate-100 text-slate-500 rounded-2xl font-black uppercase text-xs">Cancel</button>
                </div>
              </form>
            </div>
          )}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
               {products.map(p => (
                 <div key={p.id} className="bg-white p-6 rounded-[2.5rem] border border-slate-200 shadow-sm flex gap-4 group hover:shadow-xl transition-all">
                    <img src={p.image} className="w-20 h-20 rounded-2xl object-cover flex-shrink-0" />
                    <div className="flex-1 overflow-hidden">
                       <h4 className="font-black text-slate-900 uppercase tracking-tight text-xs mb-1 truncate">{p.name}</h4>
                       <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest mb-3">${p.price.toFixed(2)}</p>
                       <div className="flex gap-2">
                          <button onClick={() => handleEditClick(p)} className="p-2 bg-blue-50 text-blue-600 rounded-lg"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M11 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-5M18.364 5.364a2.121 2.121 0 013 3L12 18l-4 1 1-4L18.364 5.364z" /></svg></button>
                          <button onClick={() => onDeleteProduct(p.id)} className="p-2 bg-red-50 text-red-600 rounded-lg"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg></button>
                       </div>
                    </div>
                 </div>
               ))}
          </div>
        </div>
      )}

      {activeTab === 'orders' && (
        <div className="animate-in slide-in-from-bottom-4 space-y-8">
           <div className="bg-white rounded-[3rem] border border-slate-200 overflow-hidden shadow-sm">
             <table className="w-full text-left">
               <thead className="bg-slate-50/50 border-b border-slate-100">
                 <tr>
                   <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">Order</th>
                   <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">Customer</th>
                   <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Amount</th>
                   <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Fulfillment</th>
                 </tr>
               </thead>
               <tbody className="divide-y divide-slate-50">
                 {orders.map(order => (
                   <tr key={order.id} className="hover:bg-slate-50/30">
                     <td className="px-8 py-6 font-mono text-xs uppercase tracking-widest text-slate-900">#{order.id.slice(0, 8)}</td>
                     <td className="px-8 py-6 text-xs font-black text-slate-900 uppercase">{order.fullName}</td>
                     <td className="px-8 py-6 text-center text-sm font-black text-slate-900">${order.total.toFixed(2)}</td>
                     <td className="px-8 py-6 text-right">
                        <select className="px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest border transition-all" value={order.status} onChange={(e) => onUpdateOrderStatus(order.id, e.target.value as any)}>
                          <option value="pending">Pending</option>
                          <option value="confirmed">Confirmed</option>
                          <option value="delivered">Delivered</option>
                          <option value="cancelled">Cancelled</option>
                        </select>
                     </td>
                   </tr>
                 ))}
               </tbody>
             </table>
           </div>
        </div>
      )}

      {activeTab === 'tabs' && (
        <div className="space-y-8 animate-in slide-in-from-bottom-4">
           <div className="flex flex-col sm:flex-row justify-between items-center bg-white p-6 rounded-[2.5rem] border border-slate-200 shadow-sm gap-4">
              <h2 className="text-xl font-black text-slate-900 uppercase tracking-tighter">Tab Configuration</h2>
              <div className="flex gap-2 w-full sm:w-auto">
                 <button onClick={handleImportDefaultTabs} disabled={saving} className="px-6 py-4 bg-slate-100 text-slate-600 rounded-2xl font-black text-[10px] uppercase">Import Defaults</button>
                 <button onClick={() => { setIsCategoryFormOpen(true); setEditingCategoryId(null); setCategoryName(''); }} className="px-8 py-4 bg-blue-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl">Add New Tab</button>
              </div>
           </div>
           {isCategoryFormOpen && (
              <form onSubmit={handleCategorySubmit} className="bg-white rounded-[3rem] border border-slate-200 p-10 shadow-2xl max-w-2xl mx-auto w-full">
                 <h3 className="text-xl font-black text-slate-900 uppercase mb-8 text-center">{editingCategoryId ? 'Rename Tab' : 'Create Custom Tab'}</h3>
                 <input required className="w-full px-8 py-5 bg-slate-50 border border-slate-200 rounded-3xl font-black text-xl text-center mb-6" value={categoryName} onChange={e => setCategoryName(e.target.value)} placeholder="e.g. Gmail Store" />
                 <div className="flex gap-4">
                    <button type="submit" disabled={saving} className="flex-1 py-5 bg-blue-600 text-white rounded-2xl font-black uppercase text-xs tracking-widest shadow-xl">Sync Tab</button>
                    <button type="button" onClick={() => setIsCategoryFormOpen(false)} className="px-8 py-5 bg-slate-100 text-slate-500 rounded-2xl font-black uppercase text-xs">Dismiss</button>
                 </div>
              </form>
           )}
           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {categories.map((cat, idx) => (
                        <div key={cat.id} className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm group hover:shadow-xl transition-all">
                            <div className="flex items-center justify-between mb-8">
                                <div className="flex items-center gap-4">
                                    <div className="w-12 h-12 bg-blue-50 text-blue-600 rounded-2xl flex items-center justify-center text-lg font-black">{idx + 1}</div>
                                    <h4 className="text-xl font-black text-slate-900 tracking-tight uppercase">{cat.name}</h4>
                                </div>
                            </div>
                            <div className="flex justify-between items-center pt-6 border-t border-slate-50">
                                <p className="text-[9px] font-black text-slate-300 uppercase tracking-[0.2em]">Management</p>
                                <div className="flex gap-3">
                                    <button onClick={() => { setEditingCategoryId(cat.id); setCategoryName(cat.name); setIsCategoryFormOpen(true); }} className="p-3 bg-slate-50 text-slate-400 hover:text-blue-600 rounded-xl transition-all"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M11 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-5M18.364 5.364a2.121 2.121 0 013 3L12 18l-4 1 1-4L18.364 5.364z" /></svg></button>
                                    <button onClick={() => { if(confirm(`Delete "${cat.name}" tab?`)) onDeleteCategory(cat.id); }} className="p-3 bg-red-50 text-red-600 rounded-xl hover:bg-red-600 hover:text-white transition-all"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6" /></svg></button>
                                </div>
                            </div>
                        </div>
                    ))}
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Product, Order, CartItem, Category } from '../types';
import { supabase } from '../supabaseClient';
import { CATEGORIES as DEFAULT_CATEGORIES } from '../constants';

interface AdminPanelProps {
  products: Product[];
  orders: Order[];
  categories: Category[];
  onAddProduct: (p: Omit<Product, 'id'>) => void;
  onUpdateProduct: (id: string, p: Partial<Product>) => void;
  onDeleteProduct: (id: string) => void;
  onUpdateOrderStatus: (orderId: string, status: Order['status']) => void;
  onAddCategory: (name: string) => void;
  onUpdateCategory: (id: string, name: string) => void;
  onDeleteCategory: (id: string) => void;
  onBack: () => void;
}

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  products, 
  orders, 
  categories,
  onAddProduct, 
  onUpdateProduct,
  onDeleteProduct, 
  onUpdateOrderStatus,
  onAddCategory,
  onUpdateCategory,
  onDeleteCategory,
  onBack 
}) => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'inventory' | 'orders' | 'tabs'>('dashboard');
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [uploading, setUploading] = useState(false);
  const [saving, setSaving] = useState(false);

  const [isCategoryFormOpen, setIsCategoryFormOpen] = useState(false);
  const [editingCategoryId, setEditingCategoryId] = useState<string | null>(null);
  const [categoryName, setCategoryName] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const ownerPhotoUrl = "https://media.licdn.com/dms/image/v2/D5603AQF6FS5z4Ky4RQ/profile-displayphoto-shrink_200_200/B56Zu4YNm2G0AY-/0/1768324915128?e=2147483647&v=beta&t=_coKuJKl31AvjMDdGeLrigjfgyD8rtgblh-J_kP8Ruo";

  const [formData, setFormData] = useState({
    name: '',
    description: '',
    price: 0,
    category: '',
    image: '',
    stock: 10,
    rating: 5,
    isPublic: true
  });

  useEffect(() => {
    if (!formData.category && categories.length > 0) {
      setFormData(prev => ({ ...prev, category: categories[0].name }));
    } else if (!formData.category && categories.length === 0) {
      setFormData(prev => ({ ...prev, category: DEFAULT_CATEGORIES[1] }));
    }
  }, [categories, isFormOpen]);

  // Simplified Analytics
  const totalRevenue = orders.reduce((sum, o) => (o.status === 'confirmed' || o.status === 'delivered') ? sum + o.total : sum, 0);
  const pendingOrders = orders.filter(o => o.status === 'pending').length;

  const handleImportDefaultTabs = async () => {
    if (!confirm("Are you sure you want to import default tabs?")) return;
    setSaving(true);
    try {
      const tabsToImport = DEFAULT_CATEGORIES.filter(c => c !== 'All');
      for (let i = 0; i < tabsToImport.length; i++) {
        await onAddCategory(tabsToImport[i]);
      }
      alert("✅ Default tabs imported successfully!");
    } catch (e) {
      alert("❌ Failed to import tabs");
    } finally {
      setSaving(false);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    try {
      setUploading(true);
      if (!e.target.files || e.target.files.length === 0) return;
      const file = e.target.files[0];
      const fileExt = file.name.split('.').pop();
      const fileName = `${Math.random()}.${fileExt}`;
      const filePath = `product-images/${fileName}`;
      const { error: uploadError } = await supabase.storage.from('products').upload(filePath, file);
      if (uploadError) throw uploadError;
      const { data } = supabase.storage.from('products').getPublicUrl(filePath);
      if (data) {
        setFormData(prev => ({ ...prev, image: data.publicUrl }));
        alert("✅ Image Uploaded!");
      }
    } catch (error: any) {
      alert("❌ Upload Failed: " + error.message);
    } finally {
      setUploading(false);
    }
  };

  const handleEditClick = (product: Product) => {
    setEditingId(product.id);
    setFormData({
      name: product.name,
      description: product.description,
      price: product.price,
      category: product.category,
      image: product.image,
      stock: product.stock,
      rating: product.rating,
      isPublic: product.isPublic !== undefined ? product.isPublic : true
    });
    setIsFormOpen(true);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);
    try {
      if (editingId) { await onUpdateProduct(editingId, formData); }
      else { await onAddProduct(formData); }
      resetForm();
    } catch (e) {
      alert("❌ Error saving product");
    } finally { setSaving(false); }
  };

  const handleCategorySubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!categoryName.trim()) return;
    setSaving(true);
    try {
      if (editingCategoryId) { await onUpdateCategory(editingCategoryId, categoryName); }
      else { await onAddCategory(categoryName); }
      setCategoryName('');
      setEditingCategoryId(null);
      setIsCategoryFormOpen(false);
    } catch (e) {
      alert("❌ Error managing tab");
    } finally {
      setSaving(false);
    }
  };

  const resetForm = () => {
    setIsFormOpen(false);
    setEditingId(null);
    setFormData({ 
      name: '', description: '', price: 0, 
      category: categories.length > 0 ? categories[0].name : DEFAULT_CATEGORIES[1], 
      image: '', stock: 10, rating: 5, isPublic: true 
    });
  };

  return (
    <div className="animate-in fade-in duration-700 max-w-7xl mx-auto space-y-10 pb-20">
      {/* Simple Header */}
      <div className="bg-slate-900 rounded-[2.5rem] p-8 shadow-2xl flex flex-col md:flex-row justify-between items-center gap-6">
        <div className="flex items-center gap-6">
          <div className="w-20 h-20 rounded-full border-4 border-white/10 overflow-hidden shadow-xl">
            <img src={ownerPhotoUrl} alt="Admin" className="w-full h-full object-cover" />
          </div>
          <div>
            <h1 className="text-2xl font-black text-white uppercase tracking-tighter">Mehedi Hasan</h1>
            <p className="text-[10px] font-black text-blue-400 uppercase tracking-widest">DS Store Admin Panel</p>
          </div>
        </div>
        <button onClick={onBack} className="px-8 py-4 bg-white/10 text-white border border-white/20 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-white hover:text-slate-900 transition-all">Exit Panel</button>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        {[
          { label: 'Total Revenue', value: `$${totalRevenue.toFixed(2)}`, icon: 'M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2', color: 'bg-blue-600' },
          { label: 'Pending Orders', value: pendingOrders, icon: 'M12 8v4l3 3', color: 'bg-amber-500' },
          { label: 'Total Products', value: products.length, icon: 'M20 7l-8-4-8 4', color: 'bg-indigo-600' },
          { label: 'Active Tabs', value: categories.length, icon: 'M7 7h.01M7 3h5', color: 'bg-green-600' }
        ].map((stat, i) => (
          <div key={i} className="bg-white p-6 rounded-[2rem] border border-slate-200 shadow-sm flex items-center justify-between">
            <div>
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{stat.label}</p>
              <p className="text-2xl font-black text-slate-900">{stat.value}</p>
            </div>
            <div className={`w-12 h-12 ${stat.color} text-white rounded-2xl flex items-center justify-center`}>
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d={stat.icon} /></svg>
            </div>
          </div>
        ))}
      </div>

      {/* Tabs Menu */}
      <div className="bg-white p-2 rounded-full border border-slate-200 flex flex-wrap gap-1 w-fit shadow-sm">
        {[
          { id: 'dashboard', label: 'Dashboard' },
          { id: 'inventory', label: 'Products' },
          { id: 'orders', label: 'Orders' },
          { id: 'tabs', label: 'Tab Manager' }
        ].map(tab => (
          <button 
            key={tab.id} 
            onClick={() => setActiveTab(tab.id as any)} 
            className={`px-8 py-3 rounded-full text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === tab.id ? 'bg-[#0F172A] text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}
          >
            {tab.label}
          </button>
        ))}
      </div>

      {/* Content Areas */}
      {activeTab === 'dashboard' && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 animate-in slide-in-from-bottom-4">
          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200">
            <h3 className="text-xl font-black text-slate-900 uppercase tracking-tight mb-6">Recent Sales</h3>
            <div className="space-y-4">
              {orders.slice(0, 5).map(order => (
                <div key={order.id} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl">
                  <div>
                    <p className="text-xs font-black text-slate-900">Order #{order.id.slice(0, 8)}</p>
                    <p className="text-[10px] font-bold text-slate-400 uppercase">{order.fullName}</p>
                  </div>
                  <div className="text-right">
                    <p className="text-sm font-black text-blue-600">${order.total.toFixed(2)}</p>
                    <p className="text-[9px] font-black uppercase text-slate-400">{order.status}</p>
                  </div>
                </div>
              ))}
              {orders.length === 0 && <p className="text-center py-10 text-slate-300 font-black uppercase tracking-widest">No Recent Sales</p>}
            </div>
          </div>
          <div className="bg-slate-900 p-8 rounded-[2.5rem] text-white flex flex-col justify-center items-center text-center">
             <div className="w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center mb-6 shadow-xl">
                <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" /></svg>
             </div>
             <h3 className="text-2xl font-black uppercase tracking-tighter">Business Overview</h3>
             <p className="text-slate-400 text-sm font-bold mt-2">Welcome back to your store manager.</p>
          </div>
        </div>
      )}

      {activeTab === 'inventory' && (
        <div className="space-y-8 animate-in slide-in-from-bottom-4">
          <div className="flex justify-between items-center bg-white p-6 rounded-[2.5rem] border border-slate-200">
             <h2 className="text-xl font-black text-slate-900 uppercase tracking-tighter ml-4">Product Inventory</h2>
             <button onClick={() => { resetForm(); setIsFormOpen(true); }} className="px-8 py-4 bg-blue-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl">+ Add New Service</button>
          </div>

          {isFormOpen && (
            <div className="bg-white rounded-[2.5rem] border border-slate-200 p-8 shadow-2xl">
              <form onSubmit={handleSubmit} className="space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="space-y-6">
                    <div>
                      <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-2">Name</label>
                      <input required type="text" className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold outline-none" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
                    </div>
                    <div>
                      <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-2">Description</label>
                      <textarea required className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold outline-none min-h-[120px]" value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} />
                    </div>
                  </div>
                  <div className="space-y-6">
                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-2">Price ($)</label>
                        <input required type="number" step="0.01" className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold" value={formData.price} onChange={e => setFormData({...formData, price: parseFloat(e.target.value)})} />
                      </div>
                      <div>
                        <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-2">Stock</label>
                        <input required type="number" className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold" value={formData.stock} onChange={e => setFormData({...formData, stock: parseInt(e.target.value)})} />
                      </div>
                    </div>
                    <div>
                      <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-2">Category (Tab)</label>
                      <select className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                        {categories.map(cat => <option key={cat.id} value={cat.name}>{cat.name}</option>)}
                      </select>
                    </div>
                    <div>
                        <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileUpload} />
                        <button type="button" onClick={() => fileInputRef.current?.click()} className="w-full py-4 bg-slate-100 text-slate-600 rounded-2xl font-black text-[10px] uppercase">{uploading ? 'Processing...' : 'Upload Image'}</button>
                    </div>
                  </div>
                </div>
                <div className="flex gap-4">
                  <button type="submit" disabled={saving || uploading} className="flex-1 py-5 bg-blue-600 text-white rounded-2xl font-black uppercase text-xs tracking-widest shadow-xl">{saving ? 'Saving...' : (editingId ? 'Update Service' : 'Publish Service')}</button>
                  <button type="button" onClick={resetForm} className="px-10 py-5 bg-slate-100 text-slate-500 rounded-2xl font-black uppercase text-xs">Cancel</button>
                </div>
              </form>
            </div>
          )}

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
               {products.map(p => (
                 <div key={p.id} className="bg-white p-6 rounded-[2rem] border border-slate-200 shadow-sm flex gap-4 group">
                    <img src={p.image} className="w-20 h-20 rounded-2xl object-cover border border-slate-50" />
                    <div className="flex-1 overflow-hidden">
                       <h4 className="font-black text-slate-900 uppercase tracking-tight text-xs mb-1 truncate">{p.name}</h4>
                       <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest mb-3">${p.price.toFixed(2)}</p>
                       <div className="flex gap-2">
                          <button onClick={() => handleEditClick(p)} className="p-2 bg-blue-50 text-blue-600 rounded-lg hover:bg-blue-600 hover:text-white transition-all"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M11 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-5M18.364 5.364a2.121 2.121 0 013 3L12 18l-4 1 1-4L18.364 5.364z" /></svg></button>
                          <button onClick={() => { if(confirm('Delete?')) onDeleteProduct(p.id); }} className="p-2 bg-red-50 text-red-600 rounded-lg hover:bg-red-600 hover:text-white transition-all"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6" /></svg></button>
                       </div>
                    </div>
                 </div>
               ))}
          </div>
        </div>
      )}

      {activeTab === 'orders' && (
        <div className="animate-in slide-in-from-bottom-4 space-y-8">
           <div className="bg-white rounded-[2.5rem] border border-slate-200 overflow-hidden shadow-sm overflow-x-auto">
             <table className="w-full text-left">
               <thead className="bg-slate-50/50 border-b border-slate-100">
                 <tr>
                   <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">ID</th>
                   <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">Customer</th>
                   <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Total</th>
                   <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Status</th>
                 </tr>
               </thead>
               <tbody className="divide-y divide-slate-50">
                 {orders.map(order => (
                   <tr key={order.id} className="hover:bg-slate-50/30">
                     <td className="px-8 py-6 font-mono text-xs uppercase text-slate-900">#{order.id.slice(0, 8)}</td>
                     <td className="px-8 py-6 text-xs font-black text-slate-900 uppercase">{order.fullName}</td>
                     <td className="px-8 py-6 text-center text-sm font-black text-slate-900">${order.total.toFixed(2)}</td>
                     <td className="px-8 py-6 text-right">
                        <select 
                          className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest border transition-all ${
                            order.status === 'delivered' ? 'bg-green-50 border-green-200 text-green-600' :
                            order.status === 'confirmed' ? 'bg-blue-50 border-blue-200 text-blue-600' :
                            'bg-amber-50 border-amber-200 text-amber-600'
                          }`}
                          value={order.status}
                          onChange={(e) => onUpdateOrderStatus(order.id, e.target.value as any)}
                        >
                          <option value="pending">Pending</option>
                          <option value="confirmed">Confirmed</option>
                          <option value="delivered">Delivered</option>
                          <option value="cancelled">Cancelled</option>
                        </select>
                     </td>
                   </tr>
                 ))}
               </tbody>
             </table>
             {orders.length === 0 && <p className="text-center py-20 text-slate-300 font-black uppercase tracking-widest">No orders found</p>}
           </div>
        </div>
      )}

      {activeTab === 'tabs' && (
        <div className="space-y-8 animate-in slide-in-from-bottom-4">
           <div className="flex flex-col sm:flex-row justify-between items-center bg-white p-6 rounded-[2rem] border border-slate-200 gap-4">
              <h2 className="text-xl font-black text-slate-900 uppercase tracking-tighter">Tab Configuration</h2>
              <div className="flex gap-2 w-full sm:w-auto">
                 <button onClick={handleImportDefaultTabs} disabled={saving} className="px-6 py-4 bg-slate-100 text-slate-600 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-slate-200 transition-all">Import Defaults</button>
                 <button onClick={() => { setIsCategoryFormOpen(true); setEditingCategoryId(null); setCategoryName(''); }} className="px-8 py-4 bg-blue-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl">Add New Tab</button>
              </div>
           </div>

           {isCategoryFormOpen && (
              <form onSubmit={handleCategorySubmit} className="bg-white rounded-[2.5rem] border border-slate-200 p-10 shadow-2xl max-w-2xl mx-auto w-full">
                 <h3 className="text-xl font-black text-slate-900 uppercase mb-8 text-center">{editingCategoryId ? 'Rename Tab' : 'Add New Tab'}</h3>
                 <input required className="w-full px-8 py-5 bg-slate-50 border border-slate-200 rounded-3xl outline-none font-black text-xl text-center mb-6" value={categoryName} onChange={e => setCategoryName(e.target.value)} placeholder="e.g. Virtual Visa" />
                 <div className="flex gap-4">
                    <button type="submit" disabled={saving} className="flex-1 py-5 bg-blue-600 text-white rounded-2xl font-black uppercase text-xs tracking-widest shadow-xl">Sync Tab</button>
                    <button type="button" onClick={() => setIsCategoryFormOpen(false)} className="px-8 py-5 bg-slate-100 text-slate-500 rounded-2xl font-black uppercase text-xs">Cancel</button>
                 </div>
              </form>
           )}

           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {categories.map((cat, idx) => (
                 <div key={cat.id} className="bg-white p-6 rounded-[2rem] border border-slate-200 shadow-sm group">
                    <div className="flex items-center justify-between mb-8">
                       <div className="flex items-center gap-4">
                          <div className="w-12 h-12 bg-blue-50 text-blue-600 rounded-2xl flex items-center justify-center text-lg font-black">{idx + 1}</div>
                          <h4 className="text-lg font-black text-slate-900 uppercase tracking-tight">{cat.name}</h4>
                       </div>
                    </div>
                    <div className="flex justify-between items-center pt-6 border-t border-slate-50">
                       <p className="text-[9px] font-black text-slate-300 uppercase tracking-widest">Controls</p>
                       <div className="flex gap-3">
                          <button onClick={() => { setEditingCategoryId(cat.id); setCategoryName(cat.name); setIsCategoryFormOpen(true); }} className="text-slate-300 hover:text-blue-600"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M11 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-5M18.364 5.364a2.121 2.121 0 013 3L12 18l-4 1 1-4L18.364 5.364z" /></svg></button>
                          <button onClick={() => { if(confirm(`Delete "${cat.name}" tab?`)) onDeleteCategory(cat.id); }} className="text-slate-300 hover:text-red-600"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6" /></svg></button>
                       </div>
                    </div>
                 </div>
              ))}
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Product, Order, CartItem, Category } from '../types';
import { supabase } from '../supabaseClient';
import { CATEGORIES as DEFAULT_CATEGORIES } from '../constants';

interface AdminPanelProps {
  products: Product[];
  orders: Order[];
  categories: Category[];
  onAddProduct: (p: Omit<Product, 'id'>) => void;
  onUpdateProduct: (id: string, p: Partial<Product>) => void;
  onDeleteProduct: (id: string) => void;
  onUpdateOrderStatus: (orderId: string, status: Order['status']) => void;
  onAddCategory: (name: string) => void;
  onUpdateCategory: (id: string, name: string) => void;
  onDeleteCategory: (id: string) => void;
  onBack: () => void;
}

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  products, 
  orders, 
  categories,
  onAddProduct, 
  onUpdateProduct,
  onDeleteProduct, 
  onUpdateOrderStatus,
  onAddCategory,
  onUpdateCategory,
  onDeleteCategory,
  onBack 
}) => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'inventory' | 'orders' | 'tabs'>('dashboard');
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [uploading, setUploading] = useState(false);
  const [saving, setSaving] = useState(false);

  const [isCategoryFormOpen, setIsCategoryFormOpen] = useState(false);
  const [editingCategoryId, setEditingCategoryId] = useState<string | null>(null);
  const [categoryName, setCategoryName] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const ownerPhotoUrl = "https://media.licdn.com/dms/image/v2/D5603AQF6FS5z4Ky4RQ/profile-displayphoto-shrink_200_200/B56Zu4YNm2G0AY-/0/1768324915128?e=2147483647&v=beta&t=_coKuJKl31AvjMDdGeLrigjfgyD8rtgblh-J_kP8Ruo";

  const [formData, setFormData] = useState({
    name: '',
    description: '',
    price: 0,
    category: '',
    image: '',
    stock: 10,
    rating: 5,
    isPublic: true
  });

  useEffect(() => {
    if (!formData.category && categories.length > 0) {
      setFormData(prev => ({ ...prev, category: categories[0].name }));
    } else if (!formData.category && categories.length === 0) {
      setFormData(prev => ({ ...prev, category: DEFAULT_CATEGORIES[1] }));
    }
  }, [categories, isFormOpen]);

  // Analytics
  const stats = useMemo(() => {
    const totalRev = orders.reduce((sum, o) => (o.status === 'confirmed' || o.status === 'delivered') ? sum + o.total : sum, 0);
    const pending = orders.filter(o => o.status === 'pending').length;
    const completed = orders.filter(o => o.status === 'delivered').length;
    return { totalRev, pending, completed };
  }, [orders]);

  const handleImportDefaultTabs = async () => {
    if (!confirm("Import default tabs into database?")) return;
    setSaving(true);
    try {
      const tabsToImport = DEFAULT_CATEGORIES.filter(c => c !== 'All');
      for (const tab of tabsToImport) {
        await onAddCategory(tab);
      }
      alert("✅ Default tabs imported!");
    } catch (e) {
      alert("❌ Import failed.");
    } finally {
      setSaving(false);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    try {
      setUploading(true);
      if (!e.target.files?.[0]) return;
      const file = e.target.files[0];
      const fileExt = file.name.split('.').pop();
      const fileName = `${Math.random()}.${fileExt}`;
      const filePath = `product-images/${fileName}`;
      const { error: uploadError } = await supabase.storage.from('products').upload(filePath, file);
      if (uploadError) throw uploadError;
      const { data } = supabase.storage.from('products').getPublicUrl(filePath);
      if (data) {
        setFormData(prev => ({ ...prev, image: data.publicUrl }));
        alert("✅ Image synced successfully!");
      }
    } catch (error: any) {
      alert("❌ Upload failed: " + error.message);
    } finally {
      setUploading(false);
    }
  };

  const handleEditClick = (product: Product) => {
    setEditingId(product.id);
    setFormData({
      name: product.name,
      description: product.description,
      price: product.price,
      category: product.category,
      image: product.image,
      stock: product.stock,
      rating: product.rating,
      isPublic: product.isPublic !== undefined ? product.isPublic : true
    });
    setIsFormOpen(true);
    window.scrollTo({ top: 400, behavior: 'smooth' });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);
    try {
      if (editingId) { await onUpdateProduct(editingId, formData); }
      else { await onAddProduct(formData); }
      resetForm();
    } catch (e) {
      alert("❌ Operation failed.");
    } finally { setSaving(false); }
  };

  const handleCategorySubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!categoryName.trim()) return;
    setSaving(true);
    try {
      if (editingCategoryId) { await onUpdateCategory(editingCategoryId, categoryName); }
      else { await onAddCategory(categoryName); }
      setCategoryName('');
      setEditingCategoryId(null);
      setIsCategoryFormOpen(false);
    } catch (e) {
      alert("❌ Operation failed.");
    } finally {
      setSaving(false);
    }
  };

  const resetForm = () => {
    setIsFormOpen(false);
    setEditingId(null);
    setFormData({ 
      name: '', description: '', price: 0, 
      category: categories.length > 0 ? categories[0].name : DEFAULT_CATEGORIES[1], 
      image: '', stock: 10, rating: 5, isPublic: true 
    });
  };

  return (
    <div className="animate-in fade-in duration-700 max-w-7xl mx-auto space-y-8 pb-24">
      {/* PROFESSIONAL HEADER */}
      <div className="bg-[#0F172A] rounded-[2rem] md:rounded-[3rem] p-8 md:p-12 shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 right-0 w-64 h-64 bg-blue-600/10 blur-[80px] -mr-32 -mt-32"></div>
        <div className="relative z-10 flex flex-col md:flex-row justify-between items-center gap-8">
          <div className="flex items-center gap-6 text-center md:text-left">
            <div className="relative group">
              <div className="absolute inset-0 bg-blue-500 rounded-full blur-md opacity-0 group-hover:opacity-30 transition-opacity"></div>
              <div className="w-24 h-24 rounded-full border-4 border-white/10 overflow-hidden shadow-2xl relative z-10">
                <img src={ownerPhotoUrl} alt="Admin" className="w-full h-full object-cover transition-transform group-hover:scale-110" />
              </div>
            </div>
            <div>
              <h1 className="text-3xl md:text-4xl font-black text-white uppercase tracking-tighter">Control Center</h1>
              <p className="text-xs font-black text-blue-400 uppercase tracking-[0.3em] mt-2">Master Administrator: Mehedi Hasan</p>
              <div className="flex items-center justify-center md:justify-start gap-2 mt-3">
                <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
                <span className="text-[10px] font-bold text-white/50 uppercase tracking-widest">Gateway Encrypted & Live</span>
              </div>
            </div>
          </div>
          <button onClick={onBack} className="px-10 py-4 bg-white/5 hover:bg-white/10 text-white border border-white/10 rounded-2xl font-black text-xs uppercase tracking-widest transition-all shadow-xl backdrop-blur-md">
            Close Session
          </button>
        </div>
      </div>

      {/* QUICK STATS CARDS */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        {[
          { label: 'Total Revenue', value: `$${stats.totalRev.toFixed(2)}`, sub: 'Gross Earnings', icon: 'M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2', color: 'text-emerald-500', bg: 'bg-emerald-50' },
          { label: 'Active Orders', value: stats.pending, sub: 'Needs Verification', icon: 'M12 8v4l3 3', color: 'text-amber-500', bg: 'bg-amber-50' },
          { label: 'Completed', value: stats.completed, sub: 'Successfully Delivered', icon: 'M9 12l2 2 4-4', color: 'text-blue-500', bg: 'bg-blue-50' },
          { label: 'Services', value: products.length, sub: 'Total Catalog Units', icon: 'M20 7l-8-4-8 4', color: 'text-indigo-500', bg: 'bg-indigo-50' }
        ].map((stat, i) => (
          <div key={i} className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm flex items-center justify-between hover:shadow-md transition-all">
            <div className="space-y-1">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{stat.label}</p>
              <h3 className="text-2xl font-black text-slate-900 tracking-tighter">{stat.value}</h3>
              <p className="text-[10px] font-bold text-slate-400">{stat.sub}</p>
            </div>
            <div className={`w-14 h-14 ${stat.bg} ${stat.color} rounded-2xl flex items-center justify-center shadow-inner`}>
              <svg className="w-7 h-7" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d={stat.icon} /></svg>
            </div>
          </div>
        ))}
      </div>

      {/* TAB NAVIGATION */}
      <div className="flex justify-center">
        <div className="bg-white p-1.5 rounded-full border border-slate-200 flex flex-wrap gap-1 shadow-lg">
          {[
            { id: 'dashboard', label: 'Overview' },
            { id: 'inventory', label: 'Inventory' },
            { id: 'orders', label: 'Live Orders' },
            { id: 'tabs', label: 'Manager' }
          ].map(tab => (
            <button 
              key={tab.id} 
              onClick={() => setActiveTab(tab.id as any)} 
              className={`px-10 py-3 rounded-full text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === tab.id ? 'bg-[#0F172A] text-white shadow-xl scale-105' : 'text-slate-500 hover:bg-slate-50'}`}
            >
              {tab.label}
            </button>
          ))}
        </div>
      </div>

      {/* DYNAMIC CONTENT AREAS */}
      {activeTab === 'dashboard' && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 animate-in slide-in-from-bottom-4">
          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm">
            <div className="flex items-center justify-between mb-8">
              <h3 className="text-xl font-black text-slate-900 uppercase tracking-tight">Recent Live Sales</h3>
              <button onClick={() => setActiveTab('orders')} className="text-[10px] font-black text-blue-600 uppercase tracking-widest hover:underline">View History</button>
            </div>
            <div className="space-y-4">
              {orders.slice(0, 5).map(order => (
                <div key={order.id} className="flex items-center justify-between p-5 bg-slate-50/50 rounded-2xl border border-slate-100">
                  <div className="flex items-center gap-4">
                    <div className="w-10 h-10 bg-white rounded-xl shadow-sm flex items-center justify-center text-xs font-black text-blue-600">ID</div>
                    <div>
                      <p className="text-xs font-black text-slate-900">#{order.id.slice(0, 8)}</p>
                      <p className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter">{order.fullName}</p>
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="text-sm font-black text-slate-900">${order.total.toFixed(2)}</p>
                    <span className={`text-[8px] font-black uppercase px-2 py-0.5 rounded-md ${order.status === 'delivered' ? 'bg-green-100 text-green-600' : 'bg-amber-100 text-amber-600'}`}>
                      {order.status}
                    </span>
                  </div>
                </div>
              ))}
              {orders.length === 0 && <p className="text-center py-10 text-slate-300 font-black uppercase tracking-widest">Waiting for first sale</p>}
            </div>
          </div>
          <div className="bg-slate-900 p-8 rounded-[2.5rem] text-white flex flex-col justify-center items-center text-center shadow-2xl relative overflow-hidden">
             <div className="absolute top-0 right-0 w-32 h-32 bg-blue-600/20 blur-3xl -mr-16 -mt-16"></div>
             <div className="w-20 h-20 bg-blue-600 rounded-3xl flex items-center justify-center mb-8 shadow-2xl shadow-blue-500/30">
                <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" /></svg>
             </div>
             <h3 className="text-3xl font-black uppercase tracking-tighter">Global Metrics</h3>
             <p className="text-slate-400 text-sm font-bold mt-3 max-w-xs">Monitoring all digital transactions across the DS SERVICE STORE infrastructure.</p>
          </div>
        </div>
      )}

      {activeTab === 'inventory' && (
        <div className="space-y-8 animate-in slide-in-from-bottom-4">
          <div className="flex flex-col sm:flex-row justify-between items-center bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm gap-4">
             <div className="ml-4">
               <h2 className="text-xl font-black text-slate-900 uppercase tracking-tighter">Product Inventory</h2>
               <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Manage your digital catalog</p>
             </div>
             <button onClick={() => { resetForm(); setIsFormOpen(true); }} className="w-full sm:w-auto px-10 py-4 bg-blue-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl hover:bg-slate-900 transition-all">+ Add New Service</button>
          </div>

          {isFormOpen && (
            <div className="bg-white rounded-[2.5rem] border-2 border-slate-100 p-8 md:p-12 shadow-2xl animate-in zoom-in-95 duration-500">
              <form onSubmit={handleSubmit} className="space-y-10">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                  <div className="space-y-6">
                    <div>
                      <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-2">Service Identity</label>
                      <input required type="text" placeholder="e.g. Premium iCloud ID" className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl font-black text-sm outline-none focus:border-blue-500 transition-colors shadow-inner" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
                    </div>
                    <div>
                      <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-2">Technical Description</label>
                      <textarea required placeholder="Outline features..." className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold text-sm outline-none focus:border-blue-500 min-h-[140px] shadow-inner" value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} />
                    </div>
                  </div>
                  <div className="space-y-6">
                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-2">List Price ($)</label>
                        <input required type="number" step="0.01" className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl font-black shadow-inner" value={formData.price} onChange={e => setFormData({...formData, price: parseFloat(e.target.value)})} />
                      </div>
                      <div>
                        <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-2">Stock Volume</label>
                        <input required type="number" className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl font-black shadow-inner" value={formData.stock} onChange={e => setFormData({...formData, stock: parseInt(e.target.value)})} />
                      </div>
                    </div>
                    <div>
                      <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-2">Assigned Category</label>
                      <select className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl font-black text-sm" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                        {categories.map(cat => <option key={cat.id} value={cat.name}>{cat.name}</option>)}
                      </select>
                    </div>
                    <div>
                        <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 ml-2">Service Visualization</label>
                        <div className="flex gap-4">
                           <div className="w-20 h-20 bg-slate-100 rounded-2xl border border-slate-200 overflow-hidden flex-shrink-0">
                              {formData.image ? <img src={formData.image} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center text-slate-300"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg></div>}
                           </div>
                           <div className="flex-1">
                              <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileUpload} />
                              <button type="button" onClick={() => fileInputRef.current?.click()} className="w-full py-4 bg-slate-900 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-blue-600 transition-all">{uploading ? 'Syncing...' : 'Upload Media'}</button>
                           </div>
                        </div>
                    </div>
                  </div>
                </div>
                <div className="flex gap-4 pt-6 border-t border-slate-100">
                  <button type="submit" disabled={saving || uploading} className="flex-1 py-5 bg-blue-600 text-white rounded-2xl font-black uppercase text-xs tracking-widest shadow-2xl hover:bg-[#0F172A] transition-all">{saving ? 'Processing...' : (editingId ? 'Confirm Updates' : 'Publish Asset')}</button>
                  <button type="button" onClick={resetForm} className="px-12 py-5 bg-slate-100 text-slate-500 rounded-2xl font-black uppercase text-xs hover:bg-red-50 hover:text-red-500 transition-all">Cancel</button>
                </div>
              </form>
            </div>
          )}

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
               {products.map(p => (
                 <div key={p.id} className="bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm flex gap-5 group hover:shadow-xl hover:-translate-y-1 transition-all">
                    <img src={p.image} className="w-20 h-20 rounded-2xl object-cover border border-slate-50 shadow-sm flex-shrink-0" />
                    <div className="flex-1 overflow-hidden flex flex-col justify-between">
                       <div>
                         <h4 className="font-black text-slate-900 uppercase tracking-tight text-xs truncate">{p.name}</h4>
                         <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest mt-1">${p.price.toFixed(2)} • Stk: {p.stock}</p>
                       </div>
                       <div className="flex gap-2 mt-4">
                          <button onClick={() => handleEditClick(p)} className="flex-1 p-2 bg-slate-50 text-slate-400 hover:bg-blue-600 hover:text-white rounded-xl transition-all flex items-center justify-center"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M11 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-5M18.364 5.364a2.121 2.121 0 013 3L12 18l-4 1 1-4L18.364 5.364z" /></svg></button>
                          <button onClick={() => { if(confirm('Delete permanently?')) onDeleteProduct(p.id); }} className="flex-1 p-2 bg-slate-50 text-slate-400 hover:bg-red-600 hover:text-white rounded-xl transition-all flex items-center justify-center"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg></button>
                       </div>
                    </div>
                 </div>
               ))}
          </div>
        </div>
      )}

      {activeTab === 'orders' && (
        <div className="animate-in slide-in-from-bottom-4 space-y-8">
           <div className="bg-white rounded-[2.5rem] border border-slate-100 overflow-hidden shadow-sm overflow-x-auto">
             <table className="w-full text-left">
               <thead className="bg-[#0F172A] border-b border-slate-800">
                 <tr>
                   <th className="px-8 py-6 text-[9px] font-black text-slate-400 uppercase tracking-widest">Order Ref</th>
                   <th className="px-8 py-6 text-[9px] font-black text-slate-400 uppercase tracking-widest">Customer</th>
                   <th className="px-8 py-6 text-[9px] font-black text-slate-400 uppercase tracking-widest text-center">Amount</th>
                   <th className="px-8 py-6 text-[9px] font-black text-slate-400 uppercase tracking-widest text-right">Workflow</th>
                 </tr>
               </thead>
               <tbody className="divide-y divide-slate-50">
                 {orders.map(order => (
                   <tr key={order.id} className="hover:bg-slate-50/50 transition-colors">
                     <td className="px-8 py-6">
                        <p className="text-xs font-black text-slate-900 font-mono tracking-widest">#{order.id.slice(0, 8)}</p>
                        <p className="text-[9px] font-bold text-slate-400 uppercase mt-1">{new Date(order.createdAt).toLocaleDateString()}</p>
                     </td>
                     <td className="px-8 py-6">
                        <p className="text-xs font-black text-slate-900 uppercase">{order.fullName}</p>
                        <p className="text-[9px] font-bold text-blue-600 uppercase tracking-tighter mt-0.5">{order.whatsappNumber}</p>
                     </td>
                     <td className="px-8 py-6 text-center text-sm font-black text-slate-900">${order.total.toFixed(2)}</td>
                     <td className="px-8 py-6 text-right">
                        <select 
                          className={`px-4 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest border-2 transition-all ${
                            order.status === 'delivered' ? 'bg-green-50 border-green-200 text-green-600' :
                            order.status === 'confirmed' ? 'bg-blue-50 border-blue-200 text-blue-600' :
                            'bg-amber-50 border-amber-200 text-amber-600'
                          }`}
                          value={order.status}
                          onChange={(e) => onUpdateOrderStatus(order.id, e.target.value as any)}
                        >
                          <option value="pending">Pending</option>
                          <option value="confirmed">Confirmed</option>
                          <option value="delivered">Delivered</option>
                          <option value="cancelled">Cancelled</option>
                        </select>
                     </td>
                   </tr>
                 ))}
               </tbody>
             </table>
             {orders.length === 0 && <div className="py-24 text-center"><p className="text-slate-300 font-black uppercase tracking-widest">No order logs found</p></div>}
           </div>
        </div>
      )}

      {activeTab === 'tabs' && (
        <div className="space-y-8 animate-in slide-in-from-bottom-4">
           <div className="flex flex-col sm:flex-row justify-between items-center bg-white p-6 rounded-[2rem] border border-slate-100 gap-4 shadow-sm">
              <div className="ml-4">
                <h2 className="text-xl font-black text-slate-900 uppercase tracking-tighter">System Navigation Manager</h2>
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Configure website categories</p>
              </div>
              <div className="flex gap-2 w-full sm:w-auto">
                 <button onClick={handleImportDefaultTabs} disabled={saving} className="px-6 py-4 bg-slate-100 text-slate-600 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-slate-200 transition-all">Reset Defaults</button>
                 <button onClick={() => { setIsCategoryFormOpen(true); setEditingCategoryId(null); setCategoryName(''); }} className="px-8 py-4 bg-blue-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl">Add New Tab</button>
              </div>
           </div>

           {isCategoryFormOpen && (
              <form onSubmit={handleCategorySubmit} className="bg-white rounded-[2.5rem] border-2 border-slate-100 p-10 shadow-2xl max-w-2xl mx-auto w-full animate-in zoom-in-95">
                 <h3 className="text-xl font-black text-slate-900 uppercase mb-8 text-center">{editingCategoryId ? 'Rename Tab' : 'Create Custom Tab'}</h3>
                 <input required className="w-full px-8 py-5 bg-slate-50 border border-slate-200 rounded-3xl outline-none font-black text-2xl text-center mb-8 focus:border-blue-500 transition-all shadow-inner" value={categoryName} onChange={e => setCategoryName(e.target.value)} placeholder="e.g. Virtual Visa" />
                 <div className="flex gap-4">
                    <button type="submit" disabled={saving} className="flex-1 py-5 bg-blue-600 text-white rounded-2xl font-black uppercase text-xs tracking-widest shadow-xl">Apply Changes</button>
                    <button type="button" onClick={() => setIsCategoryFormOpen(false)} className="px-10 py-5 bg-slate-100 text-slate-500 rounded-2xl font-black uppercase text-xs">Dismiss</button>
                 </div>
              </form>
           )}

           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {categories.map((cat, idx) => (
                 <div key={cat.id} className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm group hover:shadow-lg transition-all">
                    <div className="flex items-center justify-between mb-8">
                       <div className="flex items-center gap-4">
                          <div className="w-12 h-12 bg-blue-50 text-blue-600 rounded-2xl flex items-center justify-center text-lg font-black">{idx + 1}</div>
                          <h4 className="text-lg font-black text-slate-900 uppercase tracking-tight">{cat.name}</h4>
                       </div>
                    </div>
                    <div className="flex justify-between items-center pt-6 border-t border-slate-50">
                       <p className="text-[9px] font-black text-slate-300 uppercase tracking-widest">Global Asset Tab</p>
                       <div className="flex gap-3">
                          <button onClick={() => { setEditingCategoryId(cat.id); setCategoryName(cat.name); setIsCategoryFormOpen(true); }} className="p-3 text-slate-300 hover:text-blue-600 hover:bg-blue-50 rounded-xl transition-all"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M11 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-5M18.364 5.364a2.121 2.121 0 013 3L12 18l-4 1 1-4L18.364 5.364z" /></svg></button>
                          <button onClick={() => { if(confirm(`Delete "${cat.name}" tab?`)) onDeleteCategory(cat.id); }} className="p-3 text-slate-300 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6" /></svg></button>
                       </div>
                    </div>
                 </div>
              ))}
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Product, Order, CartItem, Category } from '../types';
import { supabase } from '../supabaseClient';
import { CATEGORIES as DEFAULT_CATEGORIES } from '../constants';

interface AdminPanelProps {
  products: Product[];
  orders: Order[];
  categories: Category[];
  onAddProduct: (p: Omit<Product, 'id'>) => void;
  onUpdateProduct: (id: string, p: Partial<Product>) => void;
  onDeleteProduct: (id: string) => void;
  onUpdateOrderStatus: (orderId: string, status: Order['status']) => void;
  onAddCategory: (name: string) => void;
  onUpdateCategory: (id: string, name: string) => void;
  onDeleteCategory: (id: string) => void;
  onBack: () => void;
}

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  products, 
  orders, 
  categories,
  onAddProduct, 
  onUpdateProduct,
  onDeleteProduct, 
  onUpdateOrderStatus,
  onAddCategory,
  onUpdateCategory,
  onDeleteCategory,
  onBack 
}) => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'inventory' | 'orders' | 'tabs'>('dashboard');
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [uploading, setUploading] = useState(false);
  const [saving, setSaving] = useState(false);

  const [isCategoryFormOpen, setIsCategoryFormOpen] = useState(false);
  const [editingCategoryId, setEditingCategoryId] = useState<string | null>(null);
  const [categoryName, setCategoryName] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const ownerPhotoUrl = "https://media.licdn.com/dms/image/v2/D5603AQF6FS5z4Ky4RQ/profile-displayphoto-shrink_200_200/B56Zu4YNm2G0AY-/0/1768324915128?e=2147483647&v=beta&t=_coKuJKl31AvjMDdGeLrigjfgyD8rtgblh-J_kP8Ruo";

  const [formData, setFormData] = useState({
    name: '',
    description: '',
    price: 0,
    category: '',
    image: '',
    stock: 10,
    rating: 5,
    isPublic: true
  });

  // Keep track of revenue and stats
  const stats = useMemo(() => {
    const totalRev = orders.reduce((sum, o) => (o.status === 'confirmed' || o.status === 'delivered') ? sum + o.total : sum, 0);
    const pending = orders.filter(o => o.status === 'pending').length;
    return { totalRev, pending };
  }, [orders]);

  // Set default category for product form
  useEffect(() => {
    if (!formData.category) {
      if (categories.length > 0) {
        setFormData(prev => ({ ...prev, category: categories[0].name }));
      } else {
        setFormData(prev => ({ ...prev, category: DEFAULT_CATEGORIES[1] }));
      }
    }
  }, [categories, isFormOpen]);

  const handleImportDefaultTabs = async () => {
    if (!confirm("Add default categories to database? (Apple, iCloud, Gmail etc.)")) return;
    setSaving(true);
    try {
      const tabsToImport = DEFAULT_CATEGORIES.filter(c => c !== 'All');
      for (const tabName of tabsToImport) {
        // Only add if it doesn't already exist in the prop categories
        if (!categories.find(c => c.name === tabName)) {
          await onAddCategory(tabName);
        }
      }
      alert("✅ Default tabs have been synced to the database!");
    } catch (e: any) {
      alert("❌ Import failed: " + (e.message || "Connection error"));
    } finally {
      setSaving(false);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    try {
      setUploading(true);
      if (!e.target.files?.[0]) return;
      const file = e.target.files[0];
      const fileExt = file.name.split('.').pop();
      const filePath = `product-images/${Math.random()}.${fileExt}`;
      const { error: uploadError } = await supabase.storage.from('products').upload(filePath, file);
      if (uploadError) throw uploadError;
      const { data } = supabase.storage.from('products').getPublicUrl(filePath);
      if (data) setFormData(prev => ({ ...prev, image: data.publicUrl }));
    } catch (error: any) {
      alert("❌ Upload error: " + error.message);
    } finally {
      setUploading(false);
    }
  };

  const handleEditProduct = (product: Product) => {
    setEditingId(product.id);
    setFormData({
      name: product.name,
      description: product.description,
      price: product.price,
      category: product.category,
      image: product.image,
      stock: product.stock,
      rating: product.rating,
      isPublic: product.isPublic !== undefined ? product.isPublic : true
    });
    setIsFormOpen(true);
  };

  const handleSubmitProduct = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);
    try {
      if (editingId) { await onUpdateProduct(editingId, formData); }
      else { await onAddProduct(formData); }
      resetForm();
      alert("✅ Product saved!");
    } catch (e: any) {
      alert("❌ Failed to save product. Check database connection.");
    } finally { setSaving(false); }
  };

  const handleCategorySubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!categoryName.trim()) return;
    setSaving(true);
    try {
      if (editingCategoryId) { 
        await onUpdateCategory(editingCategoryId, categoryName.trim()); 
        alert("✅ Tab updated!");
      } else { 
        await onAddCategory(categoryName.trim()); 
        alert("✅ New Tab added successfully!");
      }
      setCategoryName('');
      setEditingCategoryId(null);
      setIsCategoryFormOpen(false);
    } catch (e: any) {
      alert("❌ Tab creation failed: " + (e.message || "Unknown error"));
    } finally {
      setSaving(false);
    }
  };

  const resetForm = () => {
    setIsFormOpen(false);
    setEditingId(null);
    setFormData({ 
      name: '', description: '', price: 0, 
      category: categories.length > 0 ? categories[0].name : DEFAULT_CATEGORIES[1], 
      image: '', stock: 10, rating: 5, isPublic: true 
    });
  };

  return (
    <div className="animate-in fade-in duration-700 max-w-7xl mx-auto space-y-8 pb-24">
      {/* HEADER */}
      <div className="bg-[#0F172A] rounded-[2rem] md:rounded-[3rem] p-8 md:p-12 shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 right-0 w-64 h-64 bg-blue-600/10 blur-[80px] -mr-32 -mt-32"></div>
        <div className="relative z-10 flex flex-col md:flex-row justify-between items-center gap-8">
          <div className="flex items-center gap-6">
            <div className="w-24 h-24 rounded-full border-4 border-white/10 overflow-hidden shadow-2xl">
              <img src={ownerPhotoUrl} alt="Admin" className="w-full h-full object-cover" />
            </div>
            <div>
              <h1 className="text-3xl md:text-4xl font-black text-white uppercase tracking-tighter">Control Center</h1>
              <p className="text-xs font-black text-blue-400 uppercase tracking-[0.3em] mt-2">Administrator: Mehedi Hasan</p>
            </div>
          </div>
          <button onClick={onBack} className="px-10 py-4 bg-white/5 hover:bg-red-500/20 text-white border border-white/10 rounded-2xl font-black text-xs uppercase tracking-widest transition-all shadow-xl backdrop-blur-md">
            Exit Admin
          </button>
        </div>
      </div>

      {/* STATS */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        {[
          { label: 'Revenue', value: `$${stats.totalRev.toFixed(2)}`, icon: 'M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2', color: 'text-emerald-500', bg: 'bg-emerald-50' },
          { label: 'Pending', value: stats.pending, icon: 'M12 8v4l3 3', color: 'text-amber-500', bg: 'bg-amber-50' },
          { label: 'Products', value: products.length, icon: 'M20 7l-8-4-8 4', color: 'text-indigo-500', bg: 'bg-indigo-50' },
          { label: 'Tabs', value: categories.length, icon: 'M7 7h.01M7 3h5', color: 'text-blue-500', bg: 'bg-blue-50' }
        ].map((stat, i) => (
          <div key={i} className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm flex items-center justify-between">
            <div className="space-y-1">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{stat.label}</p>
              <h3 className="text-2xl font-black text-slate-900">{stat.value}</h3>
            </div>
            <div className={`w-14 h-14 ${stat.bg} ${stat.color} rounded-2xl flex items-center justify-center`}>
              <svg className="w-7 h-7" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d={stat.icon} /></svg>
            </div>
          </div>
        ))}
      </div>

      {/* NAV */}
      <div className="flex justify-center">
        <div className="bg-white p-1.5 rounded-full border border-slate-200 flex flex-wrap gap-1 shadow-lg">
          {[
            { id: 'dashboard', label: 'Overview' },
            { id: 'inventory', label: 'Products' },
            { id: 'orders', label: 'Live Orders' },
            { id: 'tabs', label: 'Tab Manager' }
          ].map(tab => (
            <button 
              key={tab.id} 
              onClick={() => setActiveTab(tab.id as any)} 
              className={`px-10 py-3 rounded-full text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === tab.id ? 'bg-[#0F172A] text-white shadow-xl scale-105' : 'text-slate-500 hover:bg-slate-50'}`}
            >
              {tab.label}
            </button>
          ))}
        </div>
      </div>

      {/* DASHBOARD */}
      {activeTab === 'dashboard' && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 animate-in slide-in-from-bottom-4">
          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100">
            <h3 className="text-xl font-black text-slate-900 uppercase tracking-tight mb-8">Recent Activity</h3>
            <div className="space-y-4">
              {orders.slice(0, 5).map(order => (
                <div key={order.id} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl">
                  <div>
                    <p className="text-xs font-black text-slate-900">Order #{order.id.slice(0, 8)}</p>
                    <p className="text-[10px] font-bold text-slate-400 uppercase">{order.fullName}</p>
                  </div>
                  <span className={`text-[8px] font-black uppercase px-2 py-0.5 rounded-md ${order.status === 'delivered' ? 'bg-green-100 text-green-600' : 'bg-amber-100 text-amber-600'}`}>
                    {order.status}
                  </span>
                </div>
              ))}
              {orders.length === 0 && <p className="text-center py-10 text-slate-300 font-black uppercase tracking-widest">No orders yet</p>}
            </div>
          </div>
          <div className="bg-slate-900 p-8 rounded-[2.5rem] text-white flex flex-col justify-center items-center text-center shadow-2xl">
             <div className="w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center mb-6 shadow-xl">
                <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" /></svg>
             </div>
             <h3 className="text-2xl font-black uppercase tracking-tighter">Business Health</h3>
             <p className="text-slate-400 text-sm font-bold mt-2">Manage all digital assets efficiently.</p>
          </div>
        </div>
      )}

      {/* INVENTORY */}
      {activeTab === 'inventory' && (
        <div className="space-y-8 animate-in slide-in-from-bottom-4">
          <div className="flex flex-col sm:flex-row justify-between items-center bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm gap-4">
             <div className="ml-4">
               <h2 className="text-xl font-black text-slate-900 uppercase tracking-tighter">Inventory</h2>
               <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Digital Service Catalog</p>
             </div>
             <button onClick={() => { resetForm(); setIsFormOpen(true); }} className="w-full sm:w-auto px-10 py-4 bg-blue-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl hover:bg-slate-900 transition-all">+ Add New Product</button>
          </div>

          {isFormOpen && (
            <div className="bg-white rounded-[2.5rem] border-2 border-slate-100 p-8 md:p-12 shadow-2xl animate-in zoom-in-95">
              <form onSubmit={handleSubmitProduct} className="space-y-10">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                  <div className="space-y-6">
                    <div>
                      <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-2">Name</label>
                      <input required type="text" className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl font-black text-sm outline-none focus:border-blue-500 transition-colors" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
                    </div>
                    <div>
                      <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-2">Description</label>
                      <textarea required className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold text-sm outline-none focus:border-blue-500 min-h-[140px]" value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} />
                    </div>
                  </div>
                  <div className="space-y-6">
                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-2">Price ($)</label>
                        <input required type="number" step="0.01" className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl font-black" value={formData.price} onChange={e => setFormData({...formData, price: parseFloat(e.target.value)})} />
                      </div>
                      <div>
                        <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-2">Stock</label>
                        <input required type="number" className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl font-black" value={formData.stock} onChange={e => setFormData({...formData, stock: parseInt(e.target.value)})} />
                      </div>
                    </div>
                    <div>
                      <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-2">Category (Select Tab)</label>
                      <select className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl font-black text-sm" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                        {categories.length === 0 && <option value={DEFAULT_CATEGORIES[1]}>Create a tab first (Currently using fallback)</option>}
                        {categories.map(cat => <option key={cat.id} value={cat.name}>{cat.name}</option>)}
                      </select>
                    </div>
                    <div className="space-y-3">
                        <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Image</label>
                        <div className="flex gap-4">
                           <div className="w-16 h-16 bg-slate-100 rounded-xl overflow-hidden flex-shrink-0 border border-slate-200">
                              {formData.image && <img src={formData.image} className="w-full h-full object-cover" />}
                           </div>
                           <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileUpload} />
                           <button type="button" onClick={() => fileInputRef.current?.click()} className="flex-1 py-4 bg-slate-100 text-slate-600 rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-blue-600 hover:text-white transition-all">
                              {uploading ? 'Uploading...' : 'Upload Media'}
                           </button>
                        </div>
                    </div>
                  </div>
                </div>
                <div className="flex gap-4 pt-6 border-t border-slate-100">
                  <button type="submit" disabled={saving || uploading} className="flex-1 py-5 bg-blue-600 text-white rounded-2xl font-black uppercase text-xs tracking-widest shadow-2xl hover:bg-slate-900 transition-all">{saving ? 'Processing...' : (editingId ? 'Confirm Updates' : 'Publish Product')}</button>
                  <button type="button" onClick={resetForm} className="px-12 py-5 bg-slate-100 text-slate-500 rounded-2xl font-black uppercase text-xs hover:bg-red-50 hover:text-red-500 transition-all">Cancel</button>
                </div>
              </form>
            </div>
          )}

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
               {products.map(p => (
                 <div key={p.id} className="bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm flex gap-5 group hover:shadow-xl transition-all">
                    <img src={p.image} className="w-20 h-20 rounded-2xl object-cover border border-slate-50 shadow-sm flex-shrink-0" />
                    <div className="flex-1 overflow-hidden flex flex-col justify-between">
                       <div>
                         <h4 className="font-black text-slate-900 uppercase tracking-tight text-xs truncate">{p.name}</h4>
                         <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest mt-1">${p.price.toFixed(2)}</p>
                       </div>
                       <div className="flex gap-2 mt-4">
                          <button onClick={() => handleEditProduct(p)} className="p-2 bg-slate-50 text-slate-400 hover:bg-blue-600 hover:text-white rounded-xl transition-all">
                            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M11 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-5M18.364 5.364a2.121 2.121 0 013 3L12 18l-4 1 1-4L18.364 5.364z" /></svg>
                          </button>
                          <button onClick={() => { if(confirm('Delete?')) onDeleteProduct(p.id); }} className="p-2 bg-slate-50 text-slate-400 hover:bg-red-600 hover:text-white rounded-xl transition-all">
                            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6" /></svg>
                          </button>
                       </div>
                    </div>
                 </div>
               ))}
          </div>
        </div>
      )}

      {/* ORDERS */}
      {activeTab === 'orders' && (
        <div className="animate-in slide-in-from-bottom-4 space-y-8">
           <div className="bg-white rounded-[2.5rem] border border-slate-100 overflow-hidden shadow-sm">
             <table className="w-full text-left">
               <thead className="bg-[#0F172A] border-b border-slate-800">
                 <tr>
                   <th className="px-8 py-6 text-[9px] font-black text-slate-400 uppercase tracking-widest">Order ID</th>
                   <th className="px-8 py-6 text-[9px] font-black text-slate-400 uppercase tracking-widest">Customer</th>
                   <th className="px-8 py-6 text-[9px] font-black text-slate-400 uppercase tracking-widest text-center">Amount</th>
                   <th className="px-8 py-6 text-[9px] font-black text-slate-400 uppercase tracking-widest text-right">Action</th>
                 </tr>
               </thead>
               <tbody className="divide-y divide-slate-50">
                 {orders.map(order => (
                   <tr key={order.id} className="hover:bg-slate-50/50">
                     <td className="px-8 py-6 font-mono text-xs text-slate-900">#{order.id.slice(0, 8)}</td>
                     <td className="px-8 py-6 text-xs font-black text-slate-900 uppercase">{order.fullName}</td>
                     <td className="px-8 py-6 text-center text-sm font-black text-slate-900">${order.total.toFixed(2)}</td>
                     <td className="px-8 py-6 text-right">
                        <select 
                          className="px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest border border-slate-200"
                          value={order.status}
                          onChange={(e) => onUpdateOrderStatus(order.id, e.target.value as any)}
                        >
                          <option value="pending">Pending</option>
                          <option value="confirmed">Confirmed</option>
                          <option value="delivered">Delivered</option>
                          <option value="cancelled">Cancelled</option>
                        </select>
                     </td>
                   </tr>
                 ))}
               </tbody>
             </table>
             {orders.length === 0 && <div className="py-20 text-center text-slate-300 font-black uppercase tracking-widest">No order logs</div>}
           </div>
        </div>
      )}

      {/* TAB MANAGER */}
      {activeTab === 'tabs' && (
        <div className="space-y-8 animate-in slide-in-from-bottom-4">
           <div className="flex flex-col sm:flex-row justify-between items-center bg-white p-8 rounded-[2rem] border border-slate-100 gap-6 shadow-sm">
              <div className="ml-4">
                <h2 className="text-xl font-black text-slate-900 uppercase tracking-tighter">System Tabs (Categories)</h2>
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Manage website navigation and filtering</p>
              </div>
              <div className="flex gap-3 w-full sm:w-auto">
                 <button onClick={handleImportDefaultTabs} disabled={saving} className="px-6 py-4 bg-slate-100 text-slate-600 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-slate-200 transition-all">Import Default Tabs</button>
                 <button onClick={() => { setIsCategoryFormOpen(true); setEditingCategoryId(null); setCategoryName(''); }} className="px-10 py-4 bg-blue-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl hover:bg-slate-900 transition-all">Add New Tab</button>
              </div>
           </div>

           {isCategoryFormOpen && (
              <form onSubmit={handleCategorySubmit} className="bg-white rounded-[2.5rem] border-2 border-slate-100 p-10 shadow-2xl max-w-2xl mx-auto w-full animate-in zoom-in-95">
                 <h3 className="text-xl font-black text-slate-900 uppercase mb-8 text-center">{editingCategoryId ? 'Rename Tab' : 'Create Custom Tab'}</h3>
                 <input 
                   required 
                   className="w-full px-8 py-5 bg-slate-50 border border-slate-200 rounded-3xl outline-none font-black text-2xl text-center mb-8 focus:border-blue-500 transition-all shadow-inner" 
                   value={categoryName} 
                   onChange={e => setCategoryName(e.target.value)} 
                   placeholder="e.g. Virtual Visa" 
                   autoFocus
                 />
                 <div className="flex gap-4">
                    <button type="submit" disabled={saving} className="flex-1 py-5 bg-blue-600 text-white rounded-2xl font-black uppercase text-xs tracking-widest shadow-xl hover:bg-slate-900 transition-all">
                      {saving ? 'Saving...' : 'Confirm Tab'}
                    </button>
                    <button type="button" onClick={() => setIsCategoryFormOpen(false)} className="px-10 py-5 bg-slate-100 text-slate-500 rounded-2xl font-black uppercase text-xs hover:bg-red-50 hover:text-red-500 transition-all">
                      Cancel
                    </button>
                 </div>
              </form>
           )}

           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {categories.map((cat, idx) => (
                 <div key={cat.id} className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm group hover:shadow-lg transition-all">
                    <div className="flex items-center justify-between mb-8">
                       <div className="flex items-center gap-4">
                          <div className="w-12 h-12 bg-blue-50 text-blue-600 rounded-2xl flex items-center justify-center text-lg font-black">{idx + 1}</div>
                          <h4 className="text-lg font-black text-slate-900 uppercase tracking-tight">{cat.name}</h4>
                       </div>
                    </div>
                    <div className="flex justify-between items-center pt-6 border-t border-slate-50">
                       <p className="text-[9px] font-black text-slate-300 uppercase tracking-widest">Status: Active</p>
                       <div className="flex gap-4">
                          <button onClick={() => { setEditingCategoryId(cat.id); setCategoryName(cat.name); setIsCategoryFormOpen(true); }} className="text-slate-300 hover:text-blue-600 transition-colors">
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M11 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-5M18.364 5.364a2.121 2.121 0 013 3L12 18l-4 1 1-4L18.364 5.364z" /></svg>
                          </button>
                          <button onClick={() => { if(confirm(`Delete "${cat.name}" tab?`)) onDeleteCategory(cat.id); }} className="text-slate-300 hover:text-red-600 transition-colors">
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6" /></svg>
                          </button>
                       </div>
                    </div>
                 </div>
              ))}
              {categories.length === 0 && (
                <div className="col-span-full py-24 text-center border-2 border-dashed border-slate-200 rounded-[3rem] bg-white">
                  <p className="text-slate-400 font-black uppercase tracking-widest mb-6">Database Categories Empty</p>
                  <button onClick={handleImportDefaultTabs} className="px-10 py-4 bg-slate-900 text-white rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-blue-600 transition-all">Import Default Set</button>
                </div>
              )}
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Product, Order, CartItem, Category } from '../types';
import { supabase } from '../supabaseClient';
import { CATEGORIES as DEFAULT_CATEGORIES } from '../constants';

interface AdminPanelProps {
  products: Product[];
  orders: Order[];
  categories: Category[];
  onAddProduct: (p: Omit<Product, 'id'>) => void;
  onUpdateProduct: (id: string, p: Partial<Product>) => void;
  onDeleteProduct: (id: string) => void;
  onUpdateOrderStatus: (orderId: string, status: Order['status']) => void;
  onAddCategory: (name: string) => void;
  onUpdateCategory: (id: string, name: string) => void;
  onDeleteCategory: (id: string) => void;
  onBack: () => void;
}

export const AdminPanel: React.FC<AdminPanelProps> = ({ 
  products, 
  orders, 
  categories,
  onAddProduct, 
  onUpdateProduct,
  onDeleteProduct, 
  onUpdateOrderStatus,
  onAddCategory,
  onUpdateCategory,
  onDeleteCategory,
  onBack 
}) => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'inventory' | 'orders' | 'tabs'>('dashboard');
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [uploading, setUploading] = useState(false);
  const [saving, setSaving] = useState(false);

  const [isCategoryFormOpen, setIsCategoryFormOpen] = useState(false);
  const [editingCategoryId, setEditingCategoryId] = useState<string | null>(null);
  const [categoryName, setCategoryName] = useState('');

  // Order Detail State
  const [selectedAdminOrder, setSelectedAdminOrder] = useState<Order | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const ownerPhotoUrl = "https://media.licdn.com/dms/image/v2/D5603AQF6FS5z4Ky4RQ/profile-displayphoto-shrink_200_200/B56Zu4YNm2G0AY-/0/1768324915128?e=2147483647&v=beta&t=_coKuJKl31AvjMDdGeLrigjfgyD8rtgblh-J_kP8Ruo";

  const [formData, setFormData] = useState({
    name: '',
    description: '',
    price: 0,
    category: '',
    image: '',
    stock: 10,
    rating: 5,
    isPublic: true
  });

  const stats = useMemo(() => {
    const totalRev = orders.reduce((sum, o) => (o.status === 'confirmed' || o.status === 'delivered') ? sum + o.total : sum, 0);
    const pending = orders.filter(o => o.status === 'pending').length;
    return { totalRev, pending };
  }, [orders]);

  useEffect(() => {
    if (!formData.category) {
      if (categories.length > 0) {
        setFormData(prev => ({ ...prev, category: categories[0].name }));
      } else {
        setFormData(prev => ({ ...prev, category: DEFAULT_CATEGORIES[1] }));
      }
    }
  }, [categories, isFormOpen]);

  const handleImportDefaultTabs = async () => {
    if (!confirm("Add default categories to database? (Apple, iCloud, Gmail etc.)")) return;
    setSaving(true);
    try {
      const tabsToImport = DEFAULT_CATEGORIES.filter(c => c !== 'All');
      for (const tabName of tabsToImport) {
        if (!categories.find(c => c.name === tabName)) {
          await onAddCategory(tabName);
        }
      }
      alert("✅ Default tabs have been synced to the database!");
    } catch (e: any) {
      alert("❌ Import failed: " + (e.message || "Connection error"));
    } finally {
      setSaving(false);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    try {
      setUploading(true);
      if (!e.target.files?.[0]) return;
      const file = e.target.files[0];
      const fileExt = file.name.split('.').pop();
      const filePath = `product-images/${Math.random()}.${fileExt}`;
      const { error: uploadError } = await supabase.storage.from('products').upload(filePath, file);
      if (uploadError) throw uploadError;
      const { data } = supabase.storage.from('products').getPublicUrl(filePath);
      if (data) setFormData(prev => ({ ...prev, image: data.publicUrl }));
    } catch (error: any) {
      alert("❌ Upload error: " + error.message);
    } finally {
      setUploading(false);
    }
  };

  const handleEditProduct = (product: Product) => {
    setEditingId(product.id);
    setFormData({
      name: product.name,
      description: product.description,
      price: product.price,
      category: product.category,
      image: product.image,
      stock: product.stock,
      rating: product.rating,
      isPublic: product.isPublic !== undefined ? product.isPublic : true
    });
    setIsFormOpen(true);
  };

  const handleSubmitProduct = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);
    try {
      if (editingId) { await onUpdateProduct(editingId, formData); }
      else { await onAddProduct(formData); }
      resetForm();
      alert("✅ Product saved!");
    } catch (e: any) {
      alert("❌ Failed to save product.");
    } finally { setSaving(false); }
  };

  const handleCategorySubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!categoryName.trim()) return;
    setSaving(true);
    try {
      if (editingCategoryId) { 
        await onUpdateCategory(editingCategoryId, categoryName.trim()); 
        alert("✅ Tab updated!");
      } else { 
        await onAddCategory(categoryName.trim()); 
        alert("✅ New Tab added successfully!");
      }
      setCategoryName('');
      setEditingCategoryId(null);
      setIsCategoryFormOpen(false);
    } catch (e: any) {
      alert("❌ Tab creation failed.");
    } finally {
      setSaving(false);
    }
  };

  const resetForm = () => {
    setIsFormOpen(false);
    setEditingId(null);
    setFormData({ 
      name: '', description: '', price: 0, 
      category: categories.length > 0 ? categories[0].name : DEFAULT_CATEGORIES[1], 
      image: '', stock: 10, rating: 5, isPublic: true 
    });
  };

  const getStatusColor = (status: Order['status']) => {
    switch(status) {
      case 'delivered': return 'bg-green-100 text-green-600 border-green-200';
      case 'confirmed': return 'bg-blue-100 text-blue-600 border-blue-200';
      case 'cancelled': return 'bg-red-100 text-red-600 border-red-200';
      default: return 'bg-amber-100 text-amber-600 border-amber-200';
    }
  };

  return (
    <div className="animate-in fade-in duration-700 max-w-7xl mx-auto space-y-8 pb-24">
      {/* HEADER */}
      <div className="bg-[#0F172A] rounded-[2rem] md:rounded-[3rem] p-8 md:p-12 shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 right-0 w-64 h-64 bg-blue-600/10 blur-[80px] -mr-32 -mt-32"></div>
        <div className="relative z-10 flex flex-col md:flex-row justify-between items-center gap-8">
          <div className="flex items-center gap-6">
            <div className="w-24 h-24 rounded-full border-4 border-white/10 overflow-hidden shadow-2xl">
              <img src={ownerPhotoUrl} alt="Admin" className="w-full h-full object-cover" />
            </div>
            <div>
              <h1 className="text-3xl md:text-4xl font-black text-white uppercase tracking-tighter">Control Center</h1>
              <p className="text-xs font-black text-blue-400 uppercase tracking-[0.3em] mt-2">Master Administrator: Mehedi Hasan</p>
            </div>
          </div>
          <button onClick={onBack} className="px-10 py-4 bg-white/5 hover:bg-red-500/20 text-white border border-white/10 rounded-2xl font-black text-xs uppercase tracking-widest transition-all shadow-xl backdrop-blur-md">
            Exit Admin
          </button>
        </div>
      </div>

      {/* QUICK STATS */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        {[
          { label: 'Revenue', value: `$${stats.totalRev.toFixed(2)}`, icon: 'M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2', color: 'text-emerald-500', bg: 'bg-emerald-50' },
          { label: 'Awaiting', value: stats.pending, icon: 'M12 8v4l3 3', color: 'text-amber-500', bg: 'bg-amber-50' },
          { label: 'Stock Units', value: products.length, icon: 'M20 7l-8-4-8 4', color: 'text-indigo-500', bg: 'bg-indigo-50' },
          { label: 'Active Tabs', value: categories.length, icon: 'M7 7h.01M7 3h5', color: 'text-blue-500', bg: 'bg-blue-50' }
        ].map((stat, i) => (
          <div key={i} className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm flex items-center justify-between">
            <div className="space-y-1">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{stat.label}</p>
              <h3 className="text-2xl font-black text-slate-900">{stat.value}</h3>
            </div>
            <div className={`w-14 h-14 ${stat.bg} ${stat.color} rounded-2xl flex items-center justify-center`}>
              <svg className="w-7 h-7" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d={stat.icon} /></svg>
            </div>
          </div>
        ))}
      </div>

      {/* NAVIGATION TABS */}
      <div className="flex justify-center">
        <div className="bg-white p-1.5 rounded-full border border-slate-200 flex flex-wrap gap-1 shadow-lg">
          {[
            { id: 'dashboard', label: 'Overview' },
            { id: 'inventory', label: 'Products' },
            { id: 'orders', label: 'Order Manager' },
