          {/* The "S" */}
          <path 
            d="M68 35 H55 V41 H65 C67 41 68 42 68 44 C68 46 67 47 65 47 H58 C54 47 52 49 52 53 C52 57 54 59 58 59 H71 V53 H61 C59 53 58 52 58 50 C58 48 59 47 61 47 H68 C72 47 74 45 74 41 C74 37 72 35 68 35Z" 
            fill="#84CC16" 
