interface ProductDetailProps {
  product: Product;
  onAddToCart: (p: Product, q: number) => void;
  onBack: () => void;
}

export const ProductDetail: React.FC<ProductDetailProps> = ({ product, onAddToCart, onBack }) => {
  const [quantity, setQuantity] = useState(1);

  const handleQuantityChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let val = parseInt(e.target.value);
    if (e.target.value === "") {
      setQuantity(0);
      return;
    }
    if (!isNaN(val)) {
      // Logic: Cannot enter more than available stock
      if (val > product.stock) {
        val = product.stock;
      }
      if (val < 1) val = 1;
      setQuantity(val);
    }
  };

  const handleBlur = () => {
    if (quantity < 1) setQuantity(1);
    if (quantity > product.stock) setQuantity(product.stock);
  };

  // Pricing Logic
  const unitPrice = product.price;
  const isBulkDiscountEligible = quantity >= 100;
  const subtotal = unitPrice * quantity;
  const discount = isBulkDiscountEligible ? subtotal * 0.05 : 0;
  const finalTotal = subtotal - discount;
  const effectiveUnitPrice = isBulkDiscountEligible ? unitPrice * 0.95 : unitPrice;

  return (
